// 単語の豆知識: { 見出し語: 語源や TOEIC での出方など、覚えるきっかけになる一言 }
// 無い単語は何も表示しない。回答後の解説で vocab-drill.js が見出し語(RAW_WORDS の w)で引く。
const WORD_TIPS = {
  "profession": "profess（公言する）の名詞形で、「公に表明した仕事」が原義。professional（専門家）や profess との形の対応で覚えやすい。",
  "related": "relate はラテン語で「運び戻す」＝結びつける。be related to ~ の形でよく使われ、前置詞 to を問う設問に注意。",
  "consider": "consider は動名詞を目的語にとる動詞で、consider doing の形（×consider to do）。Part 5 の語法問題で狙われやすい。",
  "suitable": "suit（似合う）+ -able で「合うことができる」。suitable for ~ の形でよく使われ、前置詞 for との組み合わせで覚える。",
  "sufficient": "sub（下から）+ ficere（作る）＝下から満たす、が語源。sufficient funds / time の形や、反対語 insufficient とセットで覚える。",
  "declare": "de-（完全に）+ clarus（明らかな）で、clear と同系。空港の税関で「申告する」意味でも出てくる。",
  "encounter": "en-（中に）+ contra（反対に）で、向かい合う意。encounter difficulties / problems の形でよく使われる。",
  "liaison": "フランス語由来で「結びつけ」の意。a liaison between A and B の形で、部署間・組織間の連絡役を表す。綴りの ia に注意。",
  "intense": "in-（内へ）+ tendere（張る）で、ぴんと張りつめた→激しい。intense competition の形でよく使われる。形が近い intensive（集中的な）と区別する。",
  "supplier": "supply（供給する）に人を表す -er が付いた形。supplier と並んで vendor, manufacturer など取引先を指す語も出やすい。",
  "exposure": "ex-（外に）+ ponere（置く）＝外に置く→さらす、が語源。exposure to ~ の形でよく使われ、前置詞 to とセットで覚える。",
  "year-round": "round は「ぐるっと一周」の意で、year-round は一年を通して。形容詞・副詞の両方で使え、open year-round などの形で見かける。",
  "surge": "ラテン語 surgere（立ち上がる）が語源で、波が盛り上がるイメージ。a surge in demand の形でも使われ、動詞・名詞の両方がある。",
  "comeback": "動詞句 come back（戻る）が名詞になった形。make a comeback（復活する・返り咲く）の形で覚えると使いやすい。",
  "mindfulness": "mindful（心を向けている）+ -ness で名詞化した語。health や well-being 系の記事・広告文脈で見かけやすい。",
  "regain control": "re-（再び）+ gain（得る）で、取り戻す。regain control of ~ の形でよく使われ、類似語の recover との言い換えにも注意。",
  "license": "ラテン語 licere（許される）が語源。米式では動詞も名詞も license で、英式の名詞は licence。be licensed to do の形でよく使われる。",
  "utility bill": "utility は use と同系で、電気・ガス・水道など生活に役立つ公共サービスのこと。請求書や住所関係の Part 7 で出やすい。",
  "driver": "drive（駆り立てる）から、車の運転手だけでなく「原動力・要因」の意味もある。a key driver of growth の形で出やすい。",
  "donate": "ラテン語 donare（贈る）が語源で、名詞は donation、寄付者は donor。donate A to B の形でよく使われる。",
  "clothing": "cloth(布)+-ing で「布製品の総称」。clothes(個々の衣服・複数形)と違い不可算で、clothing store や clothing line の形で出やすい。",
  "production": "pro-(前へ)+duce(導く)で「前へ導き出すこと」。production line、production schedule の形でよく使われ、product や productivity と並んで出やすい。",
  "destination": "de-(完全に)+stinare(固定する)で「行き先として定めた場所」。tourist destination や travel destination など、旅行・交通の文脈で出やすい。",
  "contemporary": "con-(共に)+tempor(時)で「同じ時代の」。contemporary art のように使う。temporary(一時的な)と綴りが似るので区別して覚えたい。",
  "overview": "over(上から)+view(見る)で、全体を見渡した「概要」。provide an overview of ~ の形でよく使われ、会議や企画の説明文で出やすい。",
  "combined": "com-(共に)+bin(二つ)で「二つを合わせた」。combined effort や combined total のように、名詞の前に置く形が出やすい。",
  "discard": "dis-(離れて)+card(カード)で、トランプの手札を捨てる意味が出発点。注意書きの discard after use(使用後は破棄)の形で出やすい。",
  "exhibition": "ex-(外へ)+hibit(持つ)で「外へ持ち出して見せる」。動詞・名詞の exhibit と同じ仲間で、art exhibition や on exhibition の形で出やすい。",
  "anniversary": "ann(年)+vers(めぐる)で「年がめぐってくる日」。annual(年1回の)と同じ語根。celebrate the 10th anniversary のような形でよく使われる。",
  "substantial": "sub-(下に)+stance(立つもの)で、土台がしっかりしている→「相当な」。substantial increase や substantial amount の形で出やすい。",
  "carbon footprint": "footprint(足跡)の比喩で、活動が環境に残す CO2 排出量のこと。reduce our carbon footprint の形で、環境対策の記事・告知に出やすい。",
  "precaution": "pre-(前もって)+caution(用心)で「事前の用心」。take precautions や safety precautions の形でよく使われ、注意喚起の文に出やすい。",
  "culinary": "ラテン語 culina(台所)に由来し、料理に関する分野で使う形容詞。culinary arts、culinary school など、レストランや料理教室の文脈で出やすい。",
  "unwind": "un-(逆に)+wind(巻く)で、巻いたものをほどく→緊張がほどける。リゾートやスパの広告で relax と並んで出やすく、wind は「ワインド」と読む。",
  "isolated": "イタリア語 isola(島)系の語に由来し、島のように切り離されたイメージ。isolated area や isolated case の形で、人里離れた場所の描写に出やすい。",
  "excursion": "ex-(外へ)+curs(走る)で「外へ走り出ること」。course や current と同じ語根。day excursion など、観光や社内旅行の案内文で出やすい。",
  "authentication": "authentic(本物の)の名詞形で「本物だと確かめること」。ログインやセキュリティの文脈で、two-factor authentication の形で出やすい。",
  "calibrate": "目盛りや数値を基準に合わせて調整する動詞。calibrate the equipment の形で、機械・測定機器の保守や点検の文脈で出やすい。",
  "informal": "in-(否定)+formal(正式な)で「形式張らない」。informal meeting や informal dress のように、会議や服装規定の話題で formal とセットで出やすい。",
  "contact": "con-(共に)+tact(触れる)で「接触する」。他動詞なので contact to ではなく、contact a supervisor のように前置詞なしで目的語を取る。",
  "prove": "ラテン語 probare(試す・確かめる)が語源で、probe や approve の仲間。prove to be 〜 や prove successful のように補語を伴う形が基本。",
  "carefully": "careful の副詞形。空所が動詞の前後なら carefully、名詞の前なら careful と、Part 5 では品詞で見分ける。carefully read / review などと相性がよい。",
  "enough": "副詞の enough は形容詞・副詞の後ろに置く(big enough)のが語順。名詞の前なら enough time のように形容詞用法。enough to do が続く形も多い。",
  "assistance": "ad-(そばに)+sistere(立つ)で、そばに立って助けること。assist と同根。不可算名詞なので an assistance とはせず、need assistance / financial assistance の形で使う。",
  "client": "ラテン語 cliens(庇護を求めて頼る人)が由来。弁護士や会計士など専門的サービスを受ける相手を指すことが多く、店で買う customer とは少しニュアンスが違う。",
  "benefit": "bene-(良い)+fact(行う)で、良いことをする→利益。複数形 benefits は「福利厚生・手当」の意味になり、求人広告の health benefits が典型。benefit from 〜 も重要。",
  "supervisor": "super-(上から)+vis(見る)で、上から見守る人。動詞 supervise や名詞 supervision と品詞を区別したい。報告先を示す report to a supervisor の形も押さえる。",
  "amazing": "amaze(驚かせる)の -ing 形。ものが主語・修飾なら amazing、驚く側の人なら amazed(be amazed at 〜)と、分詞形容詞の使い分けが問われる。",
  "certainly": "certain(確かな)の副詞形。文中では「確かに」の強調だが、会話では Certainly. の一言で「かしこまりました」と依頼を快諾する返事にもなる。",
  "recommend": "recommend doing か recommend that 主語+原形の形を取り、recommend to do とは言えない。commend(ほめる)の仲間で、ほめて人に推すイメージ。",
  "period": "ギリシャ語 peri-(周り)+hodos(道)から、ぐるっと一周する道のり→期間。trial period / grace period / for a period of 〜 の形で使う。",
  "trade": "trade show(見本市)や trade agreement(貿易協定)など複合名詞でよく見る。動詞では trade in 〜 が「〜を下取りに出す」、trade with 〜 が「〜と取引する」。",
  "sign": "ラテン語 signum(しるし)が語源で、design や signal の仲間。署名は自分のしるしを書くこと。sign up for 〜(〜に申し込む)の句動詞も重要。",
  "reschedule": "re-(再び)+schedule。reschedule A for B(AをBに変更する)の形を取る。postpone は延期だけだが、reschedule は前倒しも含めた日程変更。",
  "install": "in-(中に)+stall(席・置き場)で、所定の場所に据え付ける→取りつける。名詞形 installation(設置)と動詞形の品詞の違いを区別しておく。",
  "neighborhood": "neighbor(隣人)+-hood(集まり・状態)。childhood の -hood と同じ接尾辞。in the neighborhood of 〜 で「〜の近辺に」と場所を表せる。",
  "review": "re-(再び)+view(見る)で、見直す→検討・批評。名詞では performance review(人事考課)、動詞では review a document のように使う。",
  "usually": "頻度副詞なので、一般動詞の前・be 動詞の後ろに置くのが基本位置(is usually crowded)。always / often / rarely と並べて位置ごと覚える。",
  "trouble": "have trouble (in) doing「〜するのに苦労する」や trouble with 〜「〜の不具合」の形が基本。機器の故障を伝える場面で使われる語。",
  "survey": "sur-(上から)+vey(見る)で、上から見渡す→調査。supervisor の super-+vis と同じ発想。customer survey / conduct a survey の形が定番。",
  "garage": "フランス語 garer(避難させる・保管する)からの語。parking garage(立体駐車場)や garage sale の形でも見かける。",
  "cause": "cause A to do(Aに〜させる)や cause damage / delay のように、悪い結果を目的語に取ることが多い。名詞「原因」は結果を表す effect と対で覚える。",
  "competition": "com-(共に)+petere(求める)で、同じものを求め合う→競争。compete / competitor / competitive と品詞を区別し、compete with 人 for 賞 の前置詞も確認。",
  "chief": "ラテン語 caput(頭)が語源で、captain や chapter と同じ仲間。名詞「長」のほか、形容詞で chief concern(主な関心事)のようにも使う。",
  "agreement": "agree+-ment。reach an agreement(合意に達する)や lease agreement(賃貸契約)が定番。agree は提案に to、人に with と使い分ける。",
  "mayor": "ラテン語 maior(より大きい)から。major や majority と同根で、町で一番「大きい」立場の人。run for mayor / mayor's office の形で見る。",
  "experience": "ex-(外へ)+per(試す)で、試してみて得たもの。experiment や expert と同根。「経験」は不可算、「体験」を指すと a great experience のように可算になる。",
  "register": "re-(後ろへ)+gerere(運ぶ)で、記録を持ち帰って書き留める→登録。register for 〜(〜に登録する)の前置詞と、名詞 registration との品詞の違いに注意。",
  "initial": "in-(中へ)+it(行く)で、入り口に立つ→最初の。initially / initiate / initiative と同根で、名詞だと「頭文字」。initial cost / initial investment の形でも使う。",
  "visitor": "visit（訪れる）+ -or（人）。TOEICでは受付や工場見学の場面でよく登場し、visitor pass（入館証）や visitor parking（来客用駐車場）などの複合名詞で頻出。",
  "function": "ラテン語の functio（遂行）が語源。機械の「機能」だけでなく、TOEICでは「公式行事・宴会」の意味でも登場し、attend a function のように使われる。",
  "laboratory": "labor（働く）+ -atory（場所）で「作業する場所」が原義。TOEICでは製薬や製品開発の文脈で登場し、research laboratory（研究所）や略称 lab の形で頻出。",
  "factory": "fact（作る）+ -ory（場所）が語源。TOEICでは製造業の文脈で plant（工場）と言い換えられることが多く、factory inspection（工場視察）などの複合名詞も頻出。",
  "professional": "profession（職業）の形容詞形で名詞「専門家」にもなる。TOEICでは研修案内の文脈で professional development（能力開発・人材育成研修）が頻出コロケーション。",
  "potential": "ラテン語 potens（力がある）が語源。TOEICのマーケティング文脈では、potential clients や potential customers（見込み客）の修飾語として定番。",
  "various": "動詞 vary（変化する）から派生。後ろには複数名詞を伴い（various reasons など）、Part 5やPart 7では a variety of への言い換えとしてよく意識される。",
  "proposal": "pro-（前へ）+ pose（置く）で「差し出すこと」。語尾が -al だが形容詞ではなく名詞で、submit a proposal（提案書を提出する）などの動詞との結びつきが頻出。",
  "establish": "stable（安定した）と同語源で「強固に据える」が原義。会社を「設立する」だけでなく、TOEICでは establish a relationship（関係を築く）の用法も多い。",
  "component": "com-（共に）+ pon（置く）で「一緒に置かれて全体を作るもの」。TOEICでは製造や保守の場面で replacement components（交換用部品）の形でよく目にする。",
  "opportunity": "港に向かう好都合な風（ラテン語）が由来。TOEICの手紙やスピーチでは take this opportunity to do（この場を借りて〜する）という定型句で非常によく使われる。",
  "environment": "environ（取り囲む）が語源。地球環境の話題だけでなく、TOEICでは working environment（労働環境）や environmentally friendly（環境に優しい）の形で頻出。",
  "furniture": "furnish（備え付ける）の名詞形。TOEICで最頻出の不可算名詞の1つで、複数形にできず 1 点を数える際は a piece of furniture と表す点が Part 5 で狙われる。",
  "transportation": "trans-（越えて）+ port（運ぶ）。TOEICでは public transportation（公共交通機関）や出張精算の transportation costs（交通費）の形で定番。",
  "calculate": "古代ローマで小石（calculus）を並べて数えたことが由来。TOEICでは見積もりや経費精算の文脈で出やすく、名詞形の calculation（計算・見積もり）も問われる。",
  "chance": "ラテン語の「偶然落ちる」が原義。opportunity（目的達成のための好機）に対し、chance は確率・見込みの意味も持ち、chance of rain などの形で使われる。",
  "branch": "「木の枝」が原義で、本社から枝分かれした「支店」を表す。TOEICでは head office（本社）と対比され、branch manager（支店長）などの表現で頻出。",
  "baggage": "bag（袋）の派生語で、luggage と同様に数えられない不可算名詞。TOEICの空港アナウンスでは baggage claim（手荷物受取所）が Part 4 や 7 でおなじみ。",
  "satisfy": "satis（十分）+ fy（する）で「満ち足らせる」。be satisfied with（〜に満足している）の受動態のほか、satisfy the requirements（条件を満たす）の用法も頻出。",
  "drawing": "draw（線を引く）から派生。TOEICでは芸術の絵画だけでなく「設計図・図面」の意味や、イベント通知での prize drawing（景品の抽選会）という意味でよく問われる。",
  "distance": "dis-（離れて）+ stance（立つ）で「離れて立っていること」。TOEICの宿泊施設や物件案内では within walking distance（徒歩圏内）が頻出の決まり文句。",
  "publish": "public（公の）と同語源で「公にする」が原義。本を「出版する」だけでなく、調査報告や指針を公表する文脈でも使われ、名詞 publication（出版物）との品詞区別も重要。",
  "profit": "pro-（前へ）+ fit（進む・なす）で「前進して得られる利益」。TOEICの財務諸表では net profit（純利益）、派生語として profitable（収益性の高い）が頻出。",
  "product": "pro-（前へ）+ duct（導く）で生み出されたもの。数えられる製品（可算）であり、不可算名詞の produce（農産物）や production（生産活動）との混同に注意。",
  "change": "動詞の「変更する」だけでなく、名詞「お釣り・小銭」の意味がリスニングで頻出。小銭の意味では不可算名詞で exact change（お釣りのない丁度の額）の形でよく使われる。",
  "alike": "a-（状態）+ like（似た）。名詞を前から修飾できず補語として使う形容詞（be alike）。副詞として文末に置き「〜も…も同様に」（both A and B alike など）の形でも頻出。",
  "reasonable": "reason（道理）+ -able（できる）で「納得できる」。TOEICでは価格の文脈で「手頃な」という意味で使われ、at a reasonable price や reasonably priced が定番。",
  "senior": "ラテン語の「より年配の」が原義。TOEICでは職位が「上級の」を表し、senior management（上層部）などの形で頻出。比較構文では than ではなく to を取る点も特徴。",
  "annual": "ラテン語 annus（年）が語源で「年に1度の」。TOEICの社内通知や財務文脈で極めて頻出で、annual report（年次報告書）や annual conference（年次総会）の形で多用される。",
  "purchase": "pur-（前へ）+ chase（追う）で「手に入れる」。buy のフォーマルな語で名詞にもなり、proof of purchase（購入証明書）や purchase order（発注書）の形で頻出。",
  "additional": "add(加える)+-tion+-al(形容詞語尾)で「追加の」。additional information や additional fee などの名詞句で頻出するほか、副詞 additionally との品詞区別もよく狙われます。",
  "subject": "sub-(下に)+ject(投げる)が原義で「下に置かれたもの」。メールの件名や議題として出るほか、形容詞用法 be subject to change(変更される場合がある)が超頻出です。",
  "membership": "member(一員)+-ship(資格・身分)で「会員資格」。annual membership fee(年会費)や membership renewal(会員更新)など、会員募集や施設案内の文脈で定番です。",
  "succeed": "sub-(後ろに)+ceed(行く)が原義。「成功する」は succeed in -ing を取り、「後を継ぐ」では succeed 人 as 役職 の形を取ります。名詞 success と succession の違いも重要。",
  "regarding": "動詞 regard(考慮する)から派生した前置詞で about や concerning と同義。Regarding your inquiry(お問い合わせの件)のようにメール冒頭や件名でよく使われます。",
  "bill": "「封印された文書」が由来。名詞では utility bills(光熱費)や billing address(請求先住所)、動詞では bill 人 for 金額(人に〜を請求する)の形でよく登場します。",
  "regulation": "reg-(正す・支配する)が語源で「規則・規制」。safety regulations のように複合名詞で使われるほか、comply with regulations(規則を遵守する)という動詞との連語が頻出です。",
  "seek": "「探し求める」の意。求人広告の seek applicants(応募者を募る)や seek to do(〜しようと努める)で頻出するほか、過去・過去分詞が sought と不規則変化する点も要確認です。",
  "experienced": "ex-(外へ)+peri-(試す)が語源の「経験豊富な」。求人要件の highly experienced staff や experienced candidate のように、人材を修飾する形容詞として頻出します。",
  "region": "reg-(支配する)+-ion で「支配下の土地→地域」。形容詞 regional も頻出で、regional office(支社)や regional manager(地域統括)のように組織の文脈でよく問われます。",
  "explain": "ex-(外へ)+plain(平らな)で「平らに広げて説明する」。第4文型は取れず、explain 物 to 人(人に〜を説明する)や explain that 節の形を取る語法が頻出のポイントです。",
  "equally": "equ-(等しい)+-ly で「平等に・均等に」。distribute ... equally(均等に配分する)などの動詞修飾や、equally important(同様に重要な)のような形容詞修飾で使われます。",
  "suggest": "sub-(下に)+gest(運ぶ)で「控えめに提案する」。suggest doing(動名詞)を取る点や、suggest that S (should) do と that 節内が動詞の原形になる語法が頻出です。",
  "accept": "ad-(〜へ)+cept(つかむ)で「受け取る」。accept an offer(申し出を受ける)や accept credit cards(カードが使える)のほか、形容詞 acceptable(許容できる)も頻出です。",
  "financial": "ラテン語の「清算する」が由来の形容詞。financial statements(財務諸表)や financial performance(財務実績)など、決算発表や年次報告書の文脈で頻出します。",
  "improve": "「利益をもたらす」が語源で「改善する」。improve efficiency/productivity(効率・生産性を向上させる)が頻出コロケーションで、名詞形 improvement もよく問われます。",
  "height": "high(高い)に名詞語尾 -th が付いた語。寸法の説明(height, width, depth)で見かけるほか、at the height of the season(最盛期に)という表現も頻出です。",
  "direct": "dis-+regere(まっすぐ導く)が原義。形容詞 direct flight(直行便)のほか、動詞 direct inquiries to 〜(問い合わせを〜に向ける・案内する)という語法がよく出ます。",
  "contrast": "contra-(反対に)+stare(立つ)で「対照」。前置詞句の in contrast to/with 〜(〜と対照的に)や、文頭で使う By contrast,(対照的に)という接続表現が頻出です。",
  "president": "prae-(前に)+sedere(座る)で「先頭に座る人」。ビジネスでは「社長」を指し、vice president(副社長)とセットで人事異動や昇進を伝えるアナウンス・社内メールで頻出します。",
  "transfer": "trans-(越えて)+fer(運ぶ)が原義。be transferred to 〜 branch(〜支店に転勤する)という人事や、wire transfer(電信送金)など多様なビジネス文脈で登場します。",
  "income": "in(中に)+come(入る)で「入ってくるお金→収入」。annual income(年収)や net income(純利益)の形で出ます。会社全体の売上高を表す revenue との区別も意識しましょう。",
  "afraid": "「恐れて」の意ですが、ビジネスでは I am afraid (that) 〜(あいにく〜です、申し訳ありませんが〜)という断りや言いにくいことを丁寧に伝える前置きとして頻出します。",
  "notice": "not-(知る)が語源。名詞 until further notice(追って通知があるまで)や advance notice(事前通知)のほか、give two weeks notice(2週間前の退職予告)も頻出です。",
  "mechanical": "machine(機械)と同語源。mechanical failure/problem(機械の故障・不具合)の形で、交通機関の遅延案内や工場設備のトラブルを知らせるアナウンスでよく登場します。",
  "agency": "ag-(行う)+-ency で「代行する機関」。advertising agency(広告代理店)や employment agency(人材紹介会社)など、外部委託や専門サービスの文脈で定番です。",
  "scholarship": "scholar(学者・学生)+-ship(身分・資格)で「奨学金」。award a scholarship(奨学金を授与する)や apply for a scholarship(応募する)の動詞との結びつきが頻出です。",
  "remove": "re-(離れて)+move(動かす)で「取り除く」。remove ... from 〜(〜から…を取り除く)の語法のほか、名詞 removal(撤去・除去)との品詞識別問題でも狙われます。",
  "highly": "high に由来しますが物理的な高さではなく程度を表し「非常に」。highly recommended(強く推奨される)や highly successful のように形容詞を修飾する形で頻出します。",
  "spend": "ラテン語の「重さを量って支払う」が由来。spend 時間/お金 on 名詞 や、spend 時間/お金 (in) -ing(〜するのに時間を費やす)という語法・前置詞のパターンが頻出です。",
  "latest": "late（遅い・最近の）の最上級で「最も新しい」。the latest version（最新版）や the latest news、また at the latest（遅くとも）などの成句で頻出する。",
  "therefore": "there（それ）＋fore（〜のために）から「それゆえに」。接続詞ではなく接続副詞のため、コンマだけで文を繋げず、文頭やセミコロンの直後に置かれる。",
  "purpose": "pur-（前に）＋pose（置く）で「あらかじめ前に置いた意図」→「目的」。Part 7の冒頭設問「What is the purpose of...?」で毎回のように登場する。",
  "status": "stare（立つ）が語源で「立っている位置や様子」を表す。TOEICでは current status（現状）や shipping status（発送状況）など進捗確認の文脈で頻出。",
  "interview": "inter-（互いに）＋view（見る）で「互いに見合う」が原義。人事関連で job interview（就職面接）や schedule an interview（面接日程を決める）として頻出。",
  "recently": "recent（最近の）に-lyがついた副詞。TOEICの文法問題では過去形や現在完了形（have recently -ed）と一緒に使われる時制の決定打になる。",
  "raise": "後ろに目的語を取る他動詞で、自動詞 rise（上がる）との区別が頻出。raise funds（資金を集める）や raise prices（値上げする）のほか名詞「昇給」もある。",
  "grocery": "大量（gross）に品物を扱う店主（grocer）に由来。grocery store（食料雑貨店）や、複数形 groceries（食料品）の形で店舗や買い物の文脈に登場する。",
  "move": "単に「動く」だけでなく、ビジネスでは「（会社やオフィスが）移転する」の意味で relocate の同義語として頻出。move to a new location（新天地に移転する）が典型。",
  "wheel": "車輪のほか車のハンドルも指す。Part 1の写真描写問題では behind the wheel（運転席に座って・運転中で）や steering wheel（ハンドル）の表現で出題される。",
  "square": "四角い区画から転じて「公共の広場」を意味する。Part 1や告知文で public square（公共広場）として出るほか、square meters など面積の単位でも使われる。",
  "while": "後ろに節を伴う接続詞で、名詞を伴う前置詞 during との識別がPart 5で頻出。while walking や while on duty のように主語＋be動詞が省略された形も狙われる。",
  "achieve": "a-（〜へ）＋chief（頭・頂点）で「頂点に届く」→「成し遂げる」。achieve a goal（目標を達成する）や achieve target sales（売上目標を達成する）の形で頻出。",
  "recommendation": "re-（強意）＋commend（委ねる）で「推薦すること」。letter of recommendation（推薦状）や make a recommendation（提案・助言をする）の連語で頻出。",
  "field": "野原から転じて仕事や研究の「分野・業界」を表す。an expert in the field of ...（〜の分野の専門家）のように専門性を語るプロフィール文脈で頻出。",
  "preparation": "pre-（あらかじめ）＋pare（用意する）で「事前準備」。in preparation for ...（〜の準備・備えとして）という前置詞句のセット表現がPart 5などで非常によく出る。",
  "renovate": "re-（再び）＋nov（新しい）で「再び新しくする」→「改装する」。closed for renovation（改装のため休業中）のように店舗や建物の改装告知で頻出する。",
  "original": "origin（起源）が語源。original receipt（レシート原本）や original plan（当初の計画）で使われる。副詞 originally（当初は）は計画変更を示す合図になる。",
  "affect": "af-（〜へ）＋fect（作用する）で「影響を及ぼす」。他動詞なので前置詞 on は不要。名詞 effect（効果・影響）との品詞の区別や have an effect on との混同が狙われる。",
  "vehicle": "ラテン語の「運ぶ」が語源で、乗用車・トラック・バスなど車全般の上位語。Part 1の写真描写や、Part 7の parking facility（駐車場）・交通規制の案内でよく登場する。",
  "content": "con-（共に）＋tent（保つ・含む）で「中に収められたもの」。契約や箱の「中身・目次」を表すときは複数形の contents、Web上の「情報」は不可算の content で使われる。",
  "enjoyable": "enjoy（楽しむ）＋-able（できる）で「楽しむことができる」→「楽しい」。make your stay enjoyable（滞在を快適・楽しいものにする）などホテルの案内で頻出。",
  "priority": "prior（前の）に由来し「他より先に扱うべきこと」。top priority（最優先事項）や give priority to ...（〜を優先する）の形でビジネスの意思決定や業務指示によく出る。",
  "quality": "名詞「品質」のほか、quality products（高品質な製品）や quality service のように形容詞的に名詞を修飾する用法も多い。quality control（品質管理）も頻出。",
  "guided": "guide（案内する）の受動から「案内の付いた」。観光や研修の文脈で a guided tour（ガイド付きツアー）として頻出。対義語の self-guided（各自で見学する）も読解で出る。",
  "attractive": "at-（〜へ）＋tract（引く）で「心を惹きつける」。人の魅力だけでなく、attractive price（魅力的な価格）や attractive offer（魅力的なオファー）など条件の良さに使われる。",
  "budget": "元々は「革の財布」を意味した。within budget（予算内で）や on a tight budget（厳しい予算で）の定型表現が頻出。budget flightのように「格安の」という形容詞用法もある。",
  "insurance": "sure（確実な）から派生し「不測の事態に備えて確実にしておくもの」。insurance coverage（補償範囲）や insurance policy（保険契約・証書）のコロケーションが頻出。",
  "guarantee": "名詞「保証」と動詞「保証する」の両方で使われる。under guarantee（保証期間中で）や money-back guarantee（返金保証）、guarantee that節の形で頻出。",
  "expand": "ex-（外へ）＋pand（広げる）で「外側へ規模を広げる」。expand into new markets（新市場に進出する）のように事業拡大で頻出。長さを延ばす extend との混同に注意。",
  "brief": "ラテン語 brevis（短い）に由来。TOEICでは a brief meeting や brief summary のように「手短な」の意味で頻出。動詞「手短に状況を説明する」も要チェック。",
  "project": "pro-(前へ)+ject(投げる)で「前方に投げ出す構想」。名詞は第1音節、動詞「見積もる」は第2音節にアクセント。projected sales（予測売上）の形も頻出。",
  "stair": "通常複数形 stairs で「階段」を表し、take the stairs（階段を使う）が定番。Part 1の写真描写で階段を上り下りする動作の描写にも頻出する。",
  "since": "「〜以来」では現在完了形（since last year）、「〜だから（理由）」では because の代わりに使われる。文脈による意味の見極めが Part 5 で重要。",
  "otherwise": "other（別の）+wise（方法）。TOEICでは unless otherwise noted（特記がない限り）の定型句が頻出。副詞であり接続詞ではない点も狙われやすい。",
  "noise": "吐き気を意味する nausea と同根。TOEICでは騒音への苦情（noise complaint）や excessive noise（過度の騒音）の形でオフィスや工事の文脈に出る。",
  "exactly": "ex-(外へ)+act(行う)から「きっちり仕上げられた」。exactly at 2:00 のように時刻を強調する用法や、Part 2 の応答「その通りです」で頻出。",
  "available": "avail(役立つ)+-able(できる)。物は「利用・入手可能」、人は「手が空いている」の意味。available online や Are you available? で超頻出。",
  "join": "ラテン語「結ぶ」が語源（joint と同根）。他動詞のため join the company（入社する）や join a meeting のように前置詞なしで直接目的語を取る。",
  "agricultural": "agri-(農地)+culture(耕作)+-al。名詞 agriculture（農業）の形容詞形。agricultural products（農産物）や sector（農業部門）の形で登場する。",
  "record": "re-(再び)+cord(心)で「心に留める」。名詞は第1音節、動詞は第2音節にアクセント。track record（実績）や record sales（最高売上）の表現が頻出。",
  "automobile": "auto-(自ら)+mobile(動く乗り物)。car よりフォーマルな語で、automobile industry（自動車産業）や parts（自動車部品）の文脈でよく使われる。",
  "commercial": "merc(商売)に由来し merchandise と同根。形容詞「商業の」として commercial property（商業用不動産）や commercial vehicle（商用車）で頻出。",
  "direction": "rect(まっすぐ導く)に由来。複数形 directions は「取扱説明書・指示事項」を表し、follow the directions（指示に従う）のコロケーションが定番。",
  "concern": "con-(共に)+cern(見分ける)。名詞「懸念」として express concern about（懸念を示す）が定番。派生前置詞 concerning（〜に関して）も Part 5 頻出。",
  "director": "direct(指揮する)+-or(人)。映画監督だけでなく企業の「役員・部長」を指し、board of directors（取締役会）などの役職名として頻出する。",
  "beverage": "ラテン語 bibere（飲む）に由来する改まった語。機内や懇親会のアナウンスで food and beverages（飲食、略称 F&B）の組み合わせでよく登場する。",
  "conversation": "con-(共に)+vers(向きを変える)+-ation で「言葉を交わすこと」。have a conversation with や、Part 3 の冒頭指示文で毎回目にする基本語。",
  "possible": "ラテン語 posse（能力がある）に由来。as soon as possible（できるだけ早く）や、make it possible to do（〜することを可能にする）の構文で頻出。",
  "payment": "pay(支払う)+-ment。make a payment（支払いをする）や payment method（支払い方法）、upon payment（支払い受領次第）など請求・経理トピックで頻出。",
  "leave": "「後に残す」が原義。動詞のほか、名詞「休暇」として annual leave（有給休暇）や sick leave（病気休暇）、take leave などの形で人事トピックに頻出。",
  "attract": "at-(〜へ)+tract(引く)で「引き寄せる」。attract customers（顧客を引きつける）や attract new investors（新規投資家を呼び込む）の目的語と頻出。",
  "development": "de-(外す)+velop(包む)+-ment で「包みを開くこと」。Research and Development（R&D: 研究開発）や能力開発（研修）の文脈で頻出。",
  "permit": "per-(通す)+mit(送る)。動詞「許可する（permit O to do）」のほか、名詞「許可証（parking permit）」も頻出。不可算名詞 permission（許可）と区別する。",
  "progress": "pro-(前へ)+gress(進む)で「前進」。不可算名詞なので a をつけない点がポイント。in progress（進行中で）や make progress（進歩する）で頻出。",
  "match": "古英語「対等な者」に由来。match the description（説明と一致する）や、他店の安値に合わせる price match（他店価格対抗）などのビジネス文脈で頻出。",
  "efficient": "ef-(外へ)+fic(行う)+-ent で「成果を出せる」。cost-efficient（費用対効果の高い）や energy-efficient（省エネの）の複合形容詞で頻出。",
  "demand": "de-(強く)+mand(命じる)。名詞「需要」として meet the demand（需要に応える）や demand for ~（〜への需要）、in demand（人気で）が頻出。",
  "economic": "eco(家)+nomy(管理)+-ic。TOEICでは economic（経済の、economic growth）と economical（安上がりな・節約になる）の語形混同が Part 5 で狙われる。",
  "research": "re-(徹底的に)+search(探す)。名詞 research は不可算名詞（数えられない）なのが TOEIC の急所。a をつけず、do research や market research で使う。",
  "range": "古フランス語で「列・並び」を意味した語。TOEICでは a wide range of ...（幅広い〜）や、動詞として range from A to B（AからBに及ぶ）の形で頻出。",
  "shelf": "複数形が shelves と不規則変化する点に注意。Part 1の写真描写で on the shelf や be stocked on shelves（棚に並んでいる）の表現でよく見られる。",
  "resource": "re-（再び）+ source（湧き出る泉）で、困ったときに頼れる源泉を表す。TOEICでは Human Resources（人事部）という部署名でおなじみの語。",
  "approve": "ad-（〜へ）+ prove（試す・良いと証明する）から「承認する」。他動詞で approve a budget や、名詞形の approval（承認）もPart 5で問われやすい。",
  "full-time": "part-time（非常勤の）の対義語。求人票で full-time position（常勤ポスト）や full-time employee（正社員）などの組み合わせを押さえよう。",
  "located": "ラテン語の locus（場所）が語源。be located in / at（〜に位置する）と受動態で用いられ、conveniently located（便利な立地の）は定番のコロケーション。",
  "reputation": "re-（再び）+ putare（考える）で、人々が繰り返し考えること→「評判」。have a reputation for ...（〜で評判が良い）の連語でよく問われる。",
  "occur": "ob-（向かって）+ currere（走る）で「目の前に現れる」。自動詞のため受動態（be occurred）にできないのがPart 5の文法問題で狙われやすいポイント。",
  "equip": "元は「船に備品を整える」を意味した語。語法として equip A with B（AにBを備え付ける）や受動態 be equipped with（〜を備えている）を押さえたい。",
  "although": "all（すべて）+ though（〜だけれども）の強調形。接続詞なので後ろに SV の節が続く。前置詞 despite や in spite of（後ろに名詞）との品詞の区別が定番。",
  "book": "「帳簿に記帳する」ことから動詞で「予約する」。book a flight / room だけでなく、fully booked（予約で満杯）の形もリスニングでよく耳にする。",
  "announce": "ad-（〜へ）+ nuntiare（報告する・伝える）。社内メール等で announce that ... や announce retirement（退職を発表する）の文脈でよく使われる。",
  "recognize": "re-（再び）+ cognoscere（知る）で「見覚えがある」。TOEICでは「功績を認める・表彰する」の意味でもよく使われ、表彰イベントの話題で登場しやすい。",
  "check": "チェスの「王手（check）」に由来。「確認する」のほか、TOEICでは名詞「小切手」として pay by check（小切手で支払う）の文脈でも登場する。",
  "headquarters": "head（主たる）+ quarters（宿舎・場所）。末尾に -s がついた形で単数・複数両方に扱える。corporate headquarters（企業本社）の表現が定番。",
  "park": "元は「囲い込まれた狩猟地」。TOEICでは動詞「駐車する」として、vehicles are parked along the street（通り沿いに駐車されている）などの描写が定番。",
  "return": "re-（再び）+ turn（戻す）。TOEICの読解やリスニングでは、店舗の規定として return policy（返品ポリシー・返品規約）が定番。",
  "import": "im-（中に）+ portare（運ぶ）で港の内側に運ぶ→「輸入する」。外へ運ぶ export（輸出する）と対比で覚えるとよい。imported goods（輸入品）の形も押さえたい。",
  "compare": "com-（共に）+ par（同等の・並ぶ）で「並べて比べる」。語法として compare A with B（AとBを比較する）や、分詞構文 compared with ...（〜と比べると）が重要。",
  "drawer": "draw（引く）+ -er（〜するもの）で、引いて開ける箱→「引き出し」。Part 1写真描写で desk drawer（机の引き出し）や open a drawer の動作で出題される。",
  "temporary": "ラテン語 tempus（時）が語源。対義語は permanent（恒久的な）。temporary closure（一時休業）や temporary staff（臨時職員）の形でよく目にする。",
  "electronic": "electron（電子）に由来。電気そのものを指す electrical と区別したい。electronic device（電子機器）や electronic payment（電子決済）でよく使われる。",
  "solve": "ラテン語 solvere（解く・緩める）が語源。solve a problem / issue（問題を解決する）の形で使われる。名詞形の solution（解決策）もPart 5の選択肢で頻出。",
  "opposite": "op-（向かい合って）+ positus（置かれた）。the opposite direction（反対方向）のほか、前置詞として opposite the station（駅の向かいに）のように使われる。",
  "labor": "ラテン語で「仕事・苦労」を意味する語。ビジネス英語では labor cost（人件費）や labor shortage（人手不足）などの複合名詞を押さえよう。",
  "vote": "ラテン語 votum（誓約・願い）が語源。前置詞の使い分けがポイントで、vote for ...（〜に賛成票を投じる）、vote against ...（〜に反対票を投じる）の形をとる。",
  "wildlife": "wild（野生の）+ life（生命）。集合的に野生生物全体を指す不可算名詞（数えられない名詞）である点に注意。wildlife conservation（野生生物の保護）などの文脈で出やすい。",
  "author": "ラテン語 auctor（生み出す人）に由来し、authority（権威）と同語源。名詞「著者」だけでなく、動詞として「本や報告書を執筆する」の意味で使われることもある。",
  "fund": "ラテン語 fundus（底・基礎）が語源で foundation（土台）と同根。名詞「資金・基金」のほか、動詞として fund a research project（研究に資金援助する）の用法も押さえておきたい。",
  "shuttle": "機織り機の糸を左右に往復させる杼（ひ）が原義で行き来するものを指す。TOEICでは shuttle service や airport shuttle（空港送迎バス）の組み合わせが定番。",
  "supply": "sub-（下から）+ plere（満たす）が語源。動詞では supply A with B（AにBを供給する）、名詞の複数形 supplies は office supplies（事務用品）の形で頻出。",
  "material": "ラテン語 materia（物質）が由来。packaging materials（梱包資材）などの「材料」だけでなく、promotional materials（販促資料）のように「資料」の意味でも頻出。",
  "advanced": "動詞 advance（前進させる）の過去分詞から。講座案内での advanced level（上級レベル）や、製品紹介での advanced technology（先端技術）の修飾語として定番。",
  "provide": "pro-（前もって）+ vide（見る）で「あらかじめ備える」が原義。provide A with B（AにBを提供する）と provide B to/for A の前置詞の使い分けが狙われやすい。",
  "upcoming": "up（上に）+ come（来る）で「間近に迫っている」。TOEICでは社内通知や案内文の冒頭で、upcoming conference（今度の会議）のように名詞を前から修飾する。",
  "increase": "in-（強意）+ crescere（育つ）が語源。自動詞・他動詞の双方で使われ、名詞の場合は an increase in sales（売上の増加）のように前置詞 in と結びつく。",
  "release": "relax（緩める）と同語源で「解き放つ」が原義。新製品を「発売する」や情報を「発表する」意味で多用され、名詞としても press release（公式発表）でおなじみ。",
  "ship": "名詞「船」から転じ、トラックや航空便での「発送・出荷」全般を表す動詞。注文メールの文脈で shipping confirmation（発送確認）や free shipping（送料無料）として頻出。",
  "decision": "de-（切り離す）+ cide（切る）で「迷いを断ち切ること」。動詞 make と結びつく make a decision（決断を下す）や、decision-making（意思決定）の複合語が定番。",
  "gather": "together（一緒に）と同語源。人が主語の自動詞「集まる」のほか、他動詞として gather data（データを集める）や gather feedback（意見を収集する）の形で使われる。",
  "clothes": "布地を表す cloth の複数形から派生し、常に複数扱いで受ける。TOEICでは服装規定の文脈で出やすく、不可算の集合名詞 clothing との文法上の区別が重要。",
  "replace": "re-（再び）+ place（置く）で「代わりのものを置く」。replace A with B（AをBと交換する）の構文に加え、人事異動で「〜の後任を務める」という意味でも頻出。",
  "deposit": "de-（下に）+ posit（置く）で「手元から下に置く→預ける」。銀行預金だけでなく、契約やレンタルの文脈で a refundable deposit（返金可能な保証金）の形で頻出。",
  "warehouse": "ware（商品・品物）+ house（家）で「商品を保管する建物」。TOEICでは在庫管理や物流の文脈で、warehouse staff（倉庫係）や warehouse inventory（倉庫在庫）として頻出。",
  "certain": "ラテン語 certus（確定した）が語源。補語の叙述用法では be certain that（確信している）、名詞修飾の限定用法では under certain conditions（一定の条件で）と意味が変わる。",
  "offer": "ob-（〜へ）+ ferre（運ぶ）で「相手の前に差し出す」。第4文型（offer him a job）を取る動詞で、名詞としても job offer（採用通知）や special offer（特別割引）で定番。",
  "departure": "動詞 depart（出発する）の名詞形。対義語 arrival（到着）とセットで、空港や駅の案内アナウンスの departure time（出発時刻）や departure gate（搭乗口）として頻出。",
  "duty": "due（当然支払うべき）から派生した語。TOEICでは「職務」の意味で job duties（業務内容）や on duty（勤務中）で頻出するほか、免税の duty-free でも日常的。",
  "avoid": "a-（外へ）+ void（空の）で「遠ざける」。文法的に後ろには不定詞ではなく動名詞を取る（avoid doing）点が Part 5 で狙われ、avoid delays（遅延を避ける）の形で頻出。",
  "text": "ラテン語「織られたもの」が原義で、言葉を織りなした「文章」。TOEICでは携帯メッセージを送る動詞としても使われ、Part 7 のチャット形式問題で頻出。",
  "neither": "not + either から成る否定語。接続詞 neither A nor B（AもBも〜ない）や、単数名詞を伴って「どちらの〜も…ない」（neither applicant is...）と単数で受ける規則が頻出。",
  "instead": "in + stead（場所）で「別の場所に入って→代わりに」。文末などに置く副詞 instead 単体と、後ろに名詞を伴う群前置詞 instead of（〜の代わりに）の品詞の区別が頻出。",
  "reflect": "re-（後ろへ）+ flect（曲げる）で「像を跳ね返す」。TOEICでは reflect customer feedback（顧客の意見を反映する）や、前置詞 on と組んで「熟考する」意味で出やすい。",
  "rest": "「休息」と「残り」の2大用法がある。「残り」の意味では the rest of the week（今週の残り）や the rest of the budget（予算の残額）のように、必ず the を伴って使われる。",
  "divide": "dis-（別々に）+ videre（分ける）が語源。TOEICでは divide A into B（AをBに分ける）の型が基本で、研修で参加者をグループ分けする指示（divide into teams）で定番。",
  "lead": "古英語「導く」が語源。他動詞「率いる」のほか、自動詞 lead to + 名詞（〜につながる）の因果関係表現が頻出で、この to は前置詞のため動詞原形は置けない。",
  "almost": "all + most（すべてに近い）が語源。副詞のため名詞を直接修飾できず almost all members のように用いるため、形容詞・代名詞の most との識別が Part 5 で狙われる。",
  "candidate": "古代ローマで立候補者が着た白い服（ラテン語 candidus＝白い）が由来。TOEIC採用文脈の最頻出語で、job candidate（応募者）や successful candidate（合格者）の形で頻出。",
  "reduce": "re-（後ろへ）+ duce（導く）で「引き下げる」。TOEICのコスト削減や業務改善の文脈で定番で、reduce costs（経費を削減する）や reduce waiting times（待ち時間を減らす）の形で頻出。",
  "collect": "com-（共に）+ lect（選ぶ・集める）が原義。秩序を持って集めるニュアンスがあり、collect data（データ収集）のほか、請求業務での collect payment（代金を回収する）の形でも出やすい。",
  "attend": "ad-(〜へ)+tend(伸ばす)が語源。会議などに「出席する」ときは他動詞なので前置詞は不要。attend to は「〜に対応する」という意味になる点に注意。",
  "unfortunately": "接頭辞 un-(否定)＋fortunate(幸運な)から成る副詞。Part 6 や 7 のメールで、注文のキャンセルや不採用などの「残念なお知らせ」を切り出す文頭でよく使われる。",
  "promotional": "pro-(前へ)+mot(動かす)の promote に由来する形容詞。promotional material(販促物)や promotional code などの形で、名詞を修飾する選択肢として頻出。",
  "crop": "「植物の先端の穂・収穫物」が原義。TOEIC では農業や天候のニュースでよく登場し、crop yield(作物の収穫量)や harvest a crop(作物を収穫する)の表現を押さえておきたい。",
  "saving": "save(節約する)の名詞形。TOEIC では cost savings(経費削減)や substantial savings のように複数形の savings で「節約・節減額」を表す用法が頻出する。",
  "innovative": "in-(中に)+nov(新しい)+-ative で「新しいものを採り入れた」。TOEIC では innovative solution(革新的な解決策)や innovative product のコロケーションで頻出。",
  "place": "名詞「場所」でおなじみだが、動詞の用法も重要。place an order で「注文を出す」という超頻出コロケーションになり、Part 3 や 7 の受発注のやり取りで定番。",
  "comfort": "com-(強意)+fort(強い)で「元気づける」が原義。TOEIC では comfort and convenience(快適さと利便性)のようにホテルや交通機関のPR文句として頻出する。",
  "determine": "de-(完全に)+termin(境界を定める)が語源。TOEIC では determine whether ...(〜かどうか判断する)や be determined to do(〜する決意である)の形に注目。",
  "thought": "think の過去形だけでなく名詞「考え・意見」としても重要。TOEIC では share your thoughts on ...(〜について意見を述べる)のように複数形 thoughts でよく登場する。",
  "especially": "special(特別な)に副詞語尾 -ly がついた形。「特に」と強調する副詞で、especially useful(特に役立つ)のように形容詞を直前から修飾する位置の問題で狙われやすい。",
  "ceiling": "TOEIC では Part 1 の写真問題で light fixtures hanging from the ceiling(天井から吊り下がった照明)などの描写として定番。low ceiling などの表現も出る。",
  "properly": "proper(適切な)+-ly(副詞語尾)。function properly(正常に機能する)や properly installed(適切に設置された)のように動詞や過去分詞を修飾する副詞として出題される。",
  "article": "ラテン語 articulus(小さな節)が語源。Part 7 の長文形式名「記事」として頻出するほか、an article of clothing(衣類1点)のように「品物」を表す用法もある。",
  "figure": "ラテン語 figura(形)が由来。TOEIC では「数字・数値」の意味で sales figures(売上高)のように複数形で使われるほか、動詞句 figure out(〜を把握する)も頻出。",
  "unable": "un-(否定)+able(できる)。be unable to do(〜することができない)の形で、要望に応えられない丁寧なお断りメールなどの文脈で多用される。",
  "during": "dure(続く)に由来する前置詞。during the meeting のように特定期間の名詞を取る。後ろに主語＋動詞が続く接続詞 while との品詞識別が Part 5 の定番。",
  "order": "ラテン語 ordo(順序)が由来。動詞「注文する」に加え、in order to do(〜するために)や out of order(故障中)などの重要表現を押さえたい。",
  "stress": "distress(圧迫)の頭文字が落ちた語。名詞の「圧力」だけでなく、stress the importance of ...(〜の重要性を強調する)の形で emphasize の同義語として頻出する。",
  "overall": "over(全体を覆って)+all(すべて)から「全体的な」。overall performance(全体の業績)や overall budget(総予算)のように名詞を修飾する形容詞としてよく出る。",
  "lease": "古フランス語の「貸す・手放す」が起源。lease office space(オフィスを賃貸借する)のほか、名詞で sign a lease(リース契約を結ぶ)の形で頻出。",
  "fee": "家畜や財産を表す古語に由来。admission fee(入場料)や late fee(延滞料金)、service fee(手数料)など、特定のサービスに伴う料金を表す名詞。",
  "several": "sever(切り離す)と同根で「個々に分かれた」が原義。several options や several weeks のように、後ろには必ず「可算名詞の複数形」が続く点が文法問題の急所。",
  "indicate": "in-(向かって)+dic(言う・示す)が語源。The survey indicates that ...(調査は〜と示している)のほか、Part 7 の設問「What is indicated...?」でも超重要。",
  "postpone": "post-(後ろに)+pone(置く)で文字通り「後回しにする」。postpone the event until Friday のように日時を置く形や、後ろに動名詞 -ing を取る語法が狙われる。",
  "inform": "in-(心の中に)+form(形を作る)から「教え知らせる」。inform 人 of 事柄 や inform 人 that 節のように「人を目的語にとる」語法が Part 5 で頻出。",
  "apologize": "apo-(離れて)+log(言葉)で本来は「弁明する」。自動詞なので「apologize for the delay(遅延を謝罪する)」のように前置詞 for や to 人 を伴って使われる。",
  "reach": "「手を伸ばす」が原義の他動詞。reach a goal(目標を達成する)や「連絡をとる(reach me at...)」の意味で使われ、前置詞不要の他動詞である点に注意。",
  "advertising": "ad-(〜へ)+vert(向ける)で「注意を向けること」。不可算名詞(広告宣伝・広告業)であり、1件ずつの広告を表す可算名詞 advertisement との区別が問われる。",
  "occasion": "ob-(〜へ)+cad(落ちる)で「偶然降って湧いた出来事」。on this occasion(この機会に)や on special occasions(特別な行事で)のように前置詞 on とセットで覚えるのが効果的。",
  "immediately": "im-（無）+ mediate（仲介）+ -ly で「間に何も置かず直接に」が原義。TOEICでは immediately after（〜の直後に）など時間を表す表現で頻出。",
  "valuable": "value（価値）+ -able（できる）。形容詞のほか複数形 valuables で「貴重品」を表す名詞になる。keep valuables in a safe（貴重品を金庫に保管する）の形で頻出。",
  "broadcast": "broad（広く）+ cast（投げる）で「広く種をまく」が原義。動詞の過去形・過去分詞も同形の broadcast になる点に注意。live broadcast（生放送）などの名詞でも頻出。",
  "frequent": "ラテン語の「数が多い・繰り返される」が語源。TOEICでは出張や航空会社の話題で frequent flyer（マイレージ会員）や frequent traveler の組み合わせで定番。",
  "floor": "建物の「階」を表すほか、TOEICでは施設案内で floor plan（間取り図）や sales floor（売り場）の形で頻出。階数を表す際は on the second floor と前置詞 on を使う。",
  "architect": "archi-（第一の）+ tect（築く人）で建物を設計する「人」を表す。Part 5 では architecture（建築・構造）や architectural（建築の）との品詞の区別がよく問われる。",
  "exhibit": "ex-（外へ）+ hibit（差し出す）で「外に出して見せる」。動詞だけでなく名詞「展示品・展覧会」にもなり、on exhibit（展示中で）や art exhibit の形で頻出。",
  "employee": "employ（雇う）+ 受動の -ee で「雇われる人」。雇用主を表す employer との区別が重要。employee handbook（就業規則）や employee benefits（福利厚生）などの複合名詞で頻出。",
  "encourage": "en-（〜にする）+ courage（勇気）で「勇気づける」。encourage A to do（Aに〜するよう促す）や、受動態 be encouraged to do（〜するよう推奨される）の形で頻出。",
  "suit": "ラテン語の「従う・適合する」が語源。動詞では be suited for [to]（〜に適している）という受動の形でよく使われる。派生語の形容詞 suitable（適切な）との品詞の使い分けもポイント。",
  "storage": "store（蓄える）+ -age（場所・状態）。数えられない不可算名詞で、storage facility（保管施設・倉庫）や keep items in storage（品物を保管する）の形で頻出。",
  "expect": "ex-（外を）+ spect（見る）で「待ち構えて見る」。be expected to do（〜する予定である・見込まれている）の形で、運行スケジュールや到着予定を伝える文脈で頻出。",
  "promising": "名詞 promise（期待・見込み）から「前途有望な」。人事採用で promising candidate（有望な応募者）、事業計画で promising market（有望な市場）のように名詞を前から修飾して頻出。",
  "plant": "「植物」だけでなく設備を地に据えた「工場・生産設備」を表す。TOEICでは factory の同義語として使われ、manufacturing plant（製造工場）や power plant（発電所）の形で頻出。",
  "once": "副詞「かつて・1度」に加え、TOEICでは「いったん〜すると」を表す接続詞として頻出。Part 5 では後ろに節（S+V）を従える接続詞（once you receive the item など）として狙われる。",
  "against": "「〜に反対して」のほか、Part 1 の写真描写問題では lean against the wall（壁にもたれかかる）のように「〜に寄りかかって・接触して」という物理的な位置関係を表す前置詞として頻出。",
  "downtown": "形容詞「都心の」のほか「中心街へ[で]」という副詞になる。副詞のときは go downtown や relocate downtown のように前置詞 to を挟まず動詞に直接続ける点がポイント。",
  "confirm": "con-（強意）+ firm（固い）で「確実に固める」。予約や日時の確認で confirm a reservation の形で多用される。名詞 confirmation number（予約確認番号）はリスニングでも頻出。",
  "retail": "re-（再び）+ tail（切る：tailorと同語源）で「細かく切り分けて売る＝小売り」。wholesale（卸売り）の対義語で、retail price（小売価格）や retail store（小売店）の形で頻出。",
  "fuel": "名詞「燃料」として fuel efficiency（燃費性能）や fuel costs（燃料費）が頻出。動詞で「〜を刺激する・あおる」（fuel economic growth など）という意味でも使われる。",
  "finalize": "final（最終の）+ -ize（〜にする）で「最終決定する」。契約や交渉の文脈で finalize an agreement（合意をまとめる）や finalize a contract（契約を締結する）の形で頻出。",
  "accurate": "ac-（〜へ）+ cure（注意：careと同語源）で「丹念に手入れされた」が原義。accurate estimate（正確な見積もり）や accurate information のコロケーションで頻出。",
  "atmosphere": "ギリシャ語の「蒸気の球」が語源で原義は「大気」。TOEICでは店舗や職場の「雰囲気」の意味で使われ、relaxed atmosphere（落ち着いた雰囲気）や welcoming atmosphere の形で頻出。",
  "overseas": "over（越えて）+ sea（海）。形容詞「海外の」と副詞「海外へ[で]」がある。副詞のときは expand overseas（海外進出する）のように前置詞 to を挟まず動詞に直結する点に注意。",
  "form": "「形」だけでなく事務手続きの「記入用紙」を表す。fill out [complete] a form（用紙に記入する）や application form（申込書）などの定型表現で頻出。",
  "appreciate": "ap-（〜へ）+ preti（価値：priceと同語源）で「正当に価値を認める」。感謝を表すメールで I would appreciate it if you could...（〜していただけますと幸いです）の定型句が頻出。",
  "ease": "「容易さ・気楽さ」を表す。名詞では with ease（容易に＝easily）の形で出やすく、動詞では ease congestion（混雑を緩和する）や ease restrictions（規制を緩める）の形で頻出。",
  "contain": "con-（共に）+ tain（保つ：hold）で「枠の中に保ち続ける」。情報や成分を「含む」だけでなく、TOEICでは contain costs（経費を抑制する）のように費用を抑える文脈でも使われる。",
  "mention": "他動詞なので about を置かず直接目的語を取る点に注意。TOEICでは設問文で What is mentioned about...?（〜について何が述べられていますか？）の形で頻出。",
  "decade": "ギリシャ語 deka（10）が語源で「10年間」。TOEICでは over the past decade（過去10年間にわたって）などの形で現在完了形の文とともに企業の歴史や業績推移を語る文脈で出やすい。",
  "luggage": "lug(引っ張る)+-ageで「引っ張って運ぶ荷物」。baggageと同様に「不可算名詞」のため、a luggage や複数形にはできない点が Part 5 で頻出。",
  "remain": "re-(後ろに)+main(とどまる)で「後に残る」。自動詞で直後に形容詞や過去分詞を取り、remain competitive（競争力を維持する）などの第2文型（SVC）で頻出。",
  "seldom": "rarely と同義の準否定語。not なしで「めったに〜ない」を表す。文頭に置かれると Seldom have we seen... のように後ろが疑問文の語順（倒置）になる点も重要。",
  "invite": "in-(中に)+vite(求める)から「招き入れる」。invite A to B だけでなく、invite attendees to ask questions（質問を募る）のように to do を取る語法も頻出。",
  "appropriate": "ad-(〜へ)+proprius(固有の)で「状況にぴったり合った」。take appropriate measures（適切な措置を講じる）や appropriate for the occasion の形で頻出。",
  "beyond": "be-+yond(あちら)で「限界を越えて」。空間だけでなく beyond one's control（手に負えない）や beyond repair（修理不能）のように抽象的な限界を示す前置詞として頻出。",
  "public": "people（人々）と同根。public transportation（公共交通機関）や public relations（広報・PR）、the general public（一般市民）などの定型表現で頻出。",
  "traditional": "trans-(越えて)+dare(渡す)で「代々受け継がれた」。TOEICでは「伝統的な」だけでなく traditional methods（従来の手法）のように「従来の（conventional）」の意味でも頻出。",
  "ladder": "Part 1 の写真問題で頻出。A ladder is leaning against a wall（壁にはしごが立てかけられている）や climb a ladder（上る）、step ladder（脚立）の表現が定番。",
  "chapter": "caput(頭)に由来し capital と同根。本の「章」だけでなく、the local chapter of the association（協会の地元支部）のように「支部」の意味でも TOEIC に登場する。",
  "intended": "intend（意図する）の派生語。be intended for（〜向けである）や intended audience（想定読者・対象者）、intended recipient（本来の受取人）の形で通知文に頻出。",
  "resident": "re-(後ろに)+sed(座る)+-ent(人)。可算名詞で「住民・居住者」。residential（住宅の）や residence（住宅・居住）との品詞識別が Part 5 の空所補充でよく問われる。",
  "relate": "re-(再び)+lat(運ぶ)から「結びつける」。TOEIC では be related to（〜に関連している）の受動態が頻出。前置詞 to を伴う点と related documents（関連書類）の形を押さえる。",
  "session": "sed(座る)+-ion で「着席して行う会議・集まり」。training session（研修会）や information session（説明会）、Q&A session（質疑応答）などの複合名詞で頻出。",
  "traffic": "不可算名詞のため heavy traffic（激しい交通量）や light traffic で表し many は使えない。traffic congestion（渋滞）や web traffic（アクセス数）の文脈でも頻出。",
  "relative": "形容詞「相対的な」と名詞「親戚」の両方がある。TOEIC では副詞 relatively（比較的・割合に）が空所補充で頻出（relatively low cost など）。絶対的（absolute）の対義語。",
  "currently": "cur(流れる)+-ly で「今まさに流れているように」。currently unavailable（現在利用できない）のように現在形や進行形とセットで Part 5 の空所補充に頻出する。",
  "description": "de-(下に)+script(書く)+-ion で「書き記したもの」。求人広告の job description（職務内容説明書）や通販の product description（商品説明）の複合名詞で頻出。",
  "table": "家具の机だけでなく、TOEIC の Part 7 では「一覧表・図表」の意味で頻出。As shown in the table below（下の表にあるように）や table of contents（目次）が頻出表現。",
  "close": "形容詞は濁らず「クロウス」と発音。close to（〜の近くに）と前置詞 to を伴う用法や、pay close attention to（〜に細心の注意を払う）のコロケーションが頻出。",
  "arrange": "a-+range(列)で「きちんと列に並べる」。会議や交通手段の「手配をする（arrange a meeting）」の意味と、Part 1 の「整列させる（arranged in a row）」の両面で頻出。",
  "temperature": "temper（適切な状態に整える）と同根。TOEIC では製品保管や設備管理の文脈で store at room temperature（室温で保管する）や regulate temperature（温度を調節する）の形で登場。",
  "confident": "con-(強意)+fid(信じる)+-ent。be confident that 節（〜と確信している）や be confident of（〜に自信がある）の形で出題される。名詞 confidence との品詞区別も頻出。",
  "moving": "move（心を動かす）から「感動的な」。Part 7 のレビューなどで a moving speech（感動的なスピーチ）として使われる。一方、moving company（引越し業者）のような「移転」の意味も押さえたい。",
  "reply": "re-(折り返して)+ply(重ねる)。動詞では reply to an email のように前置詞 to が必須（他動詞の answer は to 不要）。名詞でも in reply to（〜への返答として）がビジネスメールで頻出。",
  "within": "with+inで「枠の内側に」。時間「〜以内に（within 24 hours）」や距離「〜の範囲内に（within walking distance: 徒歩圏内）」を表す前置詞。Part 5 で期間を示す空所に頻出。",
  "property": "proper(固有の)+-ty から「所有物」。TOEIC では特に「不動産・物件（commercial property）」や、ホテルなどの「敷地内（on the property）」を指す名詞として頻出する。",
  "ideal": "idea(理念)+-al で「観念通りの完璧な」。be ideal for（〜にうってつけである）の形で広告文や推薦文に頻出。an ideal location for conferences（会議に最適な場所）などが定番。",
  "particular": "part(部分)+-icular から「全体の中の特定の部分」。a particular field（特定の分野）のように名詞を修飾するほか、文末や挿入で in particular（特に＝particularly）の熟語が頻出。",
  "earn": "労働や努力の対価として得る語。earn money（お金を稼ぐ）だけでなく、earn a reputation（評判を勝ち取る）や earn a promotion（昇進を果たす）のように信用や実績を得る文脈でも頻出。",
  "enclose": "en-(中に)+close(閉じる)で「中に入れて封をする」。手紙に書類を添える際に使い、「Enclosed is ~」の倒置パターンやメール添付の attach との対比で見られる。",
  "handle": "名詞 hand(手)から「手で扱う」。deal with と同義で、handle customer inquiries や handle complaints のように問い合わせや苦情に対処する文脈で用いられる。",
  "complaint": "動詞 complain の名詞形。「complaint about ~」と前置詞 about を伴う形や、file a complaint(苦情を申し立てる)の連語で登場する。",
  "correct": "cor-(完全に)+rect(まっすぐにする)から「正しく直す」。形容詞「正しい」だけでなく、動詞「訂正する」として correct an error の形でも使われる。",
  "application": "apply(申し込む)の名詞形。求職や申請の文脈で使われ、job application や application form(申込用紙)、submit an application の連語が頻出。",
  "arrangement": "arrange(整える・手配する)の名詞形。複数形で「make arrangements for ~(〜の手配をする)」や travel arrangements(旅行手配)のように準備の意味で定着している。",
  "launch": "元は「船を進水させる」。新規事業や商品の立ち上げを指し、launch a new product や launch a campaign のように新しい試み・製品を世に出す動詞として使われる。",
  "reserve": "re-(後ろに)+serve(保つ)で「後にとっておく」。reserve a room などの予約のほか、規約で「reserve the right to do(〜する権利を留保する)」の定型表現も目立つ。",
  "executive": "execute(実行する)から「事業を統括する人」。CEOのEにあたる名詞「重役」のほか、「executive board(取締役会)」のように形容詞としても用いられる。",
  "attach": "at-(〜へ)+tach(留め具)で「留め具でくっつける」。ビジネスメールの定番で、「Please find attached ~(〜を添付しました)」や attached file の形で親しまれる。",
  "equipment": "equip(備える)の名詞形。TOEICでは不可算名詞として重要で、複数形 equipments にはならず、1台を指す際は a piece of equipment と数える。",
  "individual": "in-(否定)+divide(分ける)+-ualで「これ以上分けられない」。形容詞「個々の(individual needs)」のほか、名詞「個人」の用法でも出題される。",
  "concerning": "動詞 concern(関する)が前置詞化した語で、about より改まった響きを持つ。通知やお知らせの件名で「a notice concerning ~(〜に関する通知)」の形で多用される。",
  "discover": "dis-(取り去る)+cover(覆い)で「見つける」。物理的な発見だけでなく、discover an error や discover a flaw のように不具合や誤りを見つけ出す文脈で使われる。",
  "entirely": "entire(完全な)+-lyで「完全に」。completely と同義で、entirely new(全く新しい)や not entirely(完全には〜ない)と形容詞を修飾するパターンが多い。",
  "brick": "建材の「れんが」。Part 1の写真描写で定番の単語で、「pile / stack bricks(れんがを積み上げる)」など工事や建物外観の受動態描写で頻出する。",
  "unless": "「if ... not」と同義の接続詞で後ろに節が続く。「unless otherwise noted / stated(特に指示がない限り)」という挿入句はPart 5などでよく見られる定番パターン。",
  "ability": "able(できる)の名詞形。「ability to do」の形で後ろにto不定詞を伴い、求人票の応募要件(requirements)で必要な能力を列挙する際によく登場する。",
  "probably": "probe(調べる)と同語源で「証明できるほど確からしい」。高い確信度(約8割以上)を表し、maybe より確かな推測として Part 3/4 の会話で見解を述べる際に使われる。",
  "strength": "形容詞 strong(強い)の名詞形。ビジネスでは体力ではなく「強み・長所」を指し、「strengths and weaknesses(強みと弱み)」の対比表現が頻出する。",
  "except": "ex-(外へ)+cept(つかむ)で「枠外につまみ出す」。前置詞「except for ~」や、all / every とセットで「all except ~(〜以外すべて)」の形で用いられる。",
  "conduct": "con-(共に)+duct(導く)で「導いて行う」。conduct a survey(調査を実施する)の連語が頻出で、動詞は後ろ(con-DUCT)、名詞は前(CON-duct)にアクセントがある。",
  "produce": "pro-(前方へ)+duce(導く)。動詞「生産する」のほか、名詞で「農作物(fresh produce)」を指す不可算名詞としての用法が要注意で、名詞では第1音節にアクセントがある。",
  "pleased": "動詞 please の過去分詞から派生した形容詞。「be pleased to do(喜んで〜する)」や「be pleased with ~(〜に満足している)」の形で、フォーマルな書簡の冒頭によく使われる。",
  "worth": "「worth doing(〜する価値がある)」のように後ろに名詞や動名詞を従える（to不定詞は不可）。「$50 worth of items(50ドル相当の商品)」という金額表現も頻出。",
  "emphasize": "em-(中に)+phase(見せる)で「目立たせる」。名詞 emphasis とともに、emphasize the importance of ~(〜の重要性を強調する)という表現が報告書などで好まれる。",
  "renew": "re-(再び)+new(新しくする)。契約や購読を延長する文脈で使われ、「renew a contract(契約を更新する)」や「renew a subscription(購読を更新する)」としてリマインド通知で目にする。",
  "advise": "「advise A to do(Aに〜するよう助言する)」の語法が頻出。名詞 advice(不可算名詞・c)と動詞 advise(s)のスペルと品詞の区別は、Part 5 の空欄補充で狙われやすいポイント。",
  "warranty": "warrant(保証する)+-y。電化製品の購入や修理の文脈で登場し、「under warranty(保証期間中で)」や「a one-year warranty(1年保証)」「warranty expires」の形で使われる。",
  "require": "re-(強意)+quire(求める)で「強く求める」。「require A to do(Aに〜することを要求する)」の第5文型や、受動態の「be required to do(〜することが求められる)」が頻出。",
  "promotion": "pro-(前へ)+mot(動かす)で前進させる意。TOEICでは「昇進（earn a promotion）」と「販売促進（sales promotion）」の2つの意味を押さえるのがポイント。",
  "existing": "exist(存在する)の形容詞用法。TOEICでは existing customers（既存客）や existing equipment（既存設備）など、名詞を前から修飾する形で頻出。",
  "option": "語根opt(選ぶ)から派生。TOEICでは have the option to do（〜する選択肢がある）や payment options（支払い方法）のような表現でよく見かける。",
  "mostly": "most(大部分)に副詞語尾-lyがついた語。mainlyと同義で、内容や構成が「大部分は〜である」と述べる際に使われる。almost（副詞でallや修飾語を伴う）との混同に注意。",
  "responsible": "re-(返して)+spons(答える)+-ibleで「返答する義務がある」。TOEICでは be responsible for（〜を担当している・責任がある）の形で頻出。",
  "merchandise": "merchant(商人)と同語源。TOEICでは「商品」を指す集合名詞で、不可算名詞（数えられない）扱いになる点が重要。可算名詞の goods や products と区別しよう。",
  "donation": "語根 don(与える)に由来。TOEICでは慈善活動や美術館支援の文脈で make a donation to ~（〜に寄付をする）や generous donation の形で頻出。",
  "hardly": "hardから派生したが「ほとんど〜ない」という準否定を表す。notを使わずに否定の意味になり、TOEICでは hardly any ~（ほとんど〜ない）の組み合わせでよく出る。",
  "arrival": "arriveの名詞形。TOEICでは upon arrival（到着時に）や on arrival（到着次第）の前置詞句、また estimated arrival date（到着予定日）の形で頻出。",
  "definitely": "de-(強意)+fin(境界を定める)+-lyで「はっきりと決定されて」が原義。TOEICでは definitely recommend（強くお勧めする）や返答の承諾で使われる。",
  "closely": "「物理的に近く」だけでなく「綿密に・注意深く」の意味を持つ。TOEICでは work closely with（〜と密に連携する）や examine closely の組み合わせが頻出。",
  "generous": "「寛大な・気前のよい」のほか、数量が「豊富な」という意味も持つ。TOEICでは generous donation（手厚い寄付）や generous offer（寛大な申し出）で定番。",
  "paperwork": "paper(書類)+work(作業)の複合語で、不可算名詞。TOEICでは complete the paperwork（書類手続きを済ませる）や fill out the paperwork として頻出。",
  "paid": "payの過去分詞から形容詞化。TOEICの人事・求人票では paid leave や paid vacation（有給休暇）、paid internship（有給インターン）の形で定番。",
  "hire": "動詞「雇う」に加え、TOEICでは new hire（新入社員・新規採用者）のように人を指す名詞としても頻出。recruit や employee と併せて押さえたい。",
  "below": "be-+low(低い)で「基準より下に」。TOEICの業績報告では fall below expectations（期待を下回る）や below average（平均以下）の形で数値・基準とともに頻出。",
  "hold": "「手で持つ」から広がり、TOEICでは hold a meeting（会議を開く）という開催の用法と、電話応対の Please hold.（切らずにお待ちください）の両方で頻出。",
  "gradually": "語根 grad(歩み・段階)に由来し「一歩ずつ段階的に」が原義。TOEICではグラフ説明や売上動向で increase gradually（徐々に増加する）のように動詞の後ろで頻出。",
  "foundation": "語根 found(土台・底)から派生。TOEICでは lay the foundation for ~（〜の基礎を築く）という比喩的表現や、charitable foundation（慈善財団）の文脈で頻出。",
  "extremely": "ex-(外へ)+語根trem(果て)+-lyで「極限の領域まで」が原義。TOEICでは extremely pleased（大変満足した）や extremely helpful など形容詞を強める副詞として頻出。",
  "typical": "type(型)+-icalで「型に合致した」。TOEICでは It is typical of ~（〜にはよくあることだ）という構文や、a typical day（普段の1日）などの業務描写で使われる。",
  "refund": "re-(戻す)+fund(資金・注ぐ)で「お金を戻す」。TOEICでは名詞として full refund（全額返金）や issue a refund（返金手続きをする）の表現が頻出。",
  "facility": "fac(行う・作る)から「活動を容易にする設備」の意。TOEICでは manufacturing facility（製造工場）や storage facilities（保管施設）など具体的な建物・設備を指す。",
  "appearance": "appear(現れる)の名詞形。TOEICでは店舗や商品の「外観」のほか、イベントやセミナーでの登壇を表す guest appearance（特別出演・登壇）の形でも頻出。",
  "else": "「他の」を意味し、something else や anyone else、nowhere else のように疑問詞や不定代名詞の後ろに置いて後置修飾するのが文法上のポイント。",
  "fashion": "「流行」だけでなく「様式・やり方」の意味がある。TOEICでは in a timely fashion（迅速・タイムリーに）というコロケーションが Part 5 や社内通知で頻出。",
  "response": "re-(返して)+spons(答える)で「返答」。TOEICでは in response to ~（〜への対応として・応えて）という群前置詞や、prompt response（素早い返信）が頻出。",
  "maintain": "manu(手)+tain(保つ)で「手で握り保ち続ける」。TOEICでは maintain equipment（機器を保守・維持管理する）や maintain records（記録を保管する）の形で頻出。",
  "avenue": "ad-(〜へ)+ven(来る)で「向かう道」が原義。TOEICでは道順説明の「大通り」のほか、explore new avenues（新たな道・手段を模索する）のような比喩でも使われる。",
  "complex": "com-(共に)+plex(編む)で「編み合わさって入り組んだ」。形容詞「複雑な」のほか、TOEICでは apartment complex（集合住宅）や office complex（複合ビル）の名詞用法も頻出。",
  "absolutely": "ab-(離れて)+solut(解き放たれた)で「束縛なく完全に」。absolutely necessary など形容詞を強調するほか、リスニングの応答で「その通りです」と同調する際にも頻出。",
  "receipt": "re-(再び)+ceipt(受け取る)で「受領、領収書」。p は発音しない。可算名詞の keep the receipt（レシートを保管する）や、不可算名詞の upon receipt of ~（受領次第）で頻出。",
  "participate": "parti(部分)+cip(取る)で「一部に加わる」。自動詞で前置詞 in を伴い participate in the seminar のように使う。前置詞を取らない他動詞 attend との区別が頻出。",
  "flyer/flier": "fly(飛ぶ)+-erで「風に舞うような宣伝ビラ」。distribute flyers（チラシを配る）の連語や、Part 7 で新装開店やイベントを知らせる告知文書としてよく登場する。",
  "complain": "com-(強調)+plain(嘆く)で「不満を述べる」。自動詞で complain about the service や complain that 節の形を取る。名詞 complaint（苦情）と共に顧客対応で頻出。",
  "secretary": "secret(秘密)+-ary(人)で「機密情報を管理する人」が原義。役員の日程調整や連絡を担う executive secretary（役員秘書）や、会議の議事録作成を担当する文脈でよく登場する。",
  "complicated": "com-(共に)+plic(折る)で「幾重にも折り重なった→複雑な」。a complicated process（複雑な手順）や a complicated issue のように難解な状況を表す。",
  "prevent": "pre-(前に)+vent(来る)で「先回りして塞ぐ→防ぐ」。最重要語法は〈prevent A from -ing〉（Aが〜するのを妨げる）で、悪天候による工事の遅れや事故防止などの文脈で頻出。",
  "slightly": "slight(わずかな)+-ly。slightly different from ~ のように比較・相違を和らげるほか、increase slightly（微増する）など業績報告の数値変動で頻出。",
  "afford": "助動詞 can を伴い can afford to do（〜する余裕がある）の形で用いるのが基本。派生語の affordable（手頃な）は affordable prices として頻出。",
  "whether": "「2つのうちどちらか」から「〜かどうか」。whether or not や whether A or B の形を取る。前置詞の直後や不定詞の前（whether to do）で if ではなく選ばせる問題が頻出。",
  "instrument": "in-(上に)+stru(築く)+-mentで「作業のための機器」。musical instrument（楽器）だけでなく、工場や研究所で measuring instrument（測定器具）の意味でも登場する。",
  "ensure": "en-(〜にする)+sure(確実な)で「確実に保証する」。ensure that 節や ensure safety（安全を確保する）の形を取る。人を目的語にして保証する assure との区別が重要。",
  "hesitate": "足が止まることが原義。TOEIC ではメールの結び文句〈Please do not hesitate to contact us.〉（遠慮なくご連絡ください）として頻出。〈hesitate to do〉の形を取る。",
  "honor": "式典の告知などで in honor of ~（〜を祝して／〜に敬意を表して）の形で頻出。動詞では功績を称えて「表彰する」のほか、honor a coupon（クーポンを受け付ける）の意味も持つ。",
  "vast": "ラテン語の「見渡す限りの広大さ」が語源。広さだけでなく量も表し、the vast majority of ~（〜の圧倒的多数）や vast experience（豊富な経験）の形で登場する。",
  "shortly": "short(短い)+-lyで「まもなく」。will arrive shortly のように未来表現と共に使うほか、shortly before / after ~（〜の直前／直後）の形が Part 5 で頻出。",
  "either": "「2者のどちらか」が原義。最重要語法は相関接続詞〈either A or B〉（AかBのどちらか）。また either of + 複数名詞が主語に来る場合は通例、単数動詞で受ける点も注意。",
  "reference": "re-(戻す)+fer(運ぶ)で「照会・参照」。メール添付時の for your reference（ご参考までに）や、採用での check references（身元照会先を確認する）の形で頻出。",
  "merger": "merge(溶け合う)+-erで「企業の合併」。negotiate a merger（合併を交渉する）や merger and acquisition（M&A）の形で、ビジネス記事や社内通知に頻出。",
  "engineering": "ingenium(工夫・才能)に由来。機械工学だけでなく土木や設計を含み、engineering firm（工学・設計会社）や an engineering degree（工学学位）など技術職の求人で頻出。",
  "instruction": "in-(中に)+struct(築く)で「指示、教育」。製品の使用法や手順を指す際は通例複数形で instructions となり、follow instructions（指示・説明書に従う）の連語で頻出。",
  "perhaps": "per-(〜により)+hap(偶然)で「ことによると」。maybe より丁寧な響きがあり、リスニングで Perhaps we could... のように控えめに提案や代替案を切り出す際に使われる。",
  "performance": "per-(完全に)+form(形づくる)で「成し遂げること」。公演・演奏の意味のほか、ビジネスでは job performance（勤務実績）や performance review（人事考課）の形で頻出。",
  "assembly": "as-(〜へ)+simul(共に)で「集めること」。製品の組み立ての意味で assembly line（組み立てライン）や assembly instructions（組み立て説明書）として工場や家具の文脈で頻出。",
  "useful": "use(使う)+-ful(満ちた)で「使い道が多い」。useful information（有益な情報）の形でよく使われ、Part 7 では helpful や informative への同義語言い換えとして頻出。",
  "post": "ラテン語の「定位置に置かれたもの」が語源。名詞では「役職」（post of director）を表し position と同義。動詞では post an announcement（告知を掲示する）の形で頻出。",
  "term": "ラテン語の「境界・期限」が語源。複数形 terms で「契約条件」（terms of agreement, payment terms）を表す用法が頻出。熟語 in terms of ~（〜の観点から）も重要。",
  "committee": "com-(共に)+mit(委ねる)で「任務を委託された集団」。planning committee（企画委員会）や search committee（選考委員会）のように社内組織や人事選考の文脈で頻出。",
  "aware": "ware(警戒する)と同根で「注意を払って気づいている」。最重要語法は〈be aware of ~〉や〈be aware that 節〉。名詞形も raise awareness（意識を高める）の連語で頻出。",
  "expense": "ex-(外へ)+pens(支払う)が語源。TOEICでは出張経費の travel expenses や、cover expenses(費用を賄う)、at great expense(多額の費用で)の形でよく使われる。",
  "praise": "price(価値)と同語源で、価値を認めて褒めること。TOEICでは praise A for B(AをBのことで称賛する)や receive praise(称賛を受ける)のように評価の文脈で登場する。",
  "balance": "天秤の2枚の皿が釣り合うことが原義。TOEICでは「均衡」だけでなく、account balance(口座残高)や remaining balance(未払い残高)など会計上の「残高」の意味で頻出する。",
  "compete": "com-(共に)+petere(求める)が語源で、同じ目標を競い合うこと。compete with/against(〜と競う)や、派生語の competitive price(競争力のある価格)がよく問われる。",
  "catering": "cater(飲食物を調達して賄う)の名詞形。社内イベント等の文脈で catering service(仕出し)として出るほか、動詞の cater to(〜の要望に応じる)の前置詞用法も重要。",
  "entire": "integer(完全な・欠けていない)と同語源。TOEICでは the entire staff や the entire company のように「the entire + 単数名詞」で全体をまとめて表す形が定番。",
  "difficulty": "dif-(否定)+facil(容易な)で「容易でないこと」。TOEICでは have difficulty (in) -ing(〜するのに苦労する)の動名詞語法や technical difficulties(機械トラブル)が頻出。",
  "prefer": "pre-(前に)+fer(運ぶ)で「他より前に置く→優先して好む」。TOEICでは prefer A to B(BよりAを好む)と、比較対象に than ではなく to を使う語法がPart 5で狙われやすい。",
  "issue": "「外へ出る・出す」が原義。TOEICでは名詞「最新号(latest issue)」「問題(address an issue)」、動詞「発行する(issue a refund/pass)」と多義にわたって使われる。",
  "inn": "古英語の「住まい・中」に由来し、中に入って休む場所を指す。TOEICでは Part 7 の旅行や出張のメール・予約確認書で、Holiday Inn などのように小規模なホテルや宿の名前に使われる。",
  "describe": "de-(書き下ろして)+scribe(書く)が語源。TOEICでは as described below(後述の通り)や設問の「What is described about ~?」など、手順や状況を説明する文脈で頻出。",
  "comparison": "com-(共に)+par(等しい)が語源で、2つを並べて比べること。in comparison with/to(〜と比較して)や by comparison(それに比べて)の前置詞フレーズでよく出題される。",
  "remind": "re-(再び)+mind(心)で「再び心に呼び戻す」。TOEICでは remind 人 to do(人に〜するよう念を押す)や remind 人 of ~(〜を思い出させる)という目的語の語法が狙われやすい。",
  "permanent": "per-(ずっと)+manere(留まる)で「ずっと留まり続ける」。TOEICでは temporary(一時的な)の対義語として、permanent position(正社員の職)や permanent staff の形でよく使われる。",
  "regret": "TOEICでは通知メールの定型表現「We regret to inform/announce that ~(残念ながら〜とお知らせいたします)」が定番。後ろに不定詞(to do)を取る点も重要。",
  "replacement": "re-(再び)+place(置く)+mentで「元の場所に代わりを置くこと」。TOEICでは不良品の「交換品」だけでなく、退職者の「後任(replacement for Mr. ~)」の意味でもよく使われる。",
  "above": "「〜の上に」を表す語だが、TOEICの文書やメールでは as mentioned above(上述の通り)や the address above(上記住所)のように「上記の・上述の」という意味で頻繁に登場する。",
  "waste": "vast(空っぽの)と同語源。TOEICでは「時間を浪費する(waste time)」だけでなく、環境や工場の文脈で hazardous waste(有害廃棄物)や waste disposal(廃棄物処理)としても頻出。",
  "though": "although と同じく譲歩を表す接続詞。TOEICでは despite や in spite of(前置詞)との品詞識別問題が定番。また、文末に単独で置いて「〜だけどね」と添える副詞用法も会話文でよく出る。",
  "eager": "acid(鋭い)と同語源で、気が研ぎ澄まされて急く様子。TOEICでは be eager to do(しきりに〜したがっている)の形で、就職希望者の意欲や新規事業への熱意を述べる際によく使われる。",
  "represent": "re-(再び)+present(前に差し出す)で「代理として前に立つ」。TOEICでは represent the firm(会社を代表する)のほか、派生語 sales representative(営業担当者)の名詞識別が超頻出。",
  "wonder": "TOEICでは自問する意味だけでなく、相手に頼み事をする際の「I was wondering if you could ~(〜していただけないでしょうか)」という丁寧な依頼表現としてリスニングやメールで頻出。",
  "administrative": "ad-(〜へ)+minister(仕える者)で組織に仕えて運営すること。TOEICでは administrative assistant(総務アシスタント・秘書)や administrative duties(事務職務)の連語で頻出。",
  "alternative": "alter(もう一方の・他の)が語源。TOEICでは alternative date(別の日程)や alternative plan(代替案)という形容詞のほか、an alternative to ~(〜の代案)と名詞でもよく使われる。",
  "banquet": "bench(ベンチ)と同語源で、長椅子に大勢で並んで食べる宴が原義。TOEICでは annual banquet(年次晩餐会)や awards banquet(授賞式ディナー)、banquet room(宴会場)として頻出。",
  "design": "de-(下に)+sign(印をつける)で「図面を引いて計画する」。TOEICでは製品や建物の設計のほか、be designed to do(〜するように設計・意図されている)という受動態の目的表現が頻出。",
  "treat": "ラテン語の「手で扱う」が原義。TOEICでは「扱う」に加え、treat A to lunch(Aに昼食をごちそうする)や It's my treat.(私のおごりです)という食事や接待の口語表現としてもよく出る。",
  "usual": "use(使う・慣れる)と同語源で「普段使いの」。TOEICでは as usual(いつも通り)や heavier than usual(いつもより混雑して)、usual business hours(通常営業時間)の形でよく使われる。",
  "serve": "service(仕える・奉仕する)と同語源。TOEICでは「食事を出す(serve lunch)」だけでなく、serve as director(役職を務める)や serve customers(顧客に対応する)など多義に活躍する。",
  "particularly": "part(部分)から派生し、全体の中から「特定の一部分を際立たせる」語。TOEICでは particularly useful や particularly interested のように形容詞を修飾して強調する文脈で頻出。",
  "commission": "com-(共に)+mission(送ること)で任務を任せること。名詞で「委託」「手数料(歩合)」のほか、be commissioned to do(〜するよう依頼される)と受動態の動詞でも使われる。",
  "recover": "re-(再び)+cover(手に入れる)から「回復する」。「recover from ~」の形で前置詞 from を伴い、不況や損害からの立ち直りを表すのが定番。",
  "aspect": "a-(〜へ)+spect(見る)で、ある視点から見た姿→「側面・観点」。「every aspect of the project(事業のあらゆる側面)」のように多角的な検討で使われる。",
  "responsibility": "responsible(責任がある)+-ity。前置詞 for を伴い、「take responsibility for ~(〜の責任を負う)」や、求人票で職責を表す job responsibilities が頻出。",
  "law": "「置かれた定め」が原義。コンプライアンスの文脈で「observe / obey the law(法律を遵守する)」や、義務を表す「by law(法律上・法によって)」の定型句でよく登場する。",
  "envelope": "en-(中に)+velop(包む)で「包み込むもの」。返信を促す文脈で「a self-addressed stamped envelope(宛名と切手を貼った返信用封筒)」という定型表現がPart 7で頻出。",
  "track": "「足跡をたどる」ことから「追跡する」。荷物配送のメールで「track your shipment(荷物を追跡する)」や「keep track of expenses(経費を把握する)」の形で多用される。",
  "estimate": "動詞「見積もる」だけでなく、名詞「見積書」としての用法が重要。free estimate(無料見積もり)や provide an estimate(見積もりを出す)の形で修理や工事の連絡に登場する。",
  "certificate": "cert-(確かな)+fic(作る)で「証明するもの」。「gift certificate(商品券)」や「certificate of attendance(出席証明書)」の組み合わせでよく出題される。",
  "feature": "名詞「特徴」のほか、動詞「大きく取り上げる・目玉にする」が頻出。雑誌記事や広告で「feature an interview with ~(〜の特集記事を掲載する)」のように他動詞として使われる。",
  "following": "「次の・下記の」を表す形容詞のほか、「after」と同義の前置詞として「following the meeting(会議の後に)」のように時間を表す用法が Part 5 で狙われやすい。",
  "found": "foundation(土台)と同語源で「設立する」。find の過去形と同形だが、原形動詞として「found a company(会社を設立する)」のように使われる。",
  "employer": "employ(雇う)+-er(する人)で「雇い主・雇用企業」。「雇われる人」を表す employee(従業員)との区別が必須で、求人票や就業規則で主語や条件の提示主体として登場する。",
  "previous": "pre-(前に)+via(道)で「道の手前にある→以前の」。「previous experience(過去の実務経験)」や「previous quarter(前期)」の形でよく使われる。",
  "nearly": "near(近い)+-lyで「数値に限りなく近い」ことから「ほぼ・およそ」。almostと同様に「nearly 50%」や「nearly completed」のように数詞や完了状態を修飾する副詞として頻出。",
  "lower": "形容詞 low の比較級から転じた動詞で「〜を下げる」。「lower prices(値下げする)」や「lower costs(コストを削減する)」のように、経費削減や販売促進の文脈で他動詞として頻出。",
  "express": "ex-(外へ)+press(押す)で「外に表す」。「express gratitude(感謝を伝える)」や「express interest in ~(〜に関心を示す)」というコロケーションが頻出。",
  "examine": "天秤で重さを慎重に量ることが原義。「examine a document(書類を精査する)」や「examine ~ for defects(欠陥がないか検査する)」のように使われる。",
  "firm": "ラテン語の「堅固な」から、署名で確定した事業体＝「会社」を表す。「law firm(法律事務所)」や「consulting firm(コンサル会社)」のように専門性の高い事業組織を指す名詞として頻出。",
  "whole": "healthy と同語源で「欠けのない全体」。「the whole team」のように「the whole + 単数名詞」の語順で使い、「all the + 複数名詞」と区別される。",
  "assign": "as-(〜へ)+sign(印をつける)で「割り振る」。「assign tasks to team members(業務を割り振る)」や受動態「be assigned to ~(〜に配属される)」が頻出。",
  "manufacturer": "manu-(手)+fact(作る)から「製造業者・メーカー」。日本語の「メーカー」に相当し、工場や調達の文脈で「a leading manufacturer(大手メーカー)」として頻出。",
  "journal": "journey と同語源で「日々の記録」から「定期刊行物」。「medical journal(医学雑誌)」や「trade journal(業界誌)」のように、専門分野の刊行物を指す。",
  "sculpture": "sculp(彫る)+-tureで「彫刻作品」。Part 1の写真描写で「a sculpture is on display(彫刻が展示されている)」など、展示物や鑑賞動作の描写で登場する。",
  "department": "part(分ける)から組織を切り分けた「部門・部署」。「sales department(営業部)」や「department head(部長)」のように社内組織を表す定番語。",
  "proof": "動詞 prove(証明する)の名詞形。返品や経費精算の手続きで「proof of purchase(購入証明・レシート)」や「proof of payment(支払い証明)」の定型句で使われる。",
  "specific": "species(種)と同語根で「他と区別された」が原義。「specific details(詳細な情報)」や「specific instructions(具体的な指示)」のように明確さを表す。",
  "obtain": "ob-(向かって)+tain(つかむ)で「手に入れる」。改まった語で、「obtain permission(許可を得る)」や「obtain approval(承認を取り付ける)」の形で頻出。",
  "path": "名詞「小道・進路」。Part 1の写真描写で「along the path(小道に沿って)」と歩道や公園の描写で出たり、ビジネス文脈で「career path(キャリアの歩み)」として比喩的に使われたりする。",
  "notify": "noti-(知る)+fy(〜化する)で「知らせる」。「notify A of B(AにBを通知する)」や「notify A that 節」の形を取り、直後に通知先の「人」を置く語法が頻出。",
  "admission": "ad-(〜へ)+mit(送る)で「中へ入るのを認めること」。TOEICでは admission fee（入場料）や admission ticket（入場券）などの複合名詞で頻出。",
  "tip": "「助言」の意味では可算名詞で、不可算名詞の advice と区別されます。TOEICでは useful tips や tips for の形でよく登場します。",
  "inventory": "in-(中に)+vent(来る)で「見出した品々」。TOEICでは「在庫」の意味で、take inventory（棚卸しをする）や inventory control（在庫管理）が頻出。",
  "extension": "ex-(外へ)+tens(伸ばす)。TOEICでは「締め切りの延長（request an extension）」や、電話の「内線番号（extension 204）」の意味で頻出です。",
  "prior": "ラテン語で「前の」が語源。TOEICでは prior to ...（〜の前に = before）の前置詞句や、prior notice（事前通知）の形で頻出。",
  "extensive": "ex-(外へ)+tens(伸ばす)+-iveで「外に広く伸びた」。TOEICでは extensive knowledge（幅広い知識）や extensive repairs（大規模な改修）の形で頻出。",
  "bench": "Part 1の写真問題で頻出。A bench is unoccupied（ベンチは空いている）や overlook、shaded などの受動態表現と共に公園・広場の描写でよく出ます。",
  "district": "dis-(離れて)+strict(縛る)で「管轄下に区切られた区域」。TOEICでは business district（商業地区）や financial district（金融街）の形で頻出。",
  "amount": "ad-(〜へ)+mount(登る)で「積み上がった総額」。TOEICでは不可算名詞（money等）に使い a large amount of で頻出。可算名詞に使う number と区別。",
  "revise": "re-(再び)+vis(見る)で「見直して直す」。TOEICでは revise a proposal（提案書を修正する）や revised schedule（変更後の予定）の形で頻出。",
  "appear": "appear to do（〜のようだ = seem to do）で頻出。自動詞のため受動態（be appeared）にできない文法ポイントのほか、記事が「掲載される」の意味でも出ます。",
  "train": "ラテン語で「引く」が語源で、人を導いて伸ばすこと。TOEICでは動詞で train new employees（新入社員を育成する）や training session（研修会）で頻出。",
  "load": "Part 1の写真問題で頻出。load luggage into a cart や be loaded onto a truck（積み込まれている）の形で出ます。反意語 unload（荷を降ろす）も要チェック。",
  "popularity": "popul-(民衆)+-ityで「人々に支持されていること」。TOEICでは gain popularity（人気を博す）や growing popularity（高まる人気）の形で頻出。",
  "significant": "sign-(印)+fic(作る)で「意味のある印がある」→「重要な・著しい」。TOEICでは significant increase（著しい増加）や副詞 significantly（大幅に）で頻出。",
  "leading": "動詞 lead（先導する）の現在分詞から派生。TOEICでは a leading manufacturer（大手メーカー）や a leading provider（主要供給元）の形で頻出。",
  "defective": "de-(離れて)+fect(作る)で「基準通りに作られていない」。TOEICでは return defective products（欠陥品を返品する）や名詞 defect（欠陥）との品詞識別で頻出。",
  "patient": "ラテン語で「耐える」が語源。TOEICでは名詞「患者」のほか、お知らせで Please be patient with us.（少々お待ちください・ご容赦ください）の形容詞でも出ます。",
  "rather": "would rather do A than do B（BするよりむしろAしたい）や rather than ...（〜ではなく）の形で頻出。Part 5やPart 3/4の選択肢言い換えでよく狙われます。",
  "setting": "set（置く）の名詞形。TOEICでは「（式典などの）環境・舞台（an ideal setting for the gala）」や、機器・ソフトの「初期設定（default settings）」で出ます。",
  "willing": "will（意志）+-ingで「意志を持っている」。TOEICでは be willing to do（喜んで〜する、〜するのをいとわない）の定型表現で頻出。対義語 reluctant（気が進まない）も重要。",
  "renowned": "re-(強調)+noun(名前)で「名声が轟いている」。TOEICでは a world-renowned architect（世界的に有名な建築家）など、講演者や専門家を紹介する文脈で頻出。",
  "clerk": "中世の聖職者（cleric）が語源。TOEICでは sales clerk（販売店員）や desk clerk（ホテルのフロント係）のように、接客・事務スタッフを表す語としてリスニングで頻出。",
  "contract": "con-(共に)+tract(引く)で「互いに引き合って合意する」。TOEICでは sign a contract（契約を結ぶ）や renew a contract（契約を更新する）の動詞とセットで頻出。",
  "respond": "re-(折り返し)+spond(誓う)で「応える」。自動詞として前置詞 to を伴い respond to inquiries（問い合わせに返信する）の形で頻出。他動詞 answer との違いも重要。",
  "itinerary": "ラテン語 iter（道・旅）が語源。TOEICでは出張の手配やツアー案内で a detailed itinerary（旅程表）として頻出。移動を含む日程を指し、会議の agenda（議題）と区別。",
  "forward": "fore-(前へ)+-ward(方向)。メールや書類を「転送する」動詞で forward an email to ... の形で超頻出。look forward to -ing（〜を楽しみに待つ）も必修。",
  "committed": "com-(完全に)+mit(委ねる)。be committed to -ing / noun（〜に全力を注ぐ）で頻出。to は前置詞なので、直後に動詞原形ではなく動名詞（-ing）が来る点が文法の急所。",
  "brochure": "フランス語で「仮綴じされた小冊子」が語源。TOEICでは travel brochure（旅行案内パンフレット）などの形で頻出。1枚もののチラシ（flyer）と区別されます。",
  "quite": "「完全に」が原義。TOEICでは「かなり」の意味で quite a few（かなりの数の〜）や quite a while（長い間）で頻出。語順 quite a + 形容詞 + 名詞 も要チェック。",
  "degree": "de-(下に)+gree(段階)で「歩みの段階」。TOEICでは人事・履歴書で hold a degree in ...（〜の学位を持つ）や bachelor's degree（学士号）の形で頻出。",
  "regard": "re-(じっと)+gard(見る)で「配慮して見る→みなす」。TOEICでは受動態 be regarded as ...（〜とみなされる）や前置詞 regarding（〜に関して）が狙われやすい。",
  "popular": "popul(人々)に由来し「大衆向けの」。TOEICでは be popular with [among] customers（顧客に人気がある）のように前置詞 with/among との連結が定番。",
  "former": "古英語の「最初の」に由来する。TOEICでは the former（前者）のほか、former employee（元社員）のように役職や立場の前で「前〜、元〜」として頻出。",
  "fine": "fin(終わり)が語源で、訴訟を終わらせる支払いから「罰金」に。TOEICでは名詞「罰金」（pay a fine）や be fined for ...（〜で罰金を科される）で出やすい。",
  "state": "stat(立つ)が語源で「定まった状態」、転じて「公に述べる」。TOEICでは As stated in ...（〜に記載の通り）や派生語 statement（明細書・声明）が頻出。",
  "lately": "late(遅い)の副詞形で「ごく最近」。過去形でも使える recently と異なり、lately は主に現在完了形（have done）を伴う点がTOEIC文法問題での識別点。",
  "relatively": "relate(関連づける)の派生語で「他と比較して」。TOEICでは relatively low [small] のように形容詞を修飾し、数値を客観的に和らげる表現で頻出。",
  "row": "古英語に由来し「一連の並び」。TOEICでは座席の the front row（最前列）のほか、three days in a row（3日連続で）の成句が頻出。",
  "cooperation": "co-(共に)+operate(働く)で「協働」。TOEICではアナウンスやメール結びの Thank you for your cooperation.（ご協力感謝します）が定番。",
  "refer": "re-(元へ)+fer(運ぶ)で「参照する」。自動詞なので前置詞 to を伴う refer to the manual（説明書を参照する）や名詞 reference（推薦状）が頻出。",
  "often": "古英語由来の頻度副詞。TOEICのPart 2では How often ...?（頻度はどのくらいか）に対し、twice a month や daily で答える応答パターンが頻出。",
  "fare": "「旅する」を表す古語に由来し、乗り物の「運賃」を指す。TOEICでは bus fare や airfare（航空運賃）に使われ、手数料 fee や通行料 toll と区別される。",
  "assure": "as-(〜へ)+sure(確実な)で「人を安心させる」。TOEICでは assure 人 that ... や assure 人 of ... の形をとり、人を直接挟まない ensure との語法差が急所。",
  "renovation": "re-(再び)+nov(新しい)で「改修」。TOEICでは施設の一時休業の理由として under renovation（改装中）の前置詞句がリスニング・読解ともによく出る。",
  "last": "古英語の「続く」に由来する動詞。TOEICでは自動詞として The sale lasts until Friday.（セールは金曜まで続く）のように期間や期限を伴って頻出。",
  "present": "pre-(前に)+sent(ある)で「目の前に出す」。動詞（後ろアクセント）では present one's ID（身分証を提示する）や present an award（授賞する）の形で頻出。",
  "matter": "materialと同語源で「重要事」。名詞では a routine matter（日常業務の案件）、動詞では It doesn't matter ...（重要ではない）の形で会話によく出る。",
  "distribute": "dis-(あちこちに)+tribute(与える)で「配分する」。TOEICでは会議で distribute handouts（資料を配る）や流通の distribute products として頻出。",
  "procedure": "pro-(前へ)+cede(進む)で「手順・手続き」。TOEICでは follow standard procedures（標準手順に従う）のように、規則や社内マニュアルで複数形が頻出。",
  "identify": "ident(同一の)+-fy(化する)で「特定する」。TOEICでは identify the cause of the problem（原因を特定する）や defects（欠陥）の発見の文脈で頻出。",
  "ingredient": "in-(中に)+gredi(入る)で「構成要素」。TOEICでは料理・製品の「原材料」として使われ、all-natural ingredients（天然原料）や食品表示で頻出。",
  "extended": "ex-(外へ)+tend(伸ばす)で「延長された」。TOEICでは an extended warranty（延長保証）や extended hours（延長営業）のコロケーションが定番。",
  "effort": "ef-(強意)+fort(力)で「力を出すこと」。make an effort to do のほか、目的を表す in an effort to do（〜しようと努めて）という前置詞句がTOEIC読解で頻出。",
  "actually": "act(現実)の副詞形で「実は」。TOEICのPart 2では、相手の質問や提案に対して Actually, ... と切り出して婉曲に断る・訂正する間接応答のサインになる。",
  "involved": "in-(中に)+volve(巻く)で「関与した」。TOEICでは be involved in ...（〜に関わる）や the people involved（関係者）と名詞を後ろから修飾する形で頻出。",
  "further": "far(遠い)の比較級で「程度の進展」。TOEICでは For further information, please contact us.（詳細はお問い合わせください）のメール定型句が定番。",
  "institution": "in-(中に)+stitute(立てる)で「設立された組織」。TOEICでは financial institution（金融機関）や educational institution（教育機関）として頻出。",
  "familiar": "family(家族)と同語源で「熟知した」。TOEICでは人が主語の be familiar with the software（ソフトに精通している）のように前置詞 with と共に頻出。",
  "sincerely": "sincere(偽りのない)の副詞。TOEICではビジネスメールの結語（Sincerely,）のほか、sincerely apologize for ...（心より謝罪する）の形で頻出。",
  "council": "con-(共に)+calare(呼ぶ)が語源で、同音の counsel(助言・弁護士)との混同に注意。TOEICでは city council(市議会)の形で定番。",
  "complimentary": "compliment(賛辞)から「敬意を表して進呈する→無料の」に変化。綴りが似た complementary(補完的な)と区別し、complimentary breakfast を覚えよう。",
  "grant": "古フランス語の「信用して認める」が原義。動詞 grant permission(許可を与える)のほか、名詞「助成金・補助金」(research grant)の意味も狙われやすい。",
  "prepare": "pre-(前もって)+pare(整える)で「準備する」。自動詞 prepare for ...(〜の準備をする)と他動詞 prepare a report(報告書を作成する)の両方で使われる。",
  "lawn": "開けた草地を表す古語に由来する。TOEICではPart 1の写真問題で mow the lawn(芝生を刈る)や lawn mower(芝刈り機)を押す描写として頻出。",
  "impress": "im-(中に)+press(押す)で「心に刻みつける」。TOEICでは受動態の be impressed with [by] ...(〜に感銘を受ける)や形容詞 impressive(印象的な)が頻出。",
  "affordable": "afford(余裕がある)+-able(できる)で「買う余裕がある→手頃な」。TOEICでは affordable prices [rates](手頃な価格)の形で広告文に頻出。",
  "principal": "primi-(第一の)+cap(頭)で「主要な」を意味し、同音の principle(原理・原則)との識別が急所。形容詞 principal reason(主な理由)の形で頻出。",
  "memo": "memorandum(記憶すべき事柄)の短縮形。TOEICのPart 7では To/From/Date/Subject で始まる社内通達の文書形式そのものとして頻出。",
  "explore": "ex-(外へ)+plorare(叫ぶ・探る)が語源。TOEICでは探検だけでなく、explore options [possibilities](選択肢・可能性を検討する)というビジネス語法で頻出。",
  "address": "ad-(〜へ)+dress(向ける)に由来する。名詞「住所」だけでなく、動詞として address an issue(問題に対処する)の語法が頻出。",
  "patience": "耐えることを意味するラテン語に由来し、patient の名詞形。遅延や案内文の結びで Thank you for your patience.(ご辛抱感謝します)が定番。",
  "representative": "re-(再び)+present(示す)+-ive(人)で「代表者」。語尾は-iveだが「人」を表す名詞で、sales representative(営業担当者)のように使われる。",
  "apply": "ap-(〜へ)+ply(折り重ねる)が語源。前置詞の使い分けが急所で、apply for a job(仕事に応募する)と apply to ...(〜に適用される)を区別しよう。",
  "claim": "clamare(叫ぶ)が語源で、日本語の「苦情(complaint)」と異なり正当な権利を要求することを指す。baggage claim や保険金請求で頻出。",
  "program": "pro-(前に)+gram(書かれたもの)で「前もって告知された予定表」。TOEICでは training program(研修制度)や催しの進行表(日程表)として頻出。",
  "means": "mean(中間)から生じ、目的を達成する仲立ちを表す。末尾に -s があるが単数扱いも可能で、a means of transportation(交通手段)の形が定番。",
  "process": "pro-(前へ)+cess(進む)で「進行手順」。名詞「工程・手順」のほか、動詞として process an order [application](注文・申請を処理する)が頻出。",
  "fairly": "fair(整った)+-lyから成る副詞。TOEICでは「公平に」よりも程度を表す「かなり」の意味で出やすく、in fairly good condition などで使われる。",
  "landscaping": "landscape(風景を整える)に由来する。オフィスの敷地管理や施設案内で landscaping company(造園業者)や庭木の手入れサービスとして登場する。",
  "accompany": "ac-(〜へ)+company(仲間)で「仲間として付き添う」。他動詞のため前置詞不要で、受動態 be accompanied by ...(〜を同伴・添付する)の形が頻出。",
  "findings": "find(見つける)から「見出された事実」を表す。TOEICでは市場調査やアンケートの「調査結果」として常に複数形の findings で登場する。",
  "deserve": "de-(強意)+serve(仕える)で「奉仕の対価として受けるに値する」。deserve a promotion(昇進に値する)のように表彰や人事推薦の文脈で頻出。",
  "practical": "practice(実践)に由来する形容詞。TOEICでは研修や求人の文脈で practical experience(実務経験)や practical advice(実践的な助言)の形で頻出。",
  "note": "「印をつける」を表すラテン語が語源。案内文やメールでは Please note that ...(〜にご留意ください)の形で重要事項を知らせる定型表現として頻出。",
  "eligible": "e-(外へ)+lig(選ぶ)+-ibleで「選ばれる資格がある」。be eligible for ...(〜の資格がある)や be eligible to do の形で昇進や割引の条件文に頻出。",
  "behind": "be-+hind(後方)で「後ろに」が原義。進捗や運行の遅れを表す behind schedule(予定より遅れて)が定番で、対義語 ahead of schedule と対比される。",
  "occasionally": "occasion(好機・行事)から「機会がある時に限って→時々」。sometimes より改まった響きで、業務の頻度を尋ねる Part 2 の応答や日常業務の説明で使われる。",
  "delighted": "de-(強意)+lacere(引きつける)が語源。TOEICではメール冒頭などの be delighted to do(喜んで〜する)や be delighted with ...(〜に満足している)が頻出。",
  "preserve": "pre-(前もって)+serve(守る)で「壊れないよう守る」。歴史的建造物の保護(preserve historic sites)や重要文書の保管などの文脈で使われる。",
  "throughout": "through(通り抜けて)+out(完全に)で「端から端まで」。TOEICでは前置詞として時間（throughout the year）と場所（throughout the country）の両方で頻出。",
  "likely": "like(ありそうな)+lyで「〜しそうな」を表す形容詞。TOEICでは be likely to do（〜しそうである）や It is likely that 節の重要構文として頻出。",
  "imply": "im-(中に)+ply(折る)で「中に包み込む→ほのめかす」。TOEICではPart 7の設問「What is implied about ...?（〜について何が示唆されているか）」で頻出。",
  "due": "ラテン語の「負っている」に由来し「支払われるべき→期限の」。TOEICでは be due on 日付（〜が期日）や be due to do（予定）、due to（〜のため）の用法差が狙われる。",
  "inquire": "in-(中に)+quire(求める)で「深く尋ねる」。TOEICでは自動詞 inquire about ...（〜について問い合わせる）の前置詞 about とのセットや名詞 inquiry が頻出。",
  "loyal": "ラテン語の「法を守る」に由来し「忠実な」。TOEICでは前置詞 to を伴う be loyal to や、loyal customer（常連客）の形で頻出。royal（王室の）との混同に注意。",
  "personnel": "フランス語由来で「全職員・人事部」。TOEICのPart 5では形が似ている personal（個人の、形容詞）との品詞・意味の識別問題や、personnel department（人事部）で頻出。",
  "directory": "direct(向ける)+-ory(場所・物)で「案内するもの」。TOEICでは staff directory（社員名簿）や building directory（館内案内図）など、Part 7の参照文書として頻出。",
  "valid": "val(強い・価値がある)が語源で「効力がある」。TOEICでは valid for 30 days（30日間有効）のように期限を示す for との連結や、valid ID（有効な身分証）で頻出。",
  "proceed": "pro-(前方へ)+ceed(進む)で「前進する」。TOEICでは proceed with the plan（計画を進める）のほか、複数形 proceeds が名詞で「収益金・売上高」を表す用法が頻出。",
  "sponsor": "ラテン語の「誓約する」に由来。TOEICでは名詞「後援者」だけでなく動詞「〜を協賛する」（sponsor an event）としても出題される。corporate sponsor（協賛企業）が定番。",
  "challenging": "challenge に由来し、TOEICでは difficult（難しい）を前向きに言い換えた「やりがいのある」の意味で頻出。a challenging task（やりがいのある職務）などで好んで使われる。",
  "campaign": "ラテン語 campus(野原)に由来し「組織的な活動」。TOEICでは launch a campaign（キャンペーンを開始する）のように動詞 launch や run との組み合わせが頻出。",
  "luxury": "ラテン語の「過剰・贅沢」が語源。TOEICでは名詞としてだけでなく、luxury hotel や luxury vehicle のように名詞の前で形容詞的に「高級な」として使われる形が頻出。",
  "routine": "route(道)に由来し「決められた道筋→日課」。TOEICでは名詞だけでなく、routine inspection（定期点検）や routine maintenance（定期保守）など形容詞としての用法が頻出。",
  "decorate": "ラテン語の「名誉を与える・飾る」に由来。TOEICでは店舗の内装や記念イベントで be decorated with ...（〜で飾られている）の形や、名詞 decoration（装飾）が頻出。",
  "evidence": "e-(外へ)+vid(見る)で「明白に見えるもの→証拠」。数えられない不可算名詞（冠詞 an や複数形 -s は不可）である点がTOEIC文法問題の急所。evidence to support ... が定番。",
  "essential": "essence(本質)+-ialで「本質的な→不可欠な」。TOEICでは be essential to [for] ... の前置詞の選択や、It is essential that 節内の動詞原形が狙われやすい。",
  "fluent": "flu(流れる)が語源で「滑らかに流れる」。TOEICでは求人広告の応募要件として be fluent in English（英語が流暢な）のように前置詞 in と結びつくパターンが頻出。",
  "highlight": "high(高く)+light(光)で「強い光を当てる」。TOEICでは名詞「見どころ・最重要点」のほか、動詞として highlight the need to do（〜の必要性を強調する）の形で頻出。",
  "chef": "フランス語の「長（chief）」に由来し、本来は「厨房の長」。TOEICではレストランやケータリングの文脈で executive chef（総料理長）や celebrity chef（有名シェフ）として頻出。",
  "flexible": "flex(曲げる)+-ible(できる)で「柔軟に曲がる」。TOEICでは flexible working hours（フレックス勤務）や flexible return policy（柔軟な返品規約）で頻出。",
  "source": "湧き出る「泉」が語源。TOEICでは source of information（情報源）などの名詞用法のほか、動詞「〜を現地調達する」（source parts locally）としても出題される。",
  "consumer": "consume(消費する)+-er(人)で「製品・サービスを使う人」。TOEICでは consumer demand（消費者需要）や consumer goods（消費財）など、市場レポートの複合名詞で頻出。",
  "recruit": "re-(再び)+crescere(育つ)で「補充する」。TOEICでは動詞「人材を募集する」（recruit staff）だけでなく、名詞「新人」（new recruits）としても頻出。",
  "household": "house(家)+hold(維持)で「世帯・家族」。TOEICでは household appliances（家庭用電化製品）や household income（世帯所得）など、広告や市場調査で頻出。",
  "domestic": "ラテン語 domus(家)に由来し「家庭の→国内の」。TOEICでは international（国際的な）の対義語として domestic flights（国内便）や domestic market（国内市場）の形で頻出。",
  "adjust": "ad-(〜へ)+just(正しく)で「正しい位置に合わせる」。TOEICでは adjust the schedule（日程を調整する）のほか、make adjustments to ...（〜を微調整する）の名詞形も頻出。",
  "behavior": "behave(自らを保つ→ふるまう)の名詞形。TOEICではマーケティングや市場調査の文脈で consumer behavior（消費者行動）、人事評価で employee behavior（勤務態度）として頻出。",
  "athletic": "ギリシャ語の「競技」に由来する athlete の形容詞形。TOEICでは athletic facilities（運動施設）や athletic footwear（運動靴）など、福利厚生やスポーツ用品広告の文脈で頻出。",
  "interior": "ラテン語で「より内側の」が原義。対義語 exterior（外側）との対比や、interior renovation（内装リフォーム）などの改装文脈で頻出します。",
  "motivate": "語根 mot（動かす）から派生。「motivate + 人 + to do（人に〜するやる気を起こさせる）」や受動態「be motivated to do」の語法が頻出です。",
  "recipe": "料理の調理法だけでなく「a recipe for success（成功の秘訣）」と比喩的にも使われます。名詞 receipt（領収書）とのスペル混同に注意しましょう。",
  "influence": "in-(中に)+flu(流れる)が語源。名詞では have an influence on と前置詞 on を伴いますが、動詞では他動詞のため前置詞不要で直接目的語を取ります。",
  "phase": "initial phase（初期段階）などの名詞用法のほか、動詞の phase in（段階的に導入する）、phase out（段階的に廃止する）という句動詞も頻出です。",
  "leak": "配管の水漏れだけでなく、ビジネスでは leak information（情報を漏らす）のように機密漏洩の文脈でも使われます。名詞と動詞で同形です。",
  "afterwards": "after+-wards（方向）から「その後で」を表す副詞。接続詞ではないため節はつなげず、文末や shortly afterwards（直後に）の形で使われます。",
  "colleague": "col-(共に)+leg-(選ばれた人)が語源で coworker のフォーマルな表現。大学を意味する college とスペルや発音が混同しやすいので注意が必要です。",
  "via": "ラテン語の「道」に由来する前置詞。via email（メールで）や via the website（ウェブサイト経由で）のように、通信手段や経由地を示す際に重宝されます。",
  "characteristic": "名詞では key characteristics（主要な特徴）と製品説明で頻出。形容詞では be characteristic of ~（〜に特有である）の形で前置詞 of を取ります。",
  "occupied": "occupy（占める）の過去分詞で、会議室や座席が「使用中・塞がっている」の意味で頻出します。対義語 vacant（空いている）とセットで押さえましょう。",
  "beforehand": "in advance と同義の副詞。文末に置かれ、register beforehand（事前登録する）や notify beforehand（事前に通知する）のように案内文でよく使われます。",
  "accomplished": "accomplish（達成する）から「熟練した・優れた」を表す形容詞に。an accomplished pianist や engineer のように人物紹介の文脈で頻出します。",
  "microwave": "micro-(微小な)+wave(波)が原義。名詞で「電子レンジ」を表すだけでなく動詞で「電子レンジで温める」の意味もあり、オフィスの休憩室設備などの案内文で見かけます。",
  "nevertheless": "however や nonetheless と同義の接続副詞。前文のマイナス面を受けつつ、文頭で「Nevertheless, S + V」と展開を逆接につなぐ標識として使われます。",
  "reliable": "rely（頼る）+-able から「頼りにできる」。reliable supplier（信頼できる納入業者）のように用い、be reliant on（〜に依存している）との混同に注意しましょう。",
  "translate": "trans-(越えて)+lat(運ぶ)が語源。「translate A into B（AをBに翻訳する）」の前置詞 into が定番で、比喩的に「結果につながる」の意味でも使われます。",
  "primary": "ラテン語 primus（第1の）に由来し、primary objective（主要目的）のように「主要な」の意味で頻出。副詞 primarily（主に）も合わせて押さえましょう。",
  "urban": "ラテン語 urbs（都市）が語源。urban development（都市開発）の形でよく使われ、対義語 rural（田舎の）や suburban（郊外の）と対比で問われます。",
  "relevant": "求人票の relevant experience（関連する職務経験）は定番。前置詞 to を伴う「be relevant to（〜に関連がある）」や対義語 irrelevant も重要です。",
  "consult": "前置詞なしで consult an expert（専門家に相談する）や consult a manual（説明書を参照する）と直接目的語を取る他動詞用法が狙われます。",
  "alert": "形容詞では「be alert to（〜を警戒している）」と前置詞 to を伴います。名詞では weather alert（気象警報）のように警報・通知の意味で頻出です。",
  "reception": "receive の名詞形。「受付（reception desk）」だけでなく、歓迎会や授賞式などの「歓迎会・祝賀会（welcome reception）」の意味でも頻出します。",
  "relocate": "re-(再び)+locate（配置する）で「場所を移す」。企業の「本社移転（relocate headquarters）」や転勤の文脈で頻出し、名詞形 relocation も重要です。",
  "belongings": "belong（属する）から派生し常に複数形。空港やホテルなどのアナウンスで「personal belongings（身の回りの手荷物・所持品）」の形で定番です。",
  "reward": "動詞では「reward A for B（Bに対してAに報いる）」の形で功績を称える文脈に頻出。名詞では顧客向けの reward program（ポイント還元制度）としてもビジネスで定番です。",
  "accordingly": "文頭で「したがって（= therefore）」と結果を導く用法と、文末で「それに応じて（adjust accordingly）」と動詞を修飾する用法の2通りがあります。",
  "consequently": "語根 sequ（続く）から「それに続いて」→「結果として（= as a result）」。Part 5 や 6 の空所補充で、前文の原因に対して結果を導く接続副詞として頻繁に問われます。",
  "timely": "-ly で終わるものの副詞ではなく「形容詞」。「in a timely manner（迅速に・適切なタイミングで）」のコロケーションは Part 5 の頻出パターンです。",
  "fame": "語根 fa（話す）に由来し人々の評判から「名声」に。gain fame（名声を得る）の形で使われ、形容詞 famous や派生語 infamous（悪名高い）と合わせて覚えると効果的です。",
  "evaluate": "e-(外へ)+value(価値)+-ateで「価値を見極める」。TOEICでは evaluate performance（業績を評価する）や名詞 evaluation（人事評価）で頻出。",
  "enthusiastic": "en-(中に)+theos(神)が語源で「神が宿るほどの熱意」。TOEICでは be enthusiastic about ...（〜に熱心だ）や enthusiastic support で頻出。",
  "questionnaire": "question(質問)+-naire(〜のもの)で「質問表」。TOEICでは fill out [complete] a questionnaire（アンケートに記入する）の形で頻出。",
  "situated": "site(場所)と同語源で「置かれた」。TOEICでは conveniently situated（便利な場所にある）や be situated near ... の形で、写真描写や不動産の案内で頻出。",
  "payroll": "pay(給料)+roll(名簿)で「給与台帳」。TOEICでは on the payroll（在籍して・雇用されて）や payroll department（給与計算課）の形で頻出。",
  "luncheon": "lunchの改まった表現。TOEICでは awards luncheon（授賞昼食会）や host a luncheon（昼食会を催す）のように、社内イベントや招待状（Part 7）で頻出。",
  "workplace": "work(仕事)+place(場所)の合体語。TOEICでは workplace safety（職場の安全規程）や workplace diversity（職場の多様性）などの複合名詞で頻出。",
  "caution": "ラテン語の「用心」が語源。名詞で exercise caution（注意を払う）や、動詞で caution someone against doing（〜しないよう警告する）の形で出ます。",
  "decline": "de-(下へ)+cline(傾く)で「下へ傾く」。TOEICでは「減少する（a sharp decline）」と「丁重に断る（decline an offer）」の両方の意味で頻出。",
  "outstanding": "out-(外に)+stand(立つ)で「突き出た」。TOEICでは「傑出した（outstanding performance）」だけでなく、「未払いの（outstanding balance）」が最頻出。",
  "résumé": "フランス語の「要約されたもの」が語源。TOEICでは求人・採用問題の最頻出語で、submit [attach] a résumé（履歴書を提出・添付する）の形で登場します。",
  "understaffed": "under-(不足)+staff(職員)+-edで「職員が足りない」。TOEICでは業務遅延や追加採用の理由として、We are understaffed. の形で頻出。short-handed も同義。",
  "engage": "en-(中に)+gage(誓約)で「約束に引き入れる」。TOEICでは engage in research（研究に従事する）や engage with clients（顧客と関わる）の前置詞使いが頻出。",
  "consistent": "con-(共に)+sist(立つ)で「崩れず一貫している」。TOEICでは be consistent with ...（〜と一致している）や、副詞 consistently（常に）の形で頻出。",
  "blueprint": "青色に印刷した建築図面（青写真）が由来。TOEICでは建設・改修プロジェクトの「設計図（blueprints for the facility）」や事業の「詳細計画」として頻出。",
  "workload": "work(仕事)+load(荷物・負荷)で「課せられた業務量」。TOEICでは reduce the workload（仕事量を減らす）や heavy workload（過重な仕事）の形で頻出。",
  "aisle": "sを発音せず「アイル」と読む。TOEICでは交通機関の予約で aisle seat（通路側の席、window seatの対語）や、スーパーの棚の間の通路（aisle 4）として頻出。",
  "coverage": "cover(覆う・保護する)+-ageで「カバーする範囲」。TOEICでは insurance coverage（保険の補償範囲）と media coverage（報道・取材）の2大用法で頻出。",
  "cabinet": "cabin(小部屋)+-et(縮小辞)で「小さな部屋→整理棚」。TOEICでは Part 1 の写真描写で filing cabinet（書類キャビネット）や medicine cabinet として頻出。",
  "initiative": "init-(始まる・入る)が語源。TOEICでは take the initiative（自発的に動く・主導権を取る）や new initiative（新規事業の取り組み・構想）の形で頻出。",
  "transaction": "trans-(越えて)+act(行う)+-ionで「やり取りの成立」。TOEICでは financial transaction（金融取引）や online transaction（ネット決済）の形で頻出。",
  "acknowledge": "ac-(〜へ)+knowledge(認識)で「受領や価値を認める」。TOEICのメールで acknowledge receipt of the order（注文の受領を知らせる）という定型句で頻出。",
  "estate": "state(地位・状態)と同語源で本来は「所有地・資産」。TOEICでは real estate（不動産）や real estate agency（不動産会社）の複合名詞として圧倒的に頻出。",
  "defect": "de-(離れて)+fect(作る)で「作り損ない」。TOEICでは product defect（製品の欠陥）や、形容詞 defective（欠陥のある商品）として返品・交換メールで頻出。",
  "suburb": "sub-(近く)+urb(都市)で「都市の周辺部」。TOEICでは in the suburbs of ...（〜の郊外に）や形容詞 suburban area（郊外地域）として店舗・住宅地の文脈で頻出。",
  "tenant": "ten-(保つ・握る)が語源で「部屋を借りて保持する人」。TOEICでは commercial tenant（テナント企業）や building tenant（入居者）の形で、ビル管理通知で頻出。",
  "competitive": "com-(共に)+pet(求める)で「競い合える」。TOEICでは competitive prices [rates]（他に負けない競争力のある価格・割安な価格）のコロケーションが最頻出。",
  "approximately": "ad-(〜へ)+proxim-(近い)+-lyで「ほぼ近いところに」。TOEICでは数字の直前に置いて approximately 20% や approximately two weeks の形で頻出。",
  "withdraw": "with-(後ろへ)+draw(引く)で「手元に引き戻す」。TOEICでは「預金を引き出す（withdraw money: 反意語deposit）」と「提案・商品を撤退・回収する」の両義で頻出。",
  "overtime": "over(超えて)+time(規定時間)。TOEICでは work overtime（残業する）の動詞連語や、overtime pay（残業手当）などの給与・労務管理の文脈で頻出です。",
  "illustrate": "il-(強調)+lustr(光を当てる)で「光を当てて明確にする」が原義。TOEICでは「挿絵を描く」だけでなく、図表や具体例で「説明する・例証する」文脈で使われる。",
  "observe": "ob-(〜に向かって)+serve(保つ・見守る)が語源。TOEICでは実験を「観察する」だけでなく、規則や方針を「遵守する(observe regulations)」の意味でも頻出。",
  "assessment": "動詞 assess（査定する）に名詞語尾 -ment がついた語。TOEICでは conduct an assessment（査定を行う）や performance assessment（業績評価）の形でよく使われる。",
  "patent": "「開かれたもの（公開状）」が原義。TOEICの製品開発や技術の話題で、apply for a patent（特許を出願する）や patent application（特許出願）の形で頻出。",
  "farewell": "fare（進む・行く）+ well（よく）で「よい旅を」と見送った言葉が語源。TOEICでは hold a farewell party（送別会を開く）など社内イベントの文脈で定番。",
  "packet": "pack（包む）+ 小さいものを表す -et が語源。小包のほか、TOEICでは information packet や welcome packet のように「一式の資料・配付資料」の意味でよく登場する。",
  "quantity": "「どれほどの量か」を問うラテン語が語源。TOEICでは注文や在庫管理で in large quantities（大量に）や quantity discount（大口割引）の形で頻出。",
  "invest": "in-(中に)+vest(衣服・包む)が原義。TOEICでは invest in new technology（新技術に投資する）のように前置詞 in を伴う自動詞の使い方が頻出。",
  "consist": "con-(共に)+sist(立つ)が語源。consist of ...（〜から成る）の形で使われ、受動態にできない自動詞である点がTOEICの文法問題で問われやすい。",
  "exceed": "ex-(外へ・越えて)+ceed(行く)で「限界を越えて進む」が原義。exceed expectations（期待を超える）や exceed the budget（予算を超える）など他動詞として頻出。",
  "rarely": "rare（まれな）に副詞語尾 -ly がついた語。not を使わずに否定の意味を表す「準否定語」で、文頭に置かれると Rarely do we ... のように倒置が起こる文法問題に注意。",
  "exclusively": "ex-(外へ)+clud(閉じる)で「他を締め出して」が原義。exclusively for members（会員限定で）や available exclusively online（オンライン限定）などの形で頻出。",
  "site": "「置かれた場所」が原義。TOEICでは construction site（建設現場）などの物理的な作業場所を指すほか、on-site inspection（現地視察）のような形でも頻出。",
  "pursue": "pur-(前へ)+sue(追う)で「前を追いかける」が原義。pursue a career（キャリアを追求する）や pursue new opportunities（新たな機会を追う）の形で頻出。",
  "shortage": "short（足りない）に状態を表す名詞語尾 -age がついた語。a shortage of staff（人手不足）や a housing shortage（住宅不足）のように of を伴って頻出。",
  "desirable": "desire（強く望む）+ -able（〜できる）。TOEICの求人票で、必須スキル（required）と区別して「歓迎・あれば望ましい条件（desirable）」の項目名としてよく使われる。",
  "possess": "potis(力ある者)+sedere(座る)で「支配者として腰を据える」が原義。TOEICでは土地の所有のほか、possess excellent skills（優れた能力を持つ）のように人材要件で頻出。",
  "despite": "意に介さないことが原義。TOEICのPart 5で【前置詞 despite ＋名詞】と【接続詞 although ＋節】を区別させる問題が超頻出。of を付けない（×despite of）のも重要。",
  "prompt": "pro-(前へ)+empt(取り出す)で「前に用意された」が原義。prompt response / reply（迅速な返答）の形でビジネスメールの返信やお礼の文脈に欠かせない重要語。",
  "urgent": "動詞 urge（強く促す）と同語源。an urgent matter（緊急の案件）や require urgent attention（早急な対応を要する）など、至急対応を求める社内連絡やメールで頻出。",
  "thorough": "前置詞 through（通り抜けて）と同語源で「端から端まで通り抜ける」が原義。thorough inspection（徹底的な検査）や thorough review（綿密な見直し）の形で頻出。",
  "multiple": "multi-(多くの)+ple(重なる)で「何重にもなった」が原義。TOEICでは複数拠点を持つ企業の話題で multiple locations（複数の拠点・支店）などの形でよく登場する。",
  "accessible": "access（接近）+ -ible（可能）。easily accessible by train（電車で簡単に行ける）という立地・アクセスの文脈や、accessible to all staff（全社員が利用可能）の形で頻出。",
  "numerous": "ラテン語 numerus（数）+ -ous（〜に満ちた）が語源。可算名詞の複数形を直後に取り、numerous awards（数多くの賞）や numerous complaints（多数の苦情）の形で頻出。",
  "overlook": "over-(上から)+look(見る)。部屋が海を「見渡す(overlook the ocean)」という景観の文脈と、書類の誤りを「見落とす(overlook an error)」というミスの文脈の両方で頻出。",
  "fold": "Part 1の写真問題で頻出の動作語。fold one's arms（腕を組んでいる）のほか、会場設営の文脈で folding chairs（折りたたみ椅子）のような形容詞的用法もよく使われる。",
  "contribute": "con-(共に)+tribute(与える)で「共に持ち寄る」が原義。contribute to success（成功に貢献する）のように前置詞 to を伴う自動詞の使い方がTOEICの最頻出パターン。",
  "substitute": "sub-(代わりに)+stitute(置く)で「代わりに置く」が原義。substitute A for B（Bの代わりにAを使う）という前置詞 for を取る語法がTOEICの文法問題で問われやすい。",
  "paycheck": "pay（給与）+ check（小切手）で、給与小切手や給料そのものを指す。TOEICでは direct deposit of paychecks（給与の口座自動振込）など人事・経理の連絡文で頻出。",
  "expire": "ex-(外へ)+spire(息を吐く)で「息を吐き切って息絶える」が原義。契約や会員権が切れる自動詞として使われ、expiration date（有効期限）の名詞表現もTOEICの定番。",
  "dedicated": "de-(強意)+dic(告げる)で「神に捧げられた」が原義。be dedicated to -ing/名詞（〜に専念・貢献している）のtoは前置詞である点が文法問題で頻出。",
  "inspect": "in-(中に)+spect(見る)で「中を詳しく見る」。TOEICでは inspect the equipment（設備を点検する）や名詞 inspection（検査）の品詞問題が頻出。",
  "securely": "se-(離れて)+cure(心配)で「心配のない状態に」。securely fasten（しっかり締める）や be securely locked（施錠されている）など受動態を挟む形で頻出。",
  "prohibit": "pro-(前に)+hibit(保つ)で「前に遮って禁止する」。TOEICでは strictly prohibited（固く禁止されている）や prohibit A from -ing の形で頻出。",
  "transform": "trans-(越えて)+form(形)で「形を一変させる」。TOEICでは結果の into を伴い transform A into B（AをBに変える）の形で頻出。",
  "consent": "con-(共に)+sent(感じる)で「思いを一つにする」。TOEICでは不可算名詞として without prior consent（事前の承諾なしに）の表現が頻出。",
  "remarkable": "re-(強意)+mark(注目する)+-ableで「注目に値する」。TOEICでは業績報告で a remarkable achievement（目覚ましい業績）の形で頻出。",
  "trail": "「引きずった跡」が原義で「踏み固められた小道」。TOEICでは公園や観光案内で walking trail（遊歩道）や hiking trail の形でよく出る。",
  "subscription": "sub-(下に)+script(書く)で契約書の下に署名することが原義。TOEICでは renew a subscription（定期購読を更新する）や前置詞 to との連結が頻出。",
  "qualified": "quali-(性質)+fy(化する)から生じた「適格な」。TOEICでは qualified candidates（適任者）や be qualified for ...（〜の資格がある）で頻出。",
  "modify": "mod(基準)+-fy(する)で「整えて手直しする」。TOEICでは modify the schedule [policy]（予定・方針を変更する）や名詞 modification が頻出。",
  "assume": "as-(〜へ)+sume(取る)で「引き受ける」。TOEICでは「思い込む」だけでなく、人事異動で assume responsibility（責任を引き受ける）の語義が頻出。",
  "utility": "util(役に立つ)が語源。TOEICでは複数形 utilities で電気・ガス・水道を指し、utility bill（光熱費請求書）や utility company として頻出。",
  "contrary": "contra-(反対に)が語源。TOEICでは be contrary to ...（〜に反している）や、文頭で用いる Contrary to expectations（予想に反して）が頻出。",
  "authorize": "author(権威)+-izeで「正当な権限を与える」。TOEICでは authorized personnel only（関係者以外立入禁止）など分詞形容詞の形で頻出。",
  "resign": "re-(解除)+sign(署名)で「権利を手放す」。TOEICでは人事ニュースで resign from one's position（辞任する）や resign as CEO の形で頻出。",
  "transition": "trans-(越えて)+it(行く)で「移り変わること」。TOEICでは新体制への移行で smooth transition（円滑な移行）や transition period が頻出。",
  "distinguished": "di-(離れて)+stingu(印をつける)で「際立った」。式典スピーチの a distinguished career（輝かしい経歴）や distinguished guest で頻出。",
  "conclude": "con-(完全に)+clude(閉じる)で「締めくくる」。TOEICでは会議を終える用法のほか、conclude a contract（契約を締結する）の形で頻出。",
  "vacant": "vac(空っぽ)+-antで「空いている」。TOEICでは vacant room（空室）のほか、人事の a vacant position（空席ポスト）や名詞 vacancy が頻出。",
  "appliance": "apply(あてる)+-anceで「特定の用途に使う器具」。TOEICでは household appliances（家庭用電化製品）や kitchen appliances として頻出。",
  "vice": "ラテン語の「代理」に由来する。TOEICでは組織の役職名で vice president（副社長）や vice chair（副委員長）のように、名詞の直前について「副〜」を表す。",
  "convention": "con-(共に)+vent(来る)で「集会」。TOEICでは annual convention（年次大会）や convention center（国際会議場）など、業界の大規模な集まりを指す。",
  "comparable": "com-(共に)+par(等しい)+-ableで「同等の」。be comparable to ...（〜に匹敵する）の語法や at a comparable price（同等の価格で）が頻出。",
  "panel": "陪審員名簿の「小枠」から「選抜された一団」。TOEICでは a panel of experts（専門家グループ）や panel discussion（公開討論）の形で頻出。",
  "diverse": "di-(離れて)+verse(向く)で「様々な方向を向いた」。a diverse range of ...（多様な〜）や diverse backgrounds（多様な経歴）の形で頻出。",
  "revenue": "re-(戻って)+venue(来る)で「入ってくるお金」。TOEICでは annual revenue（年間総収入）の形で頻出で、経費を引いた純利益（profit）との混同に注意。",
  "prescription": "pre-(前もって)+script(書く)で「事前の指示書」。TOEICでは薬局の場面で fill a prescription（処方箋の薬を調合・受け取る）という動詞との連結が頻出。",
  "dispose": "dis-(離れて)+pose(置く)で「片付ける」。TOEICでは自動詞として前置詞 of を伴い、dispose of documents（書類を処分する）のように語法問題で狙われる。",
  "workforce": "work(仕事)+force(力)で「組織の全労働力」。a skilled workforce（熟練労働力）や expand the workforce（人員増強）の文脈で頻出。",
  "expose": "ex-(外に)+pose(置く)で「外にさらけ出す」。TOEICでは be exposed to ...（〜にさらされる）の受動態と前置詞 to の連結や、名詞 exposure が頻出。",
  "outlook": "out(外を)+look(見る)で「将来の見通し」。TOEICでは economic outlook（景気見通し）や positive outlook のほか、前置詞 for を伴う表現が頻出。",
  "investigate": "in-(中に)+vestigium(足跡)で「足跡をたどる」。他動詞で investigate the cause（原因を調査する）の形で使われ、句動詞 look into への言い換えも頻出。",
  "suspend": "sus-(下に)+pend(ぶら下げる)で「一時停止する」。suspend operations（操業停止）や suspend service（運行休止）のように、一時的な停止を表す文脈で頻出。",
  "entitle": "en-(〜にする)+title(資格)で「権利を与える」。受動態 be entitled to ...（〜の資格がある）の形で出やすく、to の後ろには名詞や動詞の原形が続く。",
  "circulation": "circul(円)+-ationで「巡ること」。出版では新聞や雑誌の「発行部数」（large circulation）を指し、図書館の circulation desk（貸出カウンター）も頻出。",
  "crucial": "cruc(十字路)から「運命を分けるほど重大な」。play a crucial role in ...（〜で極めて重要な役割を果たす）や crucial factor（決定的要因）の形で頻出。",
  "biography": "bio-(生命)+graphy(書かれたもの)で「伝記」。autobiography（自伝）との区別が重要で、案内状の登壇者略歴（bio）や著者紹介の文脈でよく見られる。",
  "token": "古英語の「印」が語源。手紙やメールで as a token of our appreciation（感謝のしるしとして）という定型表現でお礼状や記念品を添える場面に頻出。",
  "adapt": "ad-(〜へ)+apt(適合した)で「合わせる」。adapt to the changes（変化に適応する）のように前置詞 to を取り、綴りが似た adopt（採用する）との混同に注意。",
  "diligent": "dis-(離れて)+leg(選ぶ)から「念入りな」。推薦状や人事評価で diligent worker（勤勉な働き手）や diligent efforts（熱心な努力）のように人物評で頻出。",
  "circumstance": "circum-(周囲に)+stance(立つ)で「周囲の状況」。通常複数形で under the circumstances（現状では）や、否定倒置を起こす under no circumstances が頻出。",
  "measure": "「寸法を測る」だけでなく名詞「対策」を表す。take measures to do（〜する対策を講じる）や safety measures（安全対策）のように、問題予防の文脈で頻出。",
  "relief": "re-(再び)+lev(軽くする)で「重荷が取れること」。精神的な安心のほか、時事記事で disaster relief（災害救援）や relief efforts（救済活動）の形でも頻出。",
  "commitment": "com-(共に)+mit(委ねる)で「深く関わること」。demonstrate a commitment to ...（〜への熱意・責任を示す）のように、前置詞 to（後ろは名詞・動名詞）と結びつく。",
  "venue": "ラテン語 venire（来る）に由来し「人が集まる場所」。イベント案内の concert venue（コンサート会場）や conference venue（会議場）のように、開催地を指す語として頻出。",
  "attribute": "at-(〜へ)+tribute(割り当てる)で「〜に帰する」。attribute A to B（Aの原因をBに帰する）や受動態 be attributed to ...（〜に起因する）の形で頻出。",
  "conservation": "con-(完全に)+serv(保つ)+-ationで「大切に守ること」。energy conservation（省エネ）の複合名詞で頻出で、綴りが似た conversation（会話）との混同に注意。",
  "implement": "im-(中に)+ple(満たす)で「実行する」。implement a plan [policy]（計画・方針を実行する）のように、経営施策を実行に移す文脈で頻出する他動詞。",
  "undergo": "under(下を)+go(通る)で変化の下をくぐるイメージ。undergo renovations（改修工事を受ける）や undergo inspections（検査を受ける）の形で改装や点検の文脈に頻出。",
  "faculty": "ラテン語の「能力」から転じて大学で教育を行う「教員陣」を指す。faculty members（教員団）や faculty and staff（教職員）のように、人を指す集合名詞として頻出。",
  "dairy": "中英語の「乳搾り場」が語源。dairy products（乳製品）の表現で頻出。綴りと発音が紛らわしい diary（日記）との混同に注意で、食品表示やメニュー案内によく出る。",
  "moderate": "moder(基準)+-ateで「度を越さない」。moderate growth（緩やかな成長）や moderate prices（手頃な価格）のほか、パネル討論の司会者 moderator（モデレーター）も関連語。",
  "acquire": "ac-(〜へ)+quire(求める)で「努力して得る」。M&A ニュースで acquire a company（企業を買収する）の形で出やすく、名詞 acquisition（買収、獲得）も頻出の派生語。",
  "premises": "pre-(前に)+mise(置く)から「建物を含む敷地」。常に複数形で on the premises（敷地内で）や vacate the premises（退去する）の形で施設案内や規則に頻出。",
  "preliminary": "pre-(前に)+limin(敷居)+-aryで「敷居をまたぐ前の」。preliminary results（暫定結果）や preliminary report（中間報告）のように、確定前の準備段階を表す形容詞。",
  "appetizer": "appetite(食欲)をそそるもの(-er)から「前菜」。英英語の starter と同義で、メニュー表や会食案内で main course [entree]（主菜）や dessert と並んで頻出する。",
  "minimize": "mini(最小)+-ize(化する)で「最小限にする」。工事案内での minimize disruption（混乱を最小限に抑える）や minimize costs（費用を抑える）の文脈で頻出。",
  "layout": "lay(置く)+out(広げて)から「配置・見取り図」。オフィスの改装通知で office layout（オフィスの間取り配置）や store layout（売り場配置）のように配置変更の文脈で頻出。",
  "laptop": "lap(膝)+top(上)で「膝の上で使える小型PC」。デスクトップ型（desktop）と対比され、社内規則でノートPCの持ち出し制限（laptop computer）の文脈などで頻出。",
  "copyright": "copy（複製する）+ right（権利）から成り、「著作権」を表す。copyright infringement（著作権侵害）や hold a copyright（著作権を保持する）のコロケーションが頻出。",
  "applicable": "apply（適用する）+-able（できる）から成る。「be applicable to 〜（〜に適用される）」の前置詞 to との組み合わせや、書類での if applicable（該当する場合）が頻出。",
  "librarian": "library（図書館）+-an（人）で「司書・図書館員」。Part 3・7の地域施設や大学の文脈で登場し、ask a librarian for assistance のような形でよく使われる。",
  "amenity": "心地よさを表す語根に由来し、快適な生活設備を指す。通常は複数形 amenities で用いられ、hotel amenities や modern amenities の形で宿泊施設や物件の案内に頻出。",
  "ongoing": "on（前へ）+going（進んでいる）から「進行中の、継続している」。ongoing discussion や ongoing efforts（継続的な取り組み）のように名詞の前で修飾する用法が頻出。",
  "badge": "オフィスや見本市の受付文脈で頻出の名詞。wear a badge（バッジを着用する）や visitor badge（来訪者バッジ）、ID badge（身分証）の組み合わせでよく出題される。",
  "spokesperson": "spoke（話す）+person（人）で組織を代表して発言する人。a spokesperson for the company（同社の広報担当者）のように前置詞 for を伴う表現がプレスリリースで頻出。",
  "pharmacy": "ギリシャ語の「薬」に由来する調剤薬局。日常会話のリスニングなどで pick up a prescription at a pharmacy（薬局で処方薬を受け取る）という文脈でよく登場する。",
  "ratio": "「a ratio of A to B」で「AとBの比率」を表し、前置詞 to を伴う点が語法上のポイント。Part 7の図表・調査報告書でデータの割合を説明する文脈によく登場する。",
  "thrilled": "「ぞくぞくするほど大喜びの」を表す感情形容詞。人を主語にして「be thrilled to do（〜できてとても嬉しい）」や「be thrilled with 〜」の形で通知や昇進の祝辞メールに出る。",
  "intersection": "inter-(互いに)+sect(切る)+-ion(こと)で道が交わる「交差点」。「at the intersection of 〜」の形で、リスニングやPart 7の道案内・地図問題で頻出の表現。",
  "cashier": "フランス語の「金庫(caisse)」に由来し、店舗の会計係を指す。リスニングの店舗での会話で「pay the cashier（レジ係に支払う）」や返品窓口の文脈でよく使われる。",
  "coordinate": "co-(共に)+ordinate(配置する)で「複数の要素を調整・調和させる」。coordinate efforts（取り組みを調整する）や coordinate logistics のように業務の進行管理で頻出。",
  "shareholder": "share(株式)+holder(保有者)で「株主」。annual shareholders' meeting（年次株主総会）や shareholder approval（株主の承認）など、経営・財務文書で定番の表現。",
  "nominate": "語根 nomen(名前)に由来し、候補として名を挙げること。「be nominated for an award（賞に推薦される）」のように前置詞 for を伴う受動態が社内表彰などの文脈で頻出。",
  "fragile": "fragment(破片)と同語源で「壊れやすい」。配送・物流の文脈で「Handle with care: Fragile（取扱注意：壊れ物）」や fragile items（壊れやすい品物）として登場する。",
  "invoice": "古フランス語の「送られたもの」に由来する「請求書」。issue an invoice（請求書を発行する）や pay an invoice（請求書を支払う）のコロケーションで会計・発注の文脈に頻出。",
  "last-minute": "最後の1分まで迫った「直前の、土壇場の」を表す複合形容詞。last-minute cancellation（直前キャンセル）や last-minute changes（直前の変更）の形で出張や会議の文脈に頻出。",
  "auditorium": "audi(聴く)+-orium(場所)で「音を聴く場所＝講堂・大ホール」。社内研修や講演会の案内文で、The presentation will be held in the auditorium のように会場として登場する。",
  "terminate": "terminus(限界・終点)に由来し、「契約などを途中で終了・解除する」。terminate a contract（契約を解除する）や terminate employment（解雇する）など法律・契約文脈で頻出。",
  "state-of-the-art": "技術の水準(state)の最前線にあることから「最新鋭の、最先端の」。state-of-the-art technology / facilities（最新鋭の技術／設備）のように設備や製品を修飾する形で頻出。",
  "allocate": "al-(〜へ)+locate(場所を決める)から「予算や時間を割り当てる」。「allocate budget to [for] advertising（広告に予算を配分する）」のように資金や人員の配分文脈で頻出。",
  "outing": "out(外へ)+-ingで「気軽な外出・遠足」。TOEICでは company outing（社員旅行・社内レクリエーション）のコロケーションが定番で、社内親睦イベントの告知メールなどで頻出。",
  "nutrition": "nurture(育てる)と同語源で「栄養」。食品パッケージの「nutrition facts / information（栄養成分表示）」や、社内の健康増進プログラムを扱った案内文でよく見られる。",
  "plumber": "古代の鉛(plumbum)の配管に由来し、bを発音しない(/plʌ́mər/)。オフィスの水漏れ修理を呼ぶ文脈で「call a plumber to fix the leak」のようにリスニングで頻出。",
  "statistics": "state(国家)に由来し、もとは国の情勢データ。学問（統計学）では単数扱いだが、データ（統計数値）の意味では複数扱いになり「Statistics show that 〜」のように動詞が原形を取る。",
  "accommodate": "「accommodate 100 guests（100人を収容する）」と「accommodate customer requests（要望に応じる）」の2つの意味が超頻出。会場案内や顧客対応の文脈で必ず押さえたい動詞。",
  "voucher": "vouch(保証する)+-er(もの)で「価値を保証する引換券」。遅延補償や謝礼の文脈で meal voucher（食事券）や「redeem a voucher for 〜（引換券を〜に引き換える）」の形で頻出。",
  "picturesque": "picture(絵)+-esque(〜風の)で「絵画のように美しい」。picturesque views（絵のように美しい景色）や picturesque town のように、観光ツアーの宣伝や旅行記の文脈で頻出。",
  "aspiring": "a-(〜へ)+spire(息を吹き込む・志す)から「〜を志望している、意欲的な」。aspiring entrepreneurs（起業家志望の人々）のように将来成功を目指す人物を修飾する形で頻出。",
  "wholesale": "whole（丸ごと）＋sale（販売）から「卸売り」。対義語の retail（小売り）との対比で出やすく、wholesale price（卸売価格）などの表現が定番。",
  "exhausted": "ex-（外へ）＋haurire（汲み出す）で「中身を出し切った」状態。人が主語なら「疲れ切った」、予算や資源なら「使い果たされた」の意味で使われる。",
  "duplicate": "du-（2つの）＋plicare（折る）から「2重にする」。duplicate receipt（領収書の控え）など名詞や形容詞のほか、「複製する」という動詞でも頻出。",
  "confidential": "con-（強意）＋fide（信頼）で「信頼して秘密を預ける」。Part 7の社内文書で strictly confidential（社外秘）などの形で非常によく見かける。",
  "coincide": "co-（共に）＋in-（上に）＋cadere（落ちる）から「重なる」。自動詞で coincide with ...（〜と重なる、一致する）の形で日程の重複を表す文脈で頻出。",
  "intensive": "in-（中へ）＋tendere（張る）が語源。intensive training（集中研修）など研修や講座の文脈で頻出。感情や痛みが激しいことを表す intense と区別しよう。",
  "stack": "古ノルド語の「干し草の山」が語源。Part 1の写真描写問題で Boxes are stacked...（箱が積み上げられている）のように受動態で非常によく狙われる。",
  "surplus": "sur-（越えて）＋plus（多い）から「余剰」。budget surplus（財政黒字）や surplus inventory（余剰在庫）で出やすい。対義語の deficit（赤字）も重要。",
  "enroll": "en-（中へ）＋roll（名簿の巻物）から「名簿に入れる」。自動詞で enroll in ...（〜に登録する）の形で使われ、セミナー受講案内などで頻出。名詞は enrollment。",
  "entrepreneur": "フランス語の「引き受ける人」が語源。Part 7の成功談や人物紹介でよく登場する。形容詞形の entrepreneurial（起業家精神の）も併せて押さえたい。",
  "constraint": "con-（強意）＋stringere（締め付ける）が語源。TOEIC では budget constraints（予算の制約）や time constraints（時間の制約）のように複数形で頻出。",
  "predecessor": "pre-（前に）＋decedere（立ち去る）から「前にいた人」。人事異動の文脈で「前任者」として登場し、後任者を表す successor とセットで覚えておきたい。",
  "hypothesis": "hypo-（下に）＋thesis（置くこと）から「土台として仮に置くもの」。市場調査や開発レポートの文脈で test a hypothesis（仮説を検証する）などの形で出やすい。",
  "surpass": "sur-（越えて）＋pass（進む）から「超える」。業績報告で surpass expectations（期待を超える）や surpass sales targets（売上目標を上回る）として頻出。",
  "persuasive": "動詞 persuade（説得する）の形容詞形。persuasive argument（説得力のある主張）や persuasive presentation などの形で提案・会議の文脈でよく使われる。",
  "fertilizer": "fertile（肥沃な）＋-ize（化する）＋-er（もの）から「肥料」。造園（landscaping）や農業、環境対策の話題で chemical fertilizer（化学肥料）などの形で出る。",
  "landmark": "land（土地）＋mark（目印）から「名所・目印となる建造物」。観光案内や都市開発の記事で historic landmark（歴史的名所）などの形で頻出する。",
  "wheelbarrow": "wheel（車輪）＋barrow（運搬車）。Part 1の写真描写問題で、作業員が手押し車を押す場面（A worker is pushing a wheelbarrow.）としてピンポイントで出る。",
  "cuisine": "フランス語の「台所・料理法」由来。単なる food ではなく洗練された料理を指し、local cuisine（郷土料理）などの形で出張や観光案内の文脈で非常によく出る。",
  "enhance": "ラテン語の altus（高い）に由来し「価値や能力を引き上げる」。enhance efficiency（効率を高める）や enhance productivity の形で改善策の文脈に頻出。",
  "heritage": "heir（相続人）と同語源で「受け継がれるもの」。個人の遺産（inheritance）と異なり、cultural heritage（文化遺産）など歴史や伝統を指す文脈で使われる。",
  "misleading": "mis-（誤って）＋lead（導く）から「誤った方向へ導くような」。misleading advertisement（誤解を招く広告・誇大広告）などの形で広告や法務の文脈で出やすい。",
  "compartment": "com-（共に）＋partire（分ける）から「仕切られた区画」。飛行機や鉄道の案内アナウンスで overhead compartment（頭上の荷物入れ）の形で非常によく使われる。",
  "remedy": "re-（再び）＋mederi（癒やす）から「回復させるもの」。病気の治療薬だけでなく、ビジネスの「改善策」の意味も重要で、remedy the situation と動詞でも使える。",
  "scenic": "scene（景色）の形容詞形。旅行ツアーの案内や不動産広告で、scenic view（素晴らしい眺め）や scenic route（景色の良いルート）の形で非常によく使われる。",
  "prospective": "pro-（前方）＋spect（見る）で「先を見通した」。prospective clients（見込み顧客）や prospective employees（採用候補者）で頻出。perspective（視点）と混同注意。",
  "nationwide": "nation（国）＋-wide（全体に広がる）。形容詞・副詞どちらでも使え、expand nationwide（全国展開する）や nationwide campaign などの形でビジネス展開によく出る。",
  "reluctant": "re-（反して）＋luctari（抵抗する）から「気が進まない」。be reluctant to do（〜するのをためらう・嫌がる）のイディオムが重要で、登場人物の心情描写でよく出る。",
  "comprehensive": "com-（完全に）＋prehendere（つかむ）から「すべてを取り込んだ」。comprehensive directory（網羅的な名簿）や comprehensive coverage（包括的補償）の形で Part 5・7に頻出。",
  "array": "古フランス語の「整える」が語源。an array of ...（ずらりと並んだ〜、多彩な〜）の形で品揃えを表す表現として頻出。a wide array of products が定番コロケーション。",
  "periodically": "period（周期）から派生した副詞。「定期的に点検する」のように inspect や review とセットで設備の保守・点検文脈で頻出します。",
  "compensate": "com-(共に)+pensare(重さを量る)で釣り合いを取るのが原義。前置詞 for を伴い compensate for the loss（損失を補償する）の形で頻出です。",
  "tuition": "本来は「指導・保護」を意味し、転じて「授業料」に。福利厚生の文脈で tuition reimbursement（学費補助・返還制度）としてよく登場します。",
  "deduct": "de-(下へ・離れて)+duct(引く)で「差し引く」。給与や請求書の文脈で be deducted from や、形容詞 tax-deductible（税額控除できる）で出題されます。",
  "congested": "con-(共に)+gest(運ぶ・集める)で物が一箇所に密集した状態。交通アナウンスで be congested with traffic（車で混雑している）の形でよく出ます。",
  "withstand": "with-(対抗して)+stand(立つ)で「圧力に逆らって持ちこたえる」。withstand high temperatures（高温に耐える）のように製品の耐久性説明で頻出。",
  "browse": "本来は家畜が若芽をかじる意味から「気ままに見る」に。Part 1 で客が商品を見ている場面や、書類にざっと目を通す動作描写として頻出の動詞です。",
  "diagnosis": "dia-(透かして)+gno-(知る)で「見抜いて判断する」。医療の診断だけでなく、機器のトラブルシューティングや「診断テスト（diagnostic test）」の文脈でも出ます。",
  "commend": "com-(強意)+mend(委ねる)で高く評価する意味。表彰スピーチで commend 人 for 功績（人の功績を称える）の形で頻出。recommend（勧める）と混同注意。",
  "unveil": "un-(外す)+veil(ベール・覆い)で、覆いを取って初公開すること。プレスリリース等で unveil a new model（新モデルを発表する）の形でよく使われます。",
  "persistence": "per-(最後まで)+sist(立つ)で、最後まで諦めずに立ち続けること。形容詞 persistent（粘り強い）も頻出で、困難を乗り越えて成功した人物紹介などで出ます。",
  "durable": "dur-(長続きする)+able(できる)で「長持ちする」。endure（耐える）と同語源です。製品紹介で durable materials（耐久性の高い素材）として頻出。",
  "intermission": "inter-(間に)+mit/miss(送る)で幕間に人を外へ出すこと。「公演や劇の合間の休憩時間」を指し、アナウンスやイベント案内で during the intermission として出ます。",
  "misplace": "mis-(誤って)+place(置く)で「どこに置いたか分からなくなる」。Part 2 や 3 で「書類や鍵が見当たらない」というトラブルのきっかけとして頻出です。",
  "lapse": "滑り落ちる原義から、時間が経過して権利が切れること。契約・保険の失効や、a lapse of membership（会員資格の失効）などの更新通知でよく使われます。",
  "vital": "vit-(生命)+alで「生きるのに不可欠な」。play a vital role in ~（〜で極めて重要な役割を果たす）や It is vital that節 の形でよく問われます。",
  "dietary": "diet（食事）の形容詞形。パーティーや会議の参加登録で dietary restrictions（食事制限・アレルギー対応）や dietary requirements として頻出です。",
  "bid": "価格や条件を提示することから「入札」。Part 7 の契約・調達案件で submit a bid（入札書を提出する）や the winning bid（落札）の形で登場します。",
  "detergent": "de-(離して)+tergere(拭き取る)で汚れを拭い落とすもの。Part 7 の発注票や納品書で laundry detergent（洗濯洗剤）など清掃備品として登場します。",
  "informative": "inform（知らせる）から「知識や情報が豊富でためになる」。研修やセミナー後のアンケートで an informative session（有益な講義）のように高評価の定番語です。",
  "activate": "act（行動する）を起動させること。銀行カードの利用開始や、Webサイト・会員登録メールで「アカウントを有効化する（activate your account）」として頻出。",
  "authentic": "ギリシャ語の「本物の・正真正銘の」が語源。レストランの宣伝で authentic Italian cuisine（本格イタリア料理）のように本場の味を強調する際によく出ます。",
  "reunion": "re-(再び)+union(団結・結合)で「再会」。ホテルの宴会場予約や案内メールで、family reunion（親族の集い）や class reunion（同窓会）としてよく出ます。",
  "adjacent": "ad-(〜へ)+jacere(横たわる)で「隣に並んでいる」。前置詞 to を伴う adjacent to ~（〜に隣接した）の形が狙われ、建物や部屋の位置関係の説明で頻出です。",
  "solicit": "強く働きかけて促す意味。社内メールやアンケートで solicit feedback（フィードバックを募る）や solicit opinions（意見を求める）の形で頻出です。",
  "subsidiary": "sub-(下に)+sid/sed(座る)で「下に控えて支えるもの」。parent company（親会社）の対義語として a subsidiary of ~（〜の子会社）の形で会社概要によく出ます。",
  "refrain": "re-(後ろへ)+frenum(手綱)で「手綱を引いて止める」。館内アナウンスや注意書きで Please refrain from using ~（〜の使用はお控えください）の定型句で頻出。",
  "malfunction": "mal-(悪い)+function(機能)で「機器の動作不良」。Part 3 や 7 の苦情・問い合わせで equipment malfunction（機器の故障）としてよく登場します。",
  "novice": "nov-(新しい)から「初心者・新米」。novel（斬新な）と同語源です。講座や研修の募集で suitable for novices（初心者向け）のように beginner の類語として出ます。",
  "outdated": "out-(越えて)+date(日付)で「有効期限や時代を過ぎた」。システム刷新の提案で outdated software（時代遅れのソフト）のように設備や方針の更新理由として頻出。",
  "retrieve": "re-(再び)+trouver(見つける)が語源で「取り戻す」。IT文脈で retrieve data や手荷物受取所の baggage retrieval など名詞形 retrieval も頻出。",
  "advocate": "ad-(〜へ)+voc(声)から「支持する」。名詞 advocate for 〜（〜の支持者）のほか、動詞では advocate changing policies のように動名詞を直接取りやすい。",
  "tentative": "tent-(試す)から「試験的な」→「仮の」。ビジネスの日程調整で tentative schedule（仮のスケジュール）や tentative agreement（暫定合意）の組み合わせで頻出。",
  "proofread": "proof(校正刷り)+read(読む)で「誤りを確認する」。Part 7等で proofread a manuscript（原稿を校正する）や proofreader（校正者）の形で出やすい。",
  "commemorate": "com-(共に)+memor(記憶する)で「記憶にとどめる」→「記念する」。社内行事や式典で commemorate the anniversary（周年を記念する）のコロケーションが定番。",
  "inclement": "in-(否定)+clement(穏やかな)で「穏やかでない」。TOEICではほぼ天候に用いられ、Part 4のアナウンス等で due to inclement weather（悪天候のため）の定型句で頻出。",
  "designated": "de-(強意)+sign(印)で「印をつけられた」→「指定の」。designated parking area（指定駐車場）のように名詞を修飾する分詞として案内標識や規則で頻出。",
  "apprentice": "ap-(〜へ)+prehend(つかむ)と同系統で「技術を身につける人」→「見習い」。研修や人事の文脈で apprentice program（研修生プログラム）などの形で使われる。",
  "delegate": "de-(離れて)+leg(送る)で「派遣された人」。名詞では「会議の代表者（可算名詞）」、動詞では delegate authority to 〜（権限を委任する）の形で使われる。",
  "respectively": "respect(点・観点)から「各々の点について」。文末で A and B are X and Y, respectively（AとBは各々XとY）と順序の対応を示す。respectful（敬意を表す）と混同注意。",
  "enforce": "en-(〜にする)+force(力)で「力を持たせる」→「施行する」。enforce regulations（規則を施行する）のように法規や安全基準を遵守させる文脈で使われる。",
  "integral": "integer(完全体)と同語源で「全体を構成するのに欠かせない」。be integral to 〜（〜に不可欠だ）の前置詞 to や、play an integral role in 〜 の形で頻出。",
  "interact": "inter-(相互に)+act(動く)で「互いに作用する」。自動詞なので前置詞 with を伴い、interact with customers（顧客と交流・対応する）の形で頻出。",
  "superb": "super-(超えて)が語源で「並外れた」→「素晴らしい」。レビューや推薦状で superb service（見事な対応）や superb quality（極上の品質）と称賛する文脈で頻出。",
  "whereas": "where+as から「〜であるのに対し」。対比を表す接続詞で while に近く、社内報告書などで業績の対比（Sales rose, whereas costs fell）を表すのに使われる。",
  "appraisal": "appraise(評価する)+al(名詞語尾)で「査定・評価」。人事の performance appraisal（業績評価・人事考課）や不動産の property appraisal（資産査定）の形で頻出。",
  "prosperous": "pro-(前へ)+sper(希望)で「望み通り進む」→「繁栄した」。a prosperous business（繁盛している会社）や prosperous economy（繁栄する経済）の形で頻出。",
  "proficiency": "pro-(前へ)+fic(行う)で「前進して習熟したこと」。求人要項の requirements で proficiency in English（英語力）など、言語やソフトの習熟度を示す名詞として頻出。",
  "infer": "in-(中に)+fer(運ぶ)で「事実から結論を導く」。Part 7の設問 What can be inferred about 〜?（推測できることは何か）で定番。書き手の imply（示唆する）と対比。",
  "quota": "ラテン語の「どれだけの割合」が語源で「ノルマ」。営業現場の meet one's sales quota（ノルマを達成する）や exceed the quota（ノルマ超過）など動詞との組み合わせが頻出。",
  "oversee": "over-(上から)+see(見る)で「全体を見下ろして監督する」。oversee the project（事業を統括する）のように役職の職責説明で頻出。形が似た overlook（見落とす）との混同に注意。",
  "correspondence": "co-(共に)+respond(返答する)で「応答のやり取り」→「通信・書簡」。メールや手紙を指す不可算名詞で、business correspondence（商業通信文）などの表現で頻出。",
  "acclaimed": "ad-(〜へ)+claim(叫ぶ)で「大声で称賛する」の過去分詞。critically acclaimed novel（批評家に絶賛された小説）や widely acclaimed のように副詞と共に使われる。",
  "hands-on": "hands(手)+on(接触)で「実際に手で触れる」→「実践的な」。セミナーや研修の告知で hands-on experience（実地経験）や hands-on training（体験型研修）として頻出。",
  "conform": "con-(共に)+form(形)で「形を合わせる」→「従う」。自動詞で前置詞 to/with を取り、conform to standards（基準に適合する）の形で頻出。confirm（確認する）との混同に注意。",
  "emerging": "e-(外へ)+merge(現れる)から「水面に出てくる」。emerging markets（新興市場）や emerging technologies（新興技術）のように成長分野を修飾する。",
  "complement": "complete(完成させる)と同語源で「補い完全にする」。complement each other（補完し合う）で使われる。1字違いの compliment（褒め言葉・無料の品）との混同注意。",
  "incur": "in-(中に)+cur(走る)で「自ら飛び込んで被る」。incur additional expenses（追加費用が生じる）や incur a late fee（延滞料がかかる）のように費用や罰則と結びつく。",
  "subsequent": "sub-(次に)+sequ(続く)で「次に続く」→「その後の」。subsequent years（その後の数年）と名詞を修飾するほか、副詞 subsequently（その後）も時間の推移を表すのに頻出。",
  "credential": "cred(信じる)から「信用を証明するもの」→「資格・経歴」。求人や経歴紹介で impressive credentials（素晴らしい実績）と複数形でよく使われ、ログイン資格情報を指すこともある。",
  "showcase": "show(見せる)＋case(箱)から、自慢の品を並べる「披露する」に発展。TOEICでは新製品発表や展示会で showcase new features や showcase talents のように使われます。",
  "sustainable": "sustain(維持する)＋-able(できる)から「維持可能な」。環境問題だけでなく、sustainable growth（持続的な成長）や sustainable business のように企業経営の文脈でも頻出です。",
  "mural": "ラテン語で「壁」を意味する murus が語源。TOEICでは地域の美化プロジェクトやオフィスの改装案内の文脈で、paint a mural（壁画を描く）のように使われます。",
  "unprecedented": "un-(否定)＋precedent(前例)＋-ed で「先例のない」。業績報告やニュースの文脈で、unprecedented success（空前の成功）や unprecedented demand の形でよく登場します。",
  "detour": "de-(離れて)＋tour(進路・回ること)で「本道から外れる道」。交通情報や道路工事の通知で、take a detour（回り道をする）という動詞 take との組み合わせが定番です。",
  "affiliated": "ラテン語の「養子にする（子にする）」が語源。TOEICでは be affiliated with ...（〜と提携・提携関係にある）のように前置詞 with を伴う受動態表現が頻出です。",
  "reimburse": "re-(再び)＋im-(中に)＋burse(財布)で「お金を財布に戻す」。出張経費の精算で reimburse A for B（AにBの費用を払い戻す）という語法や名詞 reimbursement が頻出です。",
  "keynote": "楽曲全体の調子を決める「主音」が語源で、基本方針を指します。学会や展示会のスケジュール表で、keynote speaker（基調講演者）や keynote address（基調講演）として頻出です。",
  "liable": "ラテン語の「縛る」が語源で、法律等に縛られている状態。TOEICでは利用規約の文脈で be liable for damage（損害賠償責任を負う）のように前置詞 for を伴う形が重要です。",
  "mandatory": "mand-(命じる)から「命令された＝義務的な」。社内通知で mandatory training（必須研修）や attendance is mandatory（出席必須）のように使われます。",
  "plaque": "薄い平板を指すフランス語に由来。TOEICでは永年勤続表彰や退職記念パーティーの文脈で、present a plaque（表彰盾を贈呈する）や a commemorative plaque として出ます。",
  "attire": "「身なりを整える」という古フランス語由来で、不可算名詞です。イベントの案内状や社内規定で business attire（正装）や casual attire（普段着）などのドレスコード指定で頻出です。",
  "impending": "im-(上に)＋pend(ぶら下がる)で、頭上に今にも落ちてきそうな状態から「差し迫った」。impending retirement（目前の退職）や天候悪化の警告などでよく見られます。",
  "waive": "権利や要求を差し控える意。プロモーションや顧客対応のメールで、waive the fee（手数料を免除する）や waive the delivery charge（送料を無料にする）の形で頻出です。",
  "commensurate": "com-(共に)＋mensur(測る・measureと同語源)から「同じ基準で釣り合った」。求人票の給与欄で salary commensurate with experience（経験に見合った給与）として頻出です。",
  "debris": "フランス語の「砕く」に由来し、末尾の s を発音しない点に注意。悪天候後の清掃や工事現場の連絡で clear the debris（残骸・がれきを片付ける）という表現で使われます。",
  "synopsis": "syn-(共に)＋opsis(見ること)で「全体をひと目で見渡すこと」。本・映画のあらすじや会議資料の文脈で使われ、Part 7の同義語問題では summary の言い換えとして狙われます。",
  "recitation": "re-(再び)＋cite(呼ぶ・引用する)から、覚えたものを口に出す「暗唱・朗読」。教育イベントやスピーチ大会の案内で recitation contest（朗読コンテスト）などの名詞句で出ます。",
  "odometer": "ギリシャ語の「道」＋meter(計器)で車の走行距離計。レンタカーの利用案内や中古車販売の文脈で、odometer reading（メーターの数値・積算走行距離）という表現がよく登場します。",
  "broadly": "形容詞 broad(広い)の副詞形。全体を広くとらえて「大筋で・おおむね」を意味します。会議やメールで broadly speaking（大まかに言えば）や broadly agree の形で使われます。",
  "benevolent": "bene(善い)＋vol(望む・意志)で「善意に満ちた」。volunteer と同語源です。寄付や社会貢献活動の文脈で benevolent organization / fund（慈善団体・基金）として使われます。",
  "off-limits": "limit(境界)から off(外れる)で立ち入り禁止の意。社内通知や施設案内で The area is off-limits to unauthorized personnel（関係者以外立ち入り禁止）のように to を伴って出ます。",
  "wobbly": "動詞 wobble(ぐらぐら揺れる)の形容詞形。オフィスの備品トラブルや修理依頼のメールで、a wobbly desk / chair（脚がぐらつく机・椅子）の修繕を頼む文脈で登場します。",
  "superintendent": "super-(上に)＋intend(注意を向ける)＋-ent(人)で「全体を上から見渡す監督者」。TOEICでは工場の現場責任者や、building superintendent（アパートや建物の管理人）の肩書きで見られます。",
  "marble": "ギリシャ語の「輝く石」に由来。TOEICではホテルや新装オフィスの改装案内で、marble floor（大理石の床）や marble countertop（大理石のカウンター天板）のように高級な内装の描写で出ます。",
  "patronage": "patron(常連客・後援者)の名詞形。店舗や劇場の案内状で Thank you for your continued patronage.（変わらぬご愛顧に感謝いたします）というお礼の決まり文句として極めて頻出です。",
  "offshore": "off(離れて)＋shore(岸)で、海岸から離れた場所から転じて「海外の・国外拠点の」。人件費削減や拠点移転の文脈で offshore outsourcing（海外外注）や offshore production として使われます。",
  "bond": "bind(縛る)と同語源で、義務を束ねる契約や証書。金融の「債券」だけでなく、TOEICの不動産契約では security bond や rental bond の形で「敷金・賃貸保証金」の意味でよく出題されます。",
  "validate": "valid(有効な)＋-ate(動詞化)。買い物客への案内で validate a parking ticket / voucher（駐車券・引換券に押印して有効にする）という受付やカスタマーサービスの場面で頻出の動詞です。",
  "immaculately": "im-(否定)＋macula(シミ・汚れ)＋-ly で「一点の汚れもなく」。ホテルや不動産の内覧案内で immaculately maintained（完璧に維持された）や immaculately clean の形で使われます。",
  "congregate": "con-(共に)+greg-(群れ)で「群れとなって集まる」。自動詞として congregate in [at] ... のように場所の前置詞を伴い、ロビーや広場に人が集まる文脈で使われる。",
  "prolific": "proli-(子孫)+fic(生み出す)から「次々と生み出す」が原義。prolific writer（多作な作家）のように、作品やアイデアを数多く発表する人物の修飾で頻出する。",
  "seaworthy": "sea(海)+worthy(適した)の複合語で「航海に耐えうる」。船の修繕や安全検査の報告書で、船が安全に航行できる状態にあることを表す際に見られる。",
  "outskirts": "out-(外の)+skirt(へり・裾)で都市の周縁部を指す。常に複数形で用いられ、on the outskirts of the city（市の郊外に）のように前置詞 on とセットで使われる。",
  "philanthropic": "phil-(愛する)+anthrop-(人間)で「人間愛の→慈善の」。philanthropic foundation（慈善財団）や philanthropic efforts の形で、寄付や社会貢献の話題に登場する。",
  "miscalculation": "mis-(誤った)+calculation(計算)で「見積もりの誤り」。動詞 make を伴って make a miscalculation（見当違いをする）の形で、予算や日程の見通しミスを表す際に使われる。",
  "rejuvenation": "re-(再び)+juven-(若い)+-ationで「再び若返らせること」。urban rejuvenation（都市再生）や rejuvenation project のように、地域経済や施設の活性化計画でよく使われる。",
  "ingenious": "engine（工夫）と同語源で、知恵が凝らされている様子を表す。ingenious design（独創的な設計）や ingenious solution の形で、画期的な製品や解決策の描写に使われる。",
  "sanitizer": "sanit-(衛生的な)+-izer(するもの)で「除菌具」。hand sanitizer（手指消毒液）の表現が代表的で、職場や施設の衛生管理・清掃マニュアルなどの文書で見られる。",
  "perk": "perquisite（臨時収入・役得）の短縮形。求人票の待遇欄で perks and benefits（特典と福利厚生）として頻出し、社員割引やジム利用権などの付加的待遇を指す。",
  "attic": "屋根のすぐ下の空間を指す。住宅の販売・賃貸情報や改修の文脈で、attic storage（屋根裏収納）や convert the attic into ... などの形で登場する。",
  "downtime": "down-(稼働停止)+time(時間)。ITシステムのメンテナンスや工場の設備更新の通知で、minimize downtime（停止時間を最小限に抑える）というコロケーションが頻出。",
  "provision": "pro-(前もって)+vis-(見る)で「前もって見て備えること」。make provision(s) for ...（〜への備えをする）や、契約書における「規定・条項」の意味でも頻出する。",
  "vibrant": "vibrate（振動する）と同語源で「エネルギーに満ち溢れた」。a vibrant city（活気ある街）や a vibrant community のように、地域や職場の賑やかさを描写する際によく使われる。",
  "protocol": "公的な手続きや行動規約を指す。safety protocols（安全基準）や follow protocol（規定の手順に従う）のように、職場の保安マニュアルや危機管理の文脈で登場する。",
  "bluff": "海や川に面した「切り立った崖・絶壁」。TOEICでは観光地や遊歩道（trail）の案内で、overlook the bluff（崖を見下ろす）など景観を描写する名詞として登場する。",
  "query": "question や inquire と同語源の「問い合わせ」。カスタマーサポートの案内で、direct your queries to ...（〜までお問い合わせください）の形で使われることが多い。",
  "paver": "pave（舗装する）+-er(もの)で「舗装用の敷石・ブロック」。patio pavers（中庭の敷石）や concrete pavers のように、庭園造り（landscaping）や改修工事の文脈で見られる。",
  "upmarket": "up-(上に)+market(市場)で「高級市場向けの」。upmarket boutique や go upmarket（高級路線へ移行する）のように、ブランド戦略や店舗のターゲット層を語る際に出る。",
  "scrutiny": "「綿密な調査・吟味」を指す名詞。under close scrutiny（厳しい精査を受けて）の形が頻出で、財務監査や新製品の安全性検査、公的審査の話題でよく用いられる。",
  "briefing": "brief（簡潔な）+-ingで「要点を絞った事前説明会」。attend a briefing（説明会に出席する）や press briefing（記者発表）のように、業務開始前の情報共有の場で頻出。",
  "intimate": "ラテン語の「最も内側の」が原義。日常語の「親しい」だけでなく、TOEICでは intimate knowledge of ...（〜についての深い知識・精通）のコロケーションでよく問われる。",
  "lucrative": "profitable（採算が取れる）のよりフォーマルな類語。lucrative contract（実りの多い契約）や lucrative market のように、大きな利益をもたらすビジネス機会の修飾で頻出。",
  "swap": "「交換する」。職場メールなどで swap shifts with ...（〜と勤務シフトを交代する）や swap A for B の形でよく使われ、exchange より口語的で身近なやり取りに登場する。",
  "proximity": "approximate（おおよその・近い）と同語根で「近さ」。in close proximity to the station（駅に極めて近接して）のように、不動産やホテルの立地の良さを述べる定型表現が頻出。",
  "entrant": "enter（入る・参加する）+-ant(人)で「参加者・参入者」。コンテストの応募者を指すほか、new entrants to the market（市場への新規参入企業）のようにビジネス文脈でも使われる。",
  "untidy": "un-(否定)+tidy(整然とした)で「乱雑な」。共有スペースのマナー啓発メールなどで、Don't leave the room untidy（部屋を散らかしたままにしないこと）のように使われる。",
  "panoramic": "pan-(すべての)+horama(眺め)+-icで「全景を見渡せる」。ホテルの客室広告や展望台の案内で、enjoy a panoramic view of the city（市街の全景を楽しむ）の形でおなじみ。",
  "prodigy": "卓越した才能を持つ「神童・天才」。雑誌の人物紹介などで a child prodigy（神童）や a coding prodigy のように、若くして顕著な成果を上げた人物を形容する名詞として登場する。",
  "cargo": "car（車）と同語源で、船や飛行機で運ぶ「積荷・貨物」。集合名詞として air cargo（航空貨物）や cargo ship（貨物船）のように、物流・貿易関連の配送手配や遅延通知で頻出する。",
  "enact": "en-(〜にする)＋act(法律)で「制定する」。行政や企業のニュースで enact legislation（法案を制定する）や enact a new policy の形で頻出です。",
  "trendy": "trend(流行)に接尾辞 -y が付いた形容詞。店舗紹介や市場調査で trendy restaurant や trendy designs のように、現代風で人気の品や店を指して使われます。",
  "bulb": "元々は「球根」を指し、形状の類似から「電球」の意味に。施設管理の依頼メールで replace a light bulb（電球を交換する）や energy-saving bulb として出ます。",
  "landlord": "land(土地)＋lord(領主)から「家主・地主」。不動産契約の文書では、借り手を指す tenant（入居者・賃借人）の対義語として賃料や契約更新の場面で頻出です。",
  "leisurely": "leisure(余暇)＋-ly で、副詞だけでなく形容詞としても使われます。旅行案内やツアー日程で at a leisurely pace（ゆったりとした歩調で）などの表現が定番です。",
  "conspicuous": "con-(完全に)＋spic(見る)から「はっきりと目に見える→目立つ」。施設案内で in a conspicuous place（目立つ場所に掲示する）などの文脈で使われます。",
  "serial": "series(一連のもの)の形容詞形。TOEICでは機器サポートの文脈で、個体識別番号を指す serial number（製造番号・シリアル番号）という組み合わせが定番です。",
  "janitor": "ローマ神話の扉の神 Janus に由来し、門番から「建物の清掃員・管理人」に。オフィスの保守契約で janitorial services（清掃サービス）の形でも頻出です。",
  "stall": "古英語の「立つ場所」から、仕切られた売り場や小部屋を指します。イベント案内で food stall（屋台）や、施設説明で shower stall（仕切り個室）として使われます。",
  "esteemed": "estimate(見積もる)と同語源で、高く評価された「高名な・尊敬されている」。式典や案内状で esteemed guests（ご来賓の皆様）のように相手を敬う表現で好まれます。",
  "accordance": "ac-(〜へ)＋cord(心)で心が一致すること。TOEICでは前置詞句の in accordance with ...（〜に従って・準拠して）が規則や方針を守る文脈で超頻出です。",
  "infringe": "in-(中に)＋fringe(破る)で境界を破る「侵害する」。知的財産や契約の文脈で、infringe on a patent（特許を侵害する）のように前置詞 on を伴う自動詞として頻出です。",
  "ballot": "かつて小球(ball)を箱に入れて意思表示した投票習慣が語源。役員選出の文脈で cast a ballot（1票を投じる）や secret ballot（無記名投票）の形で出題されます。",
  "perpetual": "per-(ずっと)＋pet(向かう)から「永久の」。ソフトウェア購入の案内で、月額制と対比して perpetual license（買い切り型の永久使用権）としてよく見られます。",
  "novelty": "novel(新しい)の名詞形。新奇さという概念のほか、販促やイベントの文脈では novelty items（記念品・ノベルティグッズ）のように具体物を指す複数形でも使われます。",
  "fledgling": "巣立ち前の雛鳥を指す語から「駆け出しの・新興の」。ビジネス記事で a fledgling company（創業間もない会社）や fledgling industry のように新興組織を修飾します。",
  "replenish": "re-(再び)＋plen(満たす・plentyと同語源)で「補充する」。備品や在庫管理で replenish supplies / stock（消耗品や在庫を補充する）の形で頻出です。",
  "boast": "無生物を主語にして「〜を誇る・自慢の設備を持つ」という意味で多用されます。The hotel boasts modern amenities のように広告文で feature の類語として出ます。",
  "faulty": "fault(欠陥)の形容詞形。サポート窓口への連絡やリコール通知で、faulty product / equipment（不良品・不具合のある機器）の交換・修理を求める文脈で頻出です。",
  "corridor": "イタリア語の「走る場所」に由来する「廊下・通路」。ホテルやオフィスの案内で hallway と同様に使われ、down the corridor（廊下の先に）などの位置説明で出ます。",
  "pantry": "ラテン語の panis(パン)の保管所が語源。現代のオフィス文脈では、社員が飲み物を淹れたり休憩したりする「給湯室・簡易キッチンスペース」の呼称として登場します。",
  "subsidize": "subsidy(補助金)の動詞形。行政の助成だけでなく、福利厚生で subsidized meals（補助が出る食事）や subsidize transportation の形で出ます。",
  "chamber": "ラテン語の「部屋」が語源。council chamber（議場）のほか、地域ビジネスの文脈で Chamber of Commerce（商工会議所）という組織名として頻出です。",
  "acidity": "acid(酸)の名詞形。化学的な「酸性度」のほか、カフェや食品紹介の記事で coffee with low acidity（酸味の少ないコーヒー）のように風味を表す文脈で登場します。",
  "gauge": "計器だけでなく、動詞で「測定する・推し量る」の意味で頻出。アンケート調査の文脈で gauge customer reactions（顧客の反応を探る・判断する）の形で使われます。",
  "attest": "ad-(〜へ)＋test(証言)で「証明する」。推薦状や利用者の声で、attest to the reliability（信頼性を証明する）のように前置詞 to を伴う自動詞の語法が頻出です。",
  "calamity": "ラテン語の「不運・損害」に由来する「大惨事・災難」。企業の危機管理や保険案内の文脈で natural calamities（自然災害）などの形で目にします。",
  "charcoal": "木を蒸し焼きにした「木炭」。社内イベントのバーベキュー案内やレストランの調理法紹介で、charcoal grill（炭火グリル）や cook over charcoal として登場します。",
  "bewilder": "be-＋wild(荒野で迷う)から「当惑させる」。TOEICでは受動態の be bewildered by ...（〜に戸惑う）や bewildering array（圧倒的な品揃え）の形で出ます。",
  "revamp": "re-(再び)＋vamp(靴の甲革を繕う)から「刷新する・大改修する」。TOEICでは revamp the company website（社内サイトを刷新する）などの目的語と共によく出ます。",
  "authoritative": "authority(権威)＋-ativeで「権威ある・信頼できる」。TOEICでは authoritative source（信頼できる情報源）の形でよく使われます。",
  "audiovisual": "audio(音声)＋visual(視覚)の合成語。TOEICでは研修や会議室の案内で、audiovisual equipment（視聴覚機器）の形で頻出する形容詞です。",
  "autobiography": "auto-(自己)＋bio-(生涯)＋graphy(書いたもの)で「自叙伝」。TOEICでは他人が書く biography（伝記）との区別が問われます。",
  "cinematography": "cinema(映画)＋graphy(記録・描写)に由来。TOEICでは映画祭などの告知で、cinematography award（撮影賞）のように使われます。",
  "systematic": "system(体系)＋-atic(形容詞語尾)。TOEICでは業務改善の文脈で、systematic approach（体系的な取り組み）の形で好まれます。",
  "congestion": "con-(共に)＋gest(集める)から「混雑」。TOEICの交通情報では traffic congestion（交通渋滞）や ease congestion（混雑緩和）が定番です。",
  "personalize": "personal(個人の)＋-ize(〜化する)。TOEICでは販促や顧客対応で、personalize service や personalized gifts（名入れギフト）の形で頻出です。",
  "criterion": "判断の基準を意味し、複数形は criteria。TOEICでは meet the criteria（基準を満たす）や selection criteria（選考基準）の形でよく出ます。",
  "proficient": "pro-(前へ)＋fic(進む)から「熟達した」。TOEICの求人要件で、be proficient in English のように前置詞 in とセットで頻出します。",
  "intermediate": "inter-(間に)＋medi-(中間)＋-ate。研修や語学講座の募集で、beginner（初級）と advanced（上級）の間の intermediate level として出ます。",
  "zeal": "「熱情」を意味するギリシャ語由来で、形容詞は zealous。推薦状や人事評価で、zeal for one's work（仕事への熱意）のように意欲を表します。",
  "deputy": "権限を「委任された人」が原義。TOEICでは役職名として deputy director（副部長）や deputy mayor（副市長）のように名詞の前につきます。",
  "coupon": "フランス語の「切り取る(couper)」が語源。TOEICの広告では redeem a coupon（クーポンを引き換えて使う）という動詞 redeem との連語が頻出です。",
  "checkout": "ホテルの退室だけでなく店舗やECの「レジ・会計」を指します。at checkout（お会計時に）や checkout counter（会計カウンター）の形で頻出です。",
  "journalism": "journal(日誌・新聞)＋-ism。求人や人物紹介で、investigative journalism（調査報道）や career in journalism（報道界での経歴）として出ます。",
  "booking": "帳簿(book)に記録することから「予約」。reservation の同義語として、confirm a booking（予約を確認する）や booking confirmation で頻出です。",
  "surprisingly": "surprise(驚き)＋-ing＋-ly。業績報告等で surprisingly low costs（驚くほど低い費用）のように、形容詞を前から強調する副詞として使われます。",
  "debate": "de-(強意)＋bate(打つ)で「論戦する」。TOEICでは市政や役員会の文脈で、hold a debate（議論を行う）や debate whether to do の形で出ます。",
  "productivity": "produce(生み出す)＋-ive＋-ityで「生産性」。業務改善や研修の効果として、boost productivity（生産性を高める）の組み合わせが頻出です。",
  "advertisement": "ad-(〜へ)＋vert(向ける)＋-mentで注意を向けるもの。place an advertisement（広告を出す）や run an advertisement の動詞との連語が定番です。",
  "mission": "mit/miss(送る)から「遣わされた任務」。会社案内で mission statement（企業理念）や fulfill one's mission（使命を果たす）の形でよく使われます。",
  "nearby": "near(近い)＋by(そばに)。形容詞と副詞の両方で使え、周辺案内で nearby restaurants（近隣の飲食店）や stay nearby（近くに宿泊する）の形で出ます。",
  "sharply": "sharp(鋭い)＋-ly。売上報告などのグラフ説明で、increase sharply（急増する）や drop sharply（急落する）のように急激な増減を表す定番副詞です。",
  "shift": "動詞では shift focus to ...（焦点を移す）、名詞では night shift（夜勤）のように勤務の「交代制」を表す文脈でTOEIC頻出です。",
  "generally": "general(全体の)＋-ly。店舗の営業案内で The office is generally closed on holidays（通常は休業）のように普段の原則を述べる際に出ます。",
  "proudly": "proud(誇りに思う)＋-ly。公式発表の冒頭で proudly announce（誇りを持って発表する）や proudly sponsor（協賛する）の形で頻出です。",
  "negotiate": "ラテン語の「余暇がない＝商取引する」が語源。契約交渉で negotiate terms（条件を取り決める）や negotiate with suppliers の形で頻出です。",
  "frequently": "frequent(頻繁な)＋-ly。バスの運行案内で run frequently（頻繁に運行する）や、Webの FAQ（Frequently Asked Questions）で定番です。",
  "solution": "solu-(解く)＋-tionで「解決策」。提案書などで an effective solution to the problem（問題への効果的な解決策）のように前置詞 to を伴います。",
  "surrounding": "sur-(周囲)＋round(囲む)＋-ing。形容詞で surrounding area（周辺地域）、名詞複数形 surroundings で「周囲の環境」を表します。",
  "sightseeing": "sight（名所）+seeing（見ること）からなる不可算名詞。a sightseeingとは言えず、go sightseeingやsightseeing tourの形で頻出。",
  "emergency": "動詞emerge（現れる・不意に生じる）の名詞形。in case of emergency（緊急時には）やemergency exit（非常口）など施設内の注意書きでよく見られる。",
  "commonly": "形容詞commonに-lyがついた副詞。commonly used（広く使われている）やcommonly known as（〜として知られる）のように過去分詞を前から修飾する形で出やすい。",
  "briefly": "brief（簡潔な）の副詞形。briefly explain（手短に説明する）やbriefly discussのように動詞を修飾するほか、「一時的に滞在する」の意味でも使われる。",
  "resolve": "re-（強意）+solve（解く）が原義。TOEICではresolve an issueやresolve customer complaints（苦情を解決する）のように問題解決の文脈で極めて頻出。",
  "ownership": "owner（所有者）+-ship（状態・権利）。take ownership of（〜の所有権を得る／責任を持って取り組む）やtransfer ownership（所有権を譲渡する）で頻出。",
  "timeline": "time（時間）+line（線）で進行日程を表す。project timeline（事業予定表）やset a strict timeline（厳格な日程を設定する）の形で頻出。",
  "ambitious": "名詞ambition（大志）の形容詞形。TOEICでは否定的な「野望」ではなく「意欲的な」という前向きな文脈で、ambitious goalやambitious planとして頻出。",
  "investigation": "in-（中へ）+vestige（足跡）をたどることが語源。conduct an investigation into ~（〜の調査を行う）のように前置詞intoを伴う形が頻出。",
  "specify": "specific（特定の）の動詞形。Part 5でunless otherwise specified（特に指定がない限り）という条件を表す定型表現が非常によく狙われる。",
  "maintenance": "動詞maintainの名詞形だが、綴りがmain-ten-anceに変化する点に注意。routine maintenance（定期点検）やunder maintenance（整備中）で頻出。",
  "promote": "pro-（前へ）+mote（動かす）が原義。「販売促進する」と「昇進させる」の2大用法があり、昇進はbe promoted to managerのように受動態+toでよく出る。",
  "disappointing": "事物が人を失望させる場合に-ing、人ががっかりした感情を表す場合に-ed（disappointed）を用いる区別がPart 5で頻出。disappointing results等で出る。",
  "overcome": "over（乗り越えて）+come（来る）の成り立ち。overcome challenges（課題を克服する）やovercome obstacles（障害を乗り越える）の目的語に注目。",
  "majority": "major（主要な）+-ity（名詞化）。a vast majority of（大多数の〜）やa large majority ofの形でアンケート調査や市場レポート（Part 7）に頻出。",
  "kneel": "名詞knee（ひざ）から派生した動詞。Part 1の写真描写問題で、作業員が床や地面にひざをついている姿勢を表すkneeling on the ground等の表現が狙われる。",
  "rapidly": "形容詞rapid（素早い）の副詞形。grow rapidly（急速に成長する）やexpand rapidly（急速に拡大する）のように事業や売上の急伸を表す動詞と共起する。",
  "tourism": "tour（周遊）+-ism（事業）。不可算名詞で、promote tourism（観光を推進する）やlocal tourism industry（地元の観光産業）の連語で頻出。",
  "permission": "不可算名詞のためa permissionとは言えない点に注意（可算のpermit「許可証」と区別）。without permission（無断で）やobtain permissionで頻出。",
  "capable": "ラテン語capere（つかむ）+-ableが語源。be able to doとは異なり、be capable of -ing（〜する能力がある）と前置詞of+動名詞を取る語法が最重要。",
  "competitor": "com-（共に）+petere（求める）+-or（者）。ビジネス文脈では個人の競争相手だけでなく「競合他社」を指し、gain an edge over competitorsの形で出やすい。",
  "boost": "「下から押し上げる」が原義。boost sales（売上を伸ばす）、boost productivity（生産性を高める）、boost morale（士気を高める）など他動詞として頻出。",
  "civil": "ラテン語civis（市民）由来。TOEICではcivil engineering（土木工学・土木工事）という専門用語として、建設関連の求人や企業紹介（Part 7）に頻出。",
  "acceptance": "動詞accept（受諾する）の名詞形。letter of acceptance（採用受諾書／承諾通知書）やterms of acceptance（受諾条件）のように文書名でよく登場する。",
  "logical": "ギリシャ語logos（言葉・理性）に由来。logical choice（妥当な選択）やlogical step（論理的な段階）のように、説得力ある提案や方針を説明する場面で出やすい。",
  "influential": "in-（中へ）+fluere（流れる）で「人の心に流れ込む力」が原義。an influential figure（影響力ある人物）やan influential publication等の形で頻出。",
  "landscape": "land（土地）+-scape（形状）。自然の景色のほか、landscaping company（造園業者）の案内や、competitive landscape（競争環境）という比喩表現でも出る。",
  "strategy": "ギリシャ語の「将軍の指揮術」が語源。develop a strategy（戦略を立てる）やimplement a strategy（戦略を実行する）のように動詞との組み合わせが頻出。",
  "reservation": "reserve（取っておく）+-ation。make a reservation（予約する）の基本表現に加え、have reservations about（〜に懸念を抱く）の意味も注意。",
  "convenience": "con-（共に）+venire（来る）で「都合よく合致すること」。ビジネスメールの結びでat your earliest convenience（ご都合のつき次第早く）が最頻出の定型表現。",
  "reject": "re-(後ろへ)＋ject(投げる)で投げ返すこと。TOEICでは reject a proposal（提案を却下する）のように使われ、turn down との言い換えも頻出です。",
  "inspiring": "in-(中に)＋spire(息・魂を吹き込む)で「人を奮い立たせる」。inspiring keynote speech（感動的な基調講演）のようにスピーチや人物を称賛する文脈で頻出です。",
  "remodel": "re-(再び)＋model(形作る)で店舗や建物を「改装する」。temporarily closed for remodeling（改装のため一時休業）のように通知文でよく見られます。",
  "supplement": "sub-(下から)＋ple(満たす)で「補う」。名詞 a supplement to ...（〜の補足）のほか、動詞 supplement one's income（収入を補う）の形でも使われます。",
  "removal": "動詞 remove に名詞語尾 -al が付いた形。equipment removal（機器の撤去）や snow removal（除雪）のように、施設管理の連絡文でよく登場します。",
  "apparent": "appear(現れる)と同語源で、外から見て明らかな状態。It became apparent that ...（…が明らかになった）や副詞 apparently（どうやら〜らしい）が頻出です。",
  "heavily": "heavy（重い）から転じて「非常に大きく・極度に」。rely heavily on ...（〜に大きく依存する）や invest heavily in ...（〜に多額投資する）の形で頻出です。",
  "reasonably": "reason(理屈)＋-able＋-ly で「理にかなって無理のない程度に」。reasonably priced（手頃な価格の）が定番で、affordable の同義表現として頻出です。",
  "container": "contain(含む)＋-er(もの)で「入れ物」。輸送用の shipping container だけでなく、保管用の airtight container（密閉容器）など物流の文脈で出ます。",
  "successfully": "succeed(成功する)の副詞形。have successfully launched や successfully completed のように、動詞の前や完了形の間で業績達成を伝える文脈で頻出です。",
  "expansion": "ex-(外へ)＋pand(広げる)の名詞形。business expansion（事業拡大）や expansion into ...（〜への進出）のように、企業の成長や新店舗展開の話題で定番です。",
  "assemble": "as-(〜へ)＋semble(同じ)で「1か所に集める」。assemble the parts（部品を組み立てる）と assemble in the hall（ホールに集まる）の両方の用法で出ます。",
  "institute": "in-(中に)＋stat/stit(立てる)で「組織や制度を立てる」。名詞の research institute（研究所）のほか、動詞で institute a policy（新規定を施行する）としても出ます。",
  "attempt": "ad-(〜へ)＋tempt(試す)で「果敢に試みる」。attempt to do（〜しようと試みる）と to 不定詞を取る形や、名詞 make an attempt to do の形で頻出です。",
  "convert": "con-(完全に)＋vert(向ける)で「向きをガラリと変える」。convert A into B（AをBに改修・換算する）が定番で、オフィスの用途変更や通貨・データ変換の文脈で出ます。",
  "extend": "ex-(外へ)＋tend(伸ばす)で「外に伸ばす」。extend the deadline（締め切りを延ばす）のほか、extend an invitation（招待を差し出す）のように好意を向ける用法も頻出です。",
  "emphasis": "en-(中に)＋pha-(示す)で「際立たせること」。place strong emphasis on ...（〜を強く重視する）という前置詞 on を伴う成句が定番で、他動詞 emphasize との区別も重要です。",
  "enlarge": "en-(〜にする)＋large(大きい)で物理的に「拡大する」。enlarge the meeting room（会議室を広げる）や enlarge a photo（写真を引き伸ばす）の文脈でよく出ます。",
  "increasingly": "increasing(増大する)＋-ly で「ますます」。increasingly popular（ますます人気のある）や increasingly difficult のように形容詞や分詞を修飾する形で頻出です。",
  "previously": "previous(前の)＋-ly で「以前に」。as previously announced（以前発表された通り）や previously scheduled のように、過去の決定事項を参照する定型句で頻出です。",
  "conflict": "con-(共に)＋flict(ぶつかる)で「衝突」。TOEICでは scheduling conflict（スケジュールの重複）の意味で頻出で、resolve a conflict（重複を解消する）とセットで出ます。",
  "novelist": "novel(目新しいこと→小説)＋-ist(人)で「小説家」。書店や図書館のイベント案内で best-selling novelist（ベストセラー作家）などの形でよく登場します。",
  "specifically": "specific(明確な・特定の)＋-ally で「特に」。designed specifically for ...（特に〜向けに設計された）のように、対象や用途を限定する受動態の文脈で非常によく使われます。",
  "approval": "approve(承認する)に -al が付いた名詞。obtain final approval（最終承認を得る）や subject to approval（承認を条件として）の形で出やすく、動詞との品詞区別も重要です。",
  "exceptional": "except(除外する)＋-ion＋-al で「例外的なほど優れた」。exceptional customer service（卓越した顧客対応）のように、人物やサービスの質を絶賛する文脈で使われます。",
  "wage": "古フランス語の「支払いの約束」が語源。minimum wage（最低賃金）や hourly wage（時給）のように労働量に応じて支払われる賃金を指し、固定月給の salary と区別されます。",
  "associate": "ad-(〜へ)＋socius(仲間)で「結びつける」。be associated with ...（〜に関連している・伴う）の受動態が頻出。名詞では sales associate（販売員）のように職務名で出ます。",
  "sophisticated": "ギリシャ語 sophos(賢い)が語源で「高度に洗練された」。sophisticated software や sophisticated technology のように、機器やシステムの高性能さを表す文脈で頻出です。",
  "current": "cur-(走る・流れる)から「今流れている」→「現在の」。current market conditions（現在の市場状況）や current employees（現職従業員）のように名詞の前で修飾する形が定番です。",
  "struggle": "スカンジナビア語起源で「もがき苦しみながら努力する」。struggle to meet the deadline（厳しい締め切りに間に合わせようと奮闘する）のように struggle to do の形で頻出です。",
  "remote": "re-(離れて)+mot(動かす)から「遠くへ離れた」。近年は remote work（テレワーク）や from a remote location の形で働き方や通信の文脈で出やすい。",
  "lumber": "主に北米で「木材・材木」を指す不可算名詞（英では timber）。建設や工場の資材調達の文脈で lumber yard（木材置場）や order lumber の形で使われる。",
  "patron": "pater(父・保護者)が語源で「後援者」から転じて施設や店舗の「常連客・利用者」を指す。library patrons（図書館の利用者）のように公共施設や美術館の案内で頻出。",
  "scope": "ギリシャ語の「観察・視野」に由来し、業務や計画の「適用範囲」を表す。beyond the scope of 〜（〜の適用範囲外で）や scope of work（業務範囲）の定型句が重要。",
  "steadily": "形容詞 steady(安定した)+ -ly で「着実に、規則正しく」。売上や業績の推移を表す定番副詞で、grow steadily や increase steadily の組み合わせで頻出。",
  "dependable": "depend(頼る)+ -able(できる)で「頼りにできる」→「信頼できる」。reliable の同義語で、dependable supplier（頼れる供給業者）など企業や製品の評判で使われる。",
  "concentrated": "con-(共に)+center(中心)で「一点に集中させた」。TOEICでは make a concentrated effort to do（〜しようと集中的に努力する）の表現でよく見られる。",
  "stable": "sta-(立つ)から「ぐらつかずに立っている」→「安定した」。maintain a stable price（安定した価格を維持する）や名詞形の stability（安定性）も要チェック。",
  "contribution": "con-(共に)+tribute(与える)で「寄与・貢献・寄付」。make a significant contribution to 〜 のように前置詞 to との結びつきが文法問題で問われやすい。",
  "laundry": "ラテン語の「洗う」に由来。TOEICでは主にホテルの宿泊案内で laundry service（洗濯サービス）や dry-cleaning と並んで案内文や領収書に登場する。",
  "engagement": "en-(〜にする)+gage(誓約)が語源。ビジネスメールでは「先約・予定」の意味で、due to a prior engagement（先約があるため）という辞退の定番表現で頻出。",
  "lighting": "不可算名詞でオフィス等の「照明設備・明かり」を表す。lighting fixtures（照明器具）や energy-efficient lighting（省エネ照明）の形で改装案内に頻出。",
  "lack": "名詞では lack of 〜（〜の不足）と of を取るが、動詞では他動詞として lack experience（経験に欠ける）のように of を直接取らない点が文法で狙われる。",
  "restore": "re-(再び)+store(立て直す)で「元の状態に戻す」。restore customer confidence（顧客の信頼を回復する）や停電後の restore power（電力を復旧する）で頻出。",
  "predict": "pre-(前もって)+dict(言う)で「前もって言う」→「予測する」。predict that 節の形で市場動向や売上の予測を述べる記事・レポートで使われる。名詞形は prediction。",
  "paragraph": "para-(そばに)+graph(書く)から「段落」。Part 7 の同義語問題や内容一致問題の設問文（In the second paragraph...）で頻出する指示語。",
  "partial": "part(部分)+ -ial(形容詞語尾)で「部分的な」。顧客対応や返品手続きで partial refund（一部返金）や partial payment（一部支払い）の形で出やすい。",
  "crossing": "動詞 cross(横断する)の名詞形で「横断歩道、交差点」。道案内やアクセス情報で pedestrian crossing（歩行者用横断歩道）や railway crossing（踏切）として頻出。",
  "fund-raising": "fund(資金)+raise(集める)で「資金調達、慈善募金」。fund-raising event / dinner / campaign（募金行事／夕食会／運動）のように複合名詞で頻出。",
  "outlet": "out(外へ)+let(出す)から「出口・直販店・差込口」。retail outlet（小売直販店）として店舗展開の文脈で出るほか、electrical outlet（電源コンセント）の意味も要チェック。",
  "critic": "「批評家（人）」。food critic（料理評論家）などレビュー記事に登場。派生語の criticism（批判・名詞）、critical（重大な／批判的な・形容詞）との品詞の区別が狙われる。",
  "postage": "post(郵便)+ -age(料金)で「郵便料金」を表す不可算名詞。配送や通信販売の書類で postage and handling（送料手数料）や postage rate（郵便料金）の形で頻出。",
  "originally": "origin(起源)+ -ally で「元々は、当初は」。日程変更のメールで be originally scheduled for 〜（当初は〜に予定されていた）と変更前の予定を示す合図になる。",
  "independently": "in-(否定)+depend(頼る)+ -ently で「他者に頼らず自立して」。求人票で work independently（指示を待たず自主的に動ける）という職務適性として頻出。",
  "generate": "gen-(生み出す)が語源。TOEICでは金銭や関心を生み出す意味で多用され、generate revenue（収益を生む）や generate interest（関心を集める）の形で頻出。",
  "preference": "pre-(前へ)+fer(運ぶ)から「優先するもの」→「好み」。研修申込書の dietary preferences（食事の希望・制限）や give preference to 〜（〜を優先する）で頻出。",
  "solid": "「固い」から転じてビジネスでは「確固たる、堅実な」の意味で多用される。a solid reputation（確固たる評判）や solid performance（手堅い業績）が定番の組み合わせ。",
  "profitable": "profit(利益)+ -able で「収益性の高い、有益な」。prove profitable（利益が出るとわかる）や highly profitable（高収益の）など決算報告や新事業の文脈で頻出。",
  "restrict": "re-(強く)+strict(引き締める)で「制限する」。restrict A to B（AをBに制限する）の受動態 be restricted to authorized personnel（関係者のみ立ち入り可）の形で頻出。",
  "manuscript": "manu-(手)+script(書かれたもの)から「手書き本」→「原稿」。出版文脈で submit a manuscript（原稿を提出する）や proofread a manuscript（原稿を校正する）の形で頻出。",
  "capture": "ラテン語 capere(つかむ)が語源。TOEICでは市場シェアを獲得する(capture a market share)や関心を集める(capture attention)の意味で頻出。",
  "dealership": "dealer(販売業者)+ -ship(特権)で「特約販売店」。car dealership や authorized dealership(正規代理店)の形で車や機器の販売・修理で頻出。",
  "evident": "e-(外に)+vid(見る)+ -ent で「見てすぐわかる」→「明白な」。形式主語の It is evident that 〜 や副詞 evidently(明らかに)の形で頻出。",
  "eliminate": "e-(外へ)+limin(敷居)+ -ate で「敷居の外に出す」→「排除する」。コストや無駄を省く文脈で eliminate waste や eliminate errors として出やすい。",
  "pastry": "paste(練り粉)+ -ry でパイ等の「焼き菓子」。ケータリングやカフェの案内で freshly baked pastries や assortment of pastries として頻出。",
  "accommodations": "ac-(〜へ)+com-(共に)+mod(適切な)が語源。「宿泊施設」の意味では通例複数形で、arrange accommodations(宿泊先を手配する)の形で頻出。",
  "portion": "ラテン語の「分け前」が語源。a portion of the budget(予算の一部)のように割合を示すほか、飲食で generous portions(多めの1人前)としても出る。",
  "tailor": "古仏語の「裁断する」に由来。名詞「仕立て屋」のほか、動詞で be tailored to customer needs(顧客のニーズに合わせて作られている)の受動態が頻出。",
  "output": "out(外へ)+put(出す)で「外に出された量」→「生産高」。工場の生産レポートで increase output(生産量を増やす)や daily output の形で頻出。",
  "interruption": "inter-(間に)+rupt(折る)+ -ion で「間に入って途切れさせること」。without interruption(中断なく)や service interruption(運行・停止)で頻出。",
  "obligation": "ob-(向かって)+lig(縛る)+ -ation で「人を縛るもの」→「義務」。fulfill one's obligations(義務を果たす)や under no obligation to do で頻出。",
  "adequate": "ad-(〜に)+equ(等しい)+ -ate で「基準に等しい」→「十分な・適切な」。adequate training(十分な研修)や adequate notice(事前の通知)の形で頻出。",
  "profile": "pro-(前へ)+file(輪郭を描く)から「横顔・概要」。TOEICでは company profile(会社概要)や、注目度の高さを表す high-profile project の形で頻出。",
  "reveal": "re-(外す)+veal(=veil 覆い)で「ベールを外す」→「明らかにする」。The survey revealed that 〜(調査で〜が判明した)の形でレポート等に頻出。",
  "ordinary": "ordin(順序・秩序)+ -ary で「秩序通りの」→「通常の」。during ordinary business hours(通常の営業時間中に)や対義語 extraordinary が頻出。",
  "completion": "動詞 complete の名詞形。upon completion of the project(計画完了時に)のように、前置詞 upon/on とセットで「〜の完了次第」を表す表現が頻出。",
  "corporation": "corpor(身体)+ -ation で「法人格を与えられた組織」→「大企業・法人」。multinational corporation(多国籍企業)や形容詞 corporate も頻出。",
  "measurement": "measure(測る)+ -ment で「測定・寸法」。改装や備品購入で take accurate measurements(正確な寸法を測る)の形で頻出。複数形で「寸法」を表す。",
  "optimistic": "optim(最善)+ -istic で「最善と信じる」→「楽観的な」。be optimistic about future sales のように前置詞 about と結びつく。対義語は pessimistic。",
  "presence": "pre-(前に)+es(ある)から「目の前にあること」→「存在感」。establish a strong presence in the market(市場で存在感を確立する)の表現で頻出。",
  "endeavor": "仏語の「義務を尽くす」に由来し「真剣な試み・努力」。送別メッセージで wish you success in your future endeavors(今後のご活躍を祈る)として頻出。",
  "authority": "author(創設者)+ -ity で「権限・権威」。専門家を表す an authority on 〜(〜の権威)や、the local authorities(地元当局)の複数形で頻出。",
  "aim": "動詞では aim to do(〜を目指す)と不定詞を取る形や、aim at 〜(〜を狙う)の前置詞 at が重要。企業の事業計画や環境目標を述べる文脈で頻出する。",
  "punctual": "punct(点)+ -ual で「指定の時刻にぴったりの」→「時間通りの」。Please be punctual for 〜(時間を厳守してください)や名詞形 punctuality も頻出。",
  "ample": "ラテン語の「広い・十分な」が語源。ample parking space(十分な駐車場)や ample time(十分な時間)のように「ゆとりがある」十分さを表す。",
  "outline": "out(外側)+line(線)から「輪郭を描く」→「概要を述べる」。outline the project schedule(計画日程の概要を説明する)のように他動詞でよく使われる。",
  "fulfill": "full(満ちた)+fill(満たす)で「完全に満たす」。fulfill obligations(義務を果たす)や、物流で fulfill customer orders(注文を処理・発送する)が頻出。",
  "retain": "re-(手元に)+tain(保つ)で「手元に残す」。retain customers(既存顧客をつなぎとめる)や retain talented staff(優秀な人材を引き留める)の形で頻出。",
  "urge": "urgere(追い立てる)が語源で urgent(緊急の)と同根。urge + 人 + to do(人に〜するよう促す)の第5文型が重要で、更新を促す通知文などでよく見られる。",
  "define": "de-(完全に)+fin(限界・境界)から「境界線を定める」→「明確にする」。clearly define the project scope(プロジェクトの範囲を明確に定義する)の形で頻出。",
  "asset": "原義は「負債を弁済するのに十分な資産」。TOEICでは不動産などの物的資産だけでなく、valuable asset to the teamのように「貴重な人材」の意味でもよく使われる。",
  "anticipated": "anti-(前に)+cip(つかむ)が語源。TOEICでは新製品や行事の発表で、highly anticipated や eagerly anticipated（待望の）の形でよく使われる。",
  "conventional": "con-(共に)+vent(来る)から「合意された慣習」。TOEICでは conventional methods（従来の方法）のように、innovative（革新的な）との対比で登場しやすい。",
  "consideration": "原義は「星々を観察して熟慮する」。TOEICでは take ... into consideration（〜を考慮に入れる）や under consideration（検討中で）の定型表現でよく登場する。",
  "consequence": "con-(共に)+sequ(続く)で「事態に伴って生じる結果」。TOEICでは as a consequence of（〜の結果として）や serious consequences（深刻な結果）の形で頻出する。",
  "strive": "strive to do（〜しようと努める）の形が基本。TOEICでは企業理念やサービス方針で、strive to provide や strive for excellence の形でよく使われる。",
  "modest": "modus（尺度）が語根で「度を越さない」が原義。TOEICの業績報告では modest increase や modest growth（控えめな伸び、わずかな増加）の形でよく使われる。",
  "vendor": "vend-(売る)+or(人)が語源。TOEICでは社外の納入業者や仕入れ先を指し、supplier と同様に approved vendor（承認業者）や local vendor の形でよく登場する。",
  "eventually": "event（出来事）から派生し、「紆余曲折の末に」という経過を含んだ「最終的に」を表す。TOEICでは遅延や交渉などのトラブルが最終的に解決する文脈でよく見られる。",
  "noted": "動詞 note（注目する）から派生し、「注目されている」→「著名な」。TOEICではイベントの告知や紹介文で、noted speaker や noted author の修飾でよく使われる。",
  "steep": "もともと「急勾配の」を意味するが、TOEICでは steep discount（大幅な割引）や steep decline（急激な下落）のように、価格や数値が急変する文脈でよく使われる。",
  "physician": "治療術に由来し、主に内科系の「医師」を指す。物理学者を表す physicist との混同に注意。TOEICでは primary care physician（かかりつけ医）の表現が頻出。",
  "considerably": "consider（考慮する）に値するほど「かなり」という意味。TOEICでは considerably higher のように比較級を強調したり、動詞 improved などを修飾する形で出題される。",
  "impose": "im-(上に)+pose(置く)で「上に重荷を課す」が原義。TOEICでは impose a fee on ...（〜に手数料を課す）のように、前置詞 on との組み合わせで出やすい。",
  "convinced": "con-(完全に)+vince(打ち負かす)で「説得されて確信した」状態を表す。TOEICでは be convinced that（〜だと確信している）や convince 人 to do の語法が頻出。",
  "garment": "身を装う言葉に由来し、1点ごとの「衣料品・衣服」を指す。TOEICではアパレル業界の話題や、garment manufacturer（衣料品製造業者）などの表現で見られる。",
  "specialize": "special（特別な）に由来。TOEICでは前置詞 in と結びつく自動詞 specialize in ...（〜を専門・得意分野とする）の形が最重要で、会社案内や職務経歴で非常によく使われる。",
  "mutual": "ラテン語の「交換する」が語源。TOEICでは契約や提携の場面で mutual agreement（合意）や for our mutual benefit（双方の利益のために）といった定型表現でよく使われる。",
  "consistently": "con-(共に)+sist(立つ)で「ブレずに一貫して立つ」イメージ。TOEICでは consistently rated high（常に高く評価されている）のように、優れた実績が継続している文脈で頻出する。",
  "objective": "ob-(向かって)+ject(投げる)から「目指す標的」。TOEICでは名詞「目標」（achieve the objective）と形容詞「客観的な」（objective opinion）の品詞の区別が問われやすい。",
  "controversial": "contro-(反対に)+vert(向ける)で「論争になる」が原義。TOEICでは controversial decision（賛否両論の決定）や controversial plan の形で、方針変更への議論を表す際に出る。",
  "allowance": "allow（認める・許す）から「認められた枠」。TOEICでは baggage allowance（手荷物許容量）のような制限枠と、travel allowance（出張手当）のような支給金の両方で頻出する。",
  "promptly": "TOEICでは主に2つの使われ方がある。promptly at 9:00（9時ちょうどに）という時刻の指定と、respond promptly（速やかに返答する）という迅速な対応の要求のどちらも頻出。",
  "legislation": "leg-(法律)+lat-(提案する)が語源の不可算名詞。TOEICでは pass legislation（法案を可決する）や comply with legislation（法律に従う）のコロケーションでよく登場する。",
  "remark": "re-(強意)+mark(印)から「述べる」。TOEICでは特に複数形 remarks で挨拶やスピーチを指し、opening remarks（開会の辞）や closing remarks（閉会の辞）が頻出。",
  "perspective": "per-(通して)+spect(見る)で「全体を見通す視点」。TOEICでは gain a fresh perspective（新たな視点を得る）や from the perspective of（〜の観点から）の形でよく使われる。",
  "precisely": "pre-(前もって)+cise(切る)で「余分を切り落とした正確さ」。TOEICでは follow instructions precisely（指示に厳密に従う）や precisely at 10:00 の形で使われる。",
  "speculation": "spec-(見る)から「先行きを推し量る」→「憶測」。TOEICでは fuel speculation（憶測をあおる）や speculation about a merger（合併についての憶測）の形で登場する。",
  "assignment": "as-(〜へ)+sign(印をつける・割り当てる)が語源。学校の「宿題」だけでなく、TOEICでは overseas assignment（海外赴任）のように仕事上の「割り当てられた任務」の意味で頻出する。",
  "instrumental": "instrument（道具・手段）から「手段として役立つ」が原義。TOEICでは play an instrumental role in や be instrumental in doing（〜に大いに貢献する）の形で頻出する。",
  "registration": "register(記録する)+ -ation(名詞語尾)。セミナー等で registration form（登録用紙）や advance registration（事前登録）の形でよく使われる。",
  "renewal": "re-(再び)+new(新しい)+ -al で「更新」。lease renewal（リース更新）や membership renewal（会員更新）など契約や会員資格の文脈で頻出。",
  "economics": "ギリシャ語の「家政管理」に由来。学問名として単数扱いされる。形容詞 economic（経済の）と economical（経済的な・お得な）の意味の混同を問う問題にも注意。",
  "simplify": "simple(単純な)+ -ify(〜にする)で「簡単にする」。simplify the process（手続きを簡素化する）など業務効率化の文脈で頻出。",
  "identification": "identify(特定する)+ -ationで「本人確認・身分証」。身分証の意味では不可算扱いで、two forms of identification（身分証2点）の形で頻出。",
  "mobile": "ラテン語 movere(動く)に由来し「動かせる」。mobile device（モバイル端末）や mobile app のほか、mobile unit（移動診察車）などの修飾でも登場。",
  "applicant": "apply(応募する)+ -ant(人)で「応募者」。求人票で qualified applicants（適任な応募者）の形で出やすく、application（応募書類）との混同に注意。",
  "optional": "opt(選ぶ)+ -alで「選択自由の」。completely optional（完全に任意）の形でよく使われる。mandatory（必須の）の対義語としても押さえたい。",
  "insert": "in-(中に)+serere(つなぐ)で「差し込む」。機器の操作で insert A into B（AをBに挿入する）の語法で出やすく、名詞では「折込広告・同封物」も表す。",
  "knowledgeable": "knowledge(知識)+ -able で「精通した」。highly knowledgeable about 〜（〜にとても詳しい）のように副詞 highly や前置詞 about と共起しやすい。",
  "introductory": "intro-(中へ)+duct(導く)+ -oryで「導入の」。新商品や会員募集で introductory price（初回お試し価格）や introductory offer の形で頻出。",
  "installation": "in-(中に)+stall(置く)+ -ationで「据付・設置」。installation guide（設置説明書）や free installation（無料設置）の複合名詞で頻出。",
  "attendance": "attend(出席する)+ -anceで「出席・来場者数」。record attendance（過去最高の人出）のように数を表す用法や、attendee（出席者）との品詞区別に注意。",
  "enrollment": "en-(中に)+roll(名簿)+ -ment で「登録・受講」。講座等で open enrollment（受付期間）や enrollment form（申込書）として頻出。動詞 enroll in も重要。",
  "receptionist": "reception(受付)+ -ist(人)で「受付係」。check in with the receptionist（受付で手続きをする）や see the receptionist の形で頻出。",
  "attachment": "attach(貼り付ける)+ -mentで「添付ファイル」。メールの定番句 please see the attachment（添付をご覧ください）や email attachment の形で頻出。",
  "accountant": "account(計算する)+ -ant(人)で「会計士」。certified public accountant（公認会計士、CPA）の肩書で登場し、業務を表す accounting（経理）との区別に注意。",
  "reminder": "re-(再び)+mind(心)+ -er で「思い出させるもの」。メールで This email serves as a reminder（念のためのご案内です）のように定型句として使われる。",
  "prediction": "pre-(前もって)+dict(言う)+ -ion で「予測」。make a prediction about 〜（〜の予測を立てる）や accurate predictions（正確な予測）の形で頻出。",
  "willingness": "will(意志)+ -ness で「進んで行う意欲」。demonstrate a willingness to learn（進んで学ぶ姿勢を示す）のように後ろに to 不定詞を従える形が頻出。",
  "qualification": "qualify(適格とする)+ -ationで「資格・要件」。求人票で meet the qualifications（要件を満たす）や minimum qualifications（最低要件）の形で頻出。",
  "pharmacist": "ギリシャ語 pharmakon(薬)+ -ist(人)で「薬剤師」。薬局や医療の文脈で pharmacy（薬局）や prescription（処方箋）とセットで出やすい。",
  "accelerate": "ac-(〜へ)+celer(速い)+ -ate で「速度を上げる」。accelerate growth（成長を加速する）や accelerate the process（手続きを早める）の形で頻出。",
  "lengthy": "length(長さ)+ -y で「長くて退屈な・長引く」。単に長いだけでなく、lengthy delay（大幅な遅延）や lengthy process（長引く手続き）のように厄介さを伴う場面で出やすい。",
  "assorted": "as-(〜へ)+sort(種類)+ -ed で「各種取り揃えた」。ギフトや食品で assorted flavors（各種フレーバーの詰め合わせ）や assorted chocolates の形で頻出。",
  "enclosure": "en-(中に)+close(閉じる)+ -ure で「同封物」。書簡で please find the enclosures（同封物をご確認ください）のように使われ、メールの attachment（添付）と対比される。",
  "staircase": "stair(階段)+case(枠)で「一連の階段」。建物案内で take the staircase（階段を使う）や emergency staircase（非常階段）の形で出やすい。",
  "incentive": "ラテン語の「鼓舞するもの」に由来し「動機・優遇策」。tax incentives（税制優遇措置）や offer an incentive to do（〜する動機を与える）の形で頻出。",
  "countless": "count(数える)+ -less(ない)で「無数の」。spend countless hours doing（〜に膨大な時間を費やす）や countless awards（多数の受賞）のように実績を称える文脈で頻出。",
  "energetic": "energy(活力)+ -etic で「精力的な」。人物紹介やセミナーで an energetic speaker（情熱的な講演者）のように人やスピーチの様子を修飾する語として使われる。",
  "inexpensive": "in-(否定)+expensive(高価な)で「手頃な価格の」。cheapと違い品質への否定的響きがなく、inexpensive alternative（手頃な代替案）や option と共に頻出。",
  "patiently": "patient(我慢強い)+ -ly で「辛抱強く」。遅延案内や窓口対応で wait patiently for the announcement（発表を辛抱強く待つ）の形でよく使われる。",
  "shipment": "ship(船で運ぶ・発送する)+ -ment(名詞語尾)で、陸送や航空便も含めた「積荷・発送」全般を指す。track a shipment（荷物を追跡する）のコロケーションが頻出。",
  "publicize": "public(公の)+ -ize(動詞語尾)で「広く世間に知らせる・宣伝する」。催し物の告知で publicize the upcoming event や widely publicized の形で頻出。",
  "reportedly": "report(報告する)+ -ed + -ly で「伝えられるところによれば」。Part 7 の記事で is reportedly planning to do（〜を計画中と報じられている）のように頻出。",
  "quote": "「引用」だけでなく名詞の「見積もり（額）」がTOEICの最重要語義。request a price quote（見積もりを依頼する）や get a free quote（無料見積もりを取る）で頻出。",
  "participant": "part(部分)+cip(取る)+ -ant(人)で「参加者」。seminar participants（セミナー参加者）のように用いられ、動詞 participate は前置詞 in を伴う点も文法で重要。",
  "recipient": "re-(再び)+cip(受け取る)+ -ent(人)で「受取人、受賞者」。表彰式で the recipient of the award（賞の受賞者）や、メールの受取人を指す文脈で頻出。",
  "insight": "in-(内部を)+sight(見ること)から「深い知見、洞察」。前置詞 into と結びつきやすく、gain valuable insights into 〜（〜についての貴重な知見を得る）の形で頻出。",
  "facilitate": "ラテン語の facilis(容易な)が語源で「円滑にする、容易にする」。ビジネスで facilitate communication（意思疎通を円滑にする）や facilitate growth で頻出。",
  "exclusive": "ex-(外に)+clude(締め出す)+ -ive で「他を閉め出した」→「独占的な、会員限定の」。exclusive access to 〜（〜への限定アクセス権）の形で頻出。",
  "revitalize": "re-(再び)+vital(命の)+ -ize で「活力を取り戻させる」。都市再生の記事で revitalize the downtown area（中心街を活性化する）や the economy で頻出。",
  "spectacular": "語根 spect(見る)に由来し「目を見張るような、壮観な」。ホテルの宿泊案内や観光広告で a spectacular view of the ocean（壮観な海の眺め）の組み合わせが頻出。",
  "notable": "note(注目する)+ -able で「注目に値する」。notable achievement（顕著な功績）や notable increase（著しい増加）のように業績報告で頻出。副詞形 notably も要確認。",
  "foster": "food(食べ物)と同源で、本来は「養育する」から「育成する、促進する」。foster teamwork（チームワークを育む）や foster innovation（革新を促す）のように社内方針で頻出。",
  "nutritious": "nutri-(育てる・養う)から「栄養のある」。社員食堂の案内や福利厚生の文脈で nutritious meals（栄養のある食事）や balanced and nutritious の形でよく使われる。",
  "expertise": "expert(専門家)から「専門知識・技術」。不可算名詞（数えられない）である点と、have expertise in 〜（〜分野の専門知識を持つ）と前置詞 in を取る形が頻出。",
  "execute": "ex-(完全に)+secut(追う)から「最後までやり遂げる」→「実行する」。execute a plan（計画を実行する）や execute a contract（契約を締結・履行する）の形で頻出。",
  "compile": "com-(共に)+pile(積み重ねる)から「資料を一箇所に集めてまとめる」。compile data / a report（データを集計する／報告書を取りまとめる）のように事務作業の文脈で頻出。",
  "interoffice": "inter-(〜の間の)+office で「社内の、部門間の」。Part 7 の文書見出しで interoffice memo（社内回覧メモ）や interoffice mail（社内便）として頻出。",
  "compromise": "com-(共に)+promise(約束する)から「双方が譲り合って合意する」→「妥協」。reach a compromise（妥協点に達する）や compromise on 〜（〜について妥協する）で頻出。",
  "revision": "re-(再び)+vis(見る)+ -ion で「見直し、改訂」。スケジュールや規約の末尾に添えられる be subject to revision（変更される場合がある）は Part 7 の超頻出定型句。",
  "continuous": "con-(共に)+tin(保つ)で「途切れなく続く」。品質管理で定番の continuous improvement（継続的改善）や continuous efforts（不断の努力）の形で頻出。",
  "certified": "cert(確実な)+ -ify + -ed で「公的に資格・品質を保証された」。certified public accountant（公認会計士）や certified technician で頻出。",
  "inquiry": "in-(中へ)+quir(求める・尋ねる)から「問い合わせ」。respond promptly to customer inquiries（顧客の問い合わせに迅速に対応する）の形で頻出。",
  "fabric": "ラテン語の「職人の製作物」が語源で「織物、生地」。家具の椅子張りや制服の文脈で durable fabric（耐久性のある布地）や stain-resistant fabric（防汚生地）として頻出。",
  "remainder": "動詞 remain(残る)の派生名詞で「残り」。for the remainder of the week / year（今週／今年度の残りの期間）のように、期間を表す前置詞句として頻出。",
  "screening": "screen(ふるいにかける)から採用の「書類選考、審査」。initial screening（一次選考）や screening process（選考過程）のように求人・面接の文脈でよく登場する。",
  "pension": "ラテン語の「支払い」が語源で「年金」。福利厚生の説明で pension plan（年金制度）や contribute to a pension（年金に拠出する）の形で retirement（退職）と共に頻出。",
  "overwhelmingly": "over-(超えて)+whelm(覆い尽くす)+ -ingly で「圧倒的に」。アンケート結果やレビューで overwhelmingly positive reviews（圧倒的に好評なレビュー）の組み合わせで頻出。",
  "subscribe": "sub-(下に)+scribe(書く)で「下に署名する」が原義。自動詞として前置詞 to を取り、subscribe to a magazine（雑誌を定期購読する）の形で頻出。",
  "duration": "dur-(硬い・長持ちする)から「持続・期間」。for the duration of 〜（〜の全期間中）という群前置詞の形で、研修やイベントの案内文・アナウンスによく登場する。",
  "initiate": "in-(中に)+it-(行く)から「中に入って始める」。start の堅い語で、initiate an investigation（調査を開始する）や initiate a project の形で頻出。",
  "spacious": "名詞 space（空間）+ -ious（〜に満ちた）で「広々とした」。spacious office や spacious room のように、不動産やホテルの案内文で頻出。",
  "abundant": "ab-(外へ)+und-(波打つ)から「あふれ出る」→「豊富な」。abundant parking space（十分な駐車スペース）のように施設や資源の文脈で出る。",
  "delegation": "de-(離れて)+legare(使者を送る)が語源。trade delegation（通商代表団）のほか、業務の「委譲」の意味や動詞 delegate（委任する）も頻出。",
  "tutorial": "tutor(個別指導者)に由来し「操作解説・指導書」を指す。video tutorial や online tutorial の形で、ITツールの研修やサポート案内に頻出。",
  "prestigious": "ラテン語の手品・幻影から「人を魅了する名声」へ発展。prestigious award（権威ある賞）や prestigious university のように受賞歴や経歴の紹介で頻出。",
  "periodical": "period(周期)+ -ic + -al で「定期的に出る刊行物」。quarterly periodical（季刊誌）のように雑誌や会報の総称として、出版や購読の案内で頻出。",
  "synthetic": "syn-(共に)+thet-(置く)で「組み合わせて作った」。natural（天然の）の対義語で、synthetic fibers（合成繊維）のように製品仕様の文脈で頻出。",
  "mutually": "mutual（相互の）の副詞形。形容詞を修飾する mutually beneficial（双方に有益な）や mutually agreeable（相互に合意可能な）の組み合わせが頻出。",
  "specification": "specific（具体的な）の名詞形。実務やTOEICでは複数形 specifications で「仕様書」を指し、meet specifications（仕様を満たす）の形で頻出。",
  "resistant": "re-(対抗して)+sist(立つ)から「耐性がある」。water-resistant（耐水性の）や resistant to shock（衝撃に強い）など製品の性能説明で頻出。",
  "intentionally": "in-(向かって)+tend(伸ばす)で「意図を持って」。accidentally（誤って）の対義語で、intentionally delayed（意図的に遅らせた）などの文脈で出る。",
  "obstruct": "ob-(前に)+struct(築く)で「前に壁を築いて塞ぐ」。obstruct traffic（交通を妨げる）や obstruct the entrance（入口を塞ぐ）のように注意文で頻出。",
  "solely": "sole（唯一の）+ -ly で only の改まった表現。based solely on 〜（〜にのみ基づいて）や solely responsible（単独で責任を負う）の形で頻出。",
  "embrace": "em-(中に)+brace(腕)で「抱きとめる」→「受け入れる」。ビジネスでは embrace new technology（新技術を採用する）や embrace change で頻出。",
  "offset": "off-(離して)+set(置く)で釣り合いを取る。offset the loss（損失を埋め合わせる）や offset the cost のように収支を相殺する文脈で頻出。過去形も同形。",
  "dominant": "ラテン語 dominus(主人)から「支配的な」。dominant market share（圧倒的な市場シェア）や dominant player（主導的企業）のように業界動向の記事で頻出。",
  "agreeable": "agree（合意する）+ -able（できる）。「感じが良い」のほか、terms agreeable to both parties（双方に受け入れ可能な条件）のように契約条件の文脈で頻出。",
  "proceeds": "proceed（前進する）に由来。常に複数形で「売上金・収益」を指し、All proceeds will be donated to 〜（収益はすべて〜に寄付される）の定型句で頻出。",
  "fierce": "ラテン語の「野生の」が語源。TOEICでは動物ではなく fierce competition（激しい競争）という、市場や業界内の熾烈な競合関係を表すコロケーションで頻出。",
  "anecdote": "ギリシャ語の「未公刊のもの」から個人の「逸話」。スピーチや研修で share a personal anecdote（個人的な逸話を話す）のように、導入エピソードの文脈で出る。",
  "rigorous": "rigor(厳しさ)+ -ous で strict の改まった語。rigorous testing（厳格な試験）や rigorous inspection（綿密な検査）のように品質管理や審査で頻出。",
  "supplementary": "supplement(補うもの)+ -ary で「追加の」。supplementary materials（補足資料）や supplementary information の形で、研修や配布物の案内で頻出。",
  "concise": "con-(完全に)+cise(切る)で「不要部分を切り落とした」。clear and concise（明瞭で簡潔な）がビジネス文書の定番句で、keep it concise も頻出。",
  "medication": "medi-(治療する)から「医薬品」。take medication（薬を服用する）や prescribed medication（処方薬）の形で、健康管理や医療の文脈で使われる。",
  "disruption": "dis-(ばらばらに)+rupt(壊す)で「分裂・混乱」。cause disruption to 〜（〜に支障をきたす）や service disruption（運行の乱れ）の形で頻出。",
  "adhere": "ad-(〜に)+here(くっつく)から「固守する」。自動詞で前置詞 to を取り、adhere to guidelines（ガイドラインを遵守する）の形で規定遵守の文脈に頻出。",
  "prominently": "pro-(前へ)+min-(突き出る)から「目立つように」。display signs prominently（標識を目立つように掲示する）のように、掲示や広告の配置の文脈で頻出。",
  "transparent": "trans-(通り抜けて)+parere(見える)が語源。TOEICでは物理的な透明さだけでなく、transparent process（透明性のあるプロセス）のように情報開示の文脈で登場する。",
  "outfit": "名詞「一揃いの衣装・装備」に加え、be outfitted with...（〜が備え付けられている）という受動態の動詞用法がオフィスや施設の改装通知でよく問われる。",
  "distraction": "dis-(離れて)+tract(引く)で、意識があちこちに引っ張られること。オフィス環境の改善文脈で minimize distractions（気の散る要因を最小限にする）の形でよく出る。",
  "notorious": "notus(知られた)が語源で、悪い意味で有名なこと。交通渋滞や遅延の描写で be notorious for...（〜で悪名高い）の形で前置詞 for を伴って使われる。",
  "transit": "trans-(越えて)+it(行く)で、場所を通り抜けて運ぶこと。public transit（公共交通機関）のほか、荷物の追跡画面で in transit（輸送中）の表示として頻出。",
  "devise": "名詞 device（装置・工夫）に対応する動詞。知恵を絞って新しく作り出す意味で、devise a strategy（戦略を考案する）や devise a plan の形で多用される。",
  "obsolete": "使われなくなって廃れた状態を表す。システムの刷新や機器の入れ替え告知で、become obsolete（時代遅れになる・旧式化する）の形でよく目にする。",
  "detect": "de-(取り除く)+tect(覆う)で、覆いを外して暴くのが原義。品質管理や検査の文脈で detect defects（欠陥を見つける）や detect errors の形で頻出。",
  "adoption": "ad-(〜へ)+opt(選ぶ)で、選んで取り入れること。新技術や制度の導入文脈で使われ、似た形の adaptation（適応・改変）と意味を取り違えないよう注意。",
  "commence": "start や begin の硬いフォーマル表現。契約書や工事・式典の公式通知でよく使われ、commence on [日付] や工事が主語で「始まる」自動詞としても多用される。",
  "incorporate": "in-(中へ)+corpor(身体)で、組織の体内に組み入れるのが原義。incorporate A into B（AをBに取り入れる）の形でフィードバックの反映や機能追加によく使われる。",
  "exquisite": "ex-(外へ)+quisit(探し求める)で、選び抜かれた極上のものを表す。レストランやホテルのレビュー・広告で exquisite cuisine（極上の料理）の形容詞としてよく出る。",
  "breathtaking": "breath（息）を take（奪う）ほど圧倒的であることから。旅行ツアーやホテル案内の広告で、breathtaking view（息をのむ絶景）という組み合わせで登場する。",
  "centerpiece": "テーブルの中央に置く主役の装飾品が原義。転じて展示会や事業計画の「最大の目玉・中心」を指し、the centerpiece of the campaign のように使われる。",
  "pharmaceutical": "ギリシャ語の pharmakon（薬）に由来する。TOEICでは企業情報や求人広告で a pharmaceutical company（製薬会社）という業種を表す名詞句として頻出。",
  "oversight": "over-(上から)+sight(見る)。上から全体を点検する「監視・監督」と、見過ごしてしまう「見落とし・過失」の両義がある。clerical oversight（事務的ミス）はお決まり表現。",
  "reimbursement": "re-(再び)+im-(中へ)+burse(財布)で、払ったお金を財布に戻すこと。出張旅費の精算規定で request reimbursement for...（〜の払い戻しを申請する）と頻出。",
  "equipped": "動詞 equip の過去分詞。be equipped with...（〜が備わっている）や、a fully equipped conference room（設備の整った会議室）のように施設説明で活躍する。",
  "botanical": "ギリシャ語で草・植物を意味する語が由来。TOEICではほぼ観光案内やイベント会場の文脈で使われ、botanical garden(s)（植物園）という連語で覚えておくのが確実。",
  "keenly": "形容詞 keen（鋭い・熱心な）の副詞形。顧客の需要や課題を痛切に認識している文脈で、be keenly aware of...（〜を強く意識している）の形でよく使われる。",
  "itemize": "item（項目）+-ize（〜化する）で、1項目ずつ明細を分けること。請求書や経費精算で itemize all expenses（全経費の内訳を明記する）や itemized receipt（内訳付き領収書）と出る。",
  "occupancy": "動詞 occupy（占有する）の名詞形。ホテルや商業ビルの稼働状況を表す occupancy rate（客室稼働率・入居率）や、安全基準の maximum occupancy（定員・最大収容人数）で頻出。",
  "thoughtfully": "thought（考え）+-ful+-ly で、相手や利用者への細やかな配慮が行き届いている様子。thoughtfully designed（配慮の行き届いた設計の）のように過去分詞を修飾する。",
  "artifact": "arte(技術・人の手で)+fact(作られたもの)が語源。博物館の展示案内や特別展のニュースで、historical artifacts（歴史的工芸品）などの形で目にする。",
  "outreach": "out-(外へ)+reach(手を伸ばす)で、外の地域社会へ手を差し伸べること。企業の社会貢献活動として community outreach program（地域奉仕プログラム）の形でよく使われる。",
  "mentor": "ギリシャ神話で王の息子を導いた賢者メントールに由来。新入社員研修などの文脈で、名詞としてだけでなく mentor new employees（新人を指導する）と動詞でも使われる。",
  "skeptical": "よく吟味して容易に信じない態度を表す。事業計画や合併の提案に対して役員が慎重姿勢を示す場面で、be skeptical about...（〜に懐疑的である）の形で前置詞 about や of を伴う。",
  "memorabilia": "memory（記憶）と同語源で、歴史や出来事を思い起こさせる品々。sports memorabilia（スポーツの記念品・グッズ）のように、ファン向け記念コレクションの文脈で登場する。",
  "fluctuation": "fluere(流れる)から「波打つ」が原義。為替や原油価格、売上の上下動を表し、price fluctuations（価格変動）や fluctuations in demand（需要の変動）の形で頻出。",
  "faucet": "樽の差し口を指す古フランス語が由来。オフィスの営繕依頼やホテルのトラブル連絡で、leaking faucet（水漏れしている蛇口）や fix a faucet という文脈でよく登場する。",
  "feasible": "facere(行う)+-ible(できる)で「実行できる」。economically feasible（経済的に実現可能な）などのコロケーションや、名詞形 feasibility study（実現可能性調査）でも頻出。",
  "foremost": "古英語で「一番前」を二重に強調した語。登壇者の紹介や推薦文で one of the foremost experts（屈指の専門家の一人）や foremost authority（第一人者）として頻出。",
  "gala": "「祝祭・歓楽」を意味する語に由来する華やかな宴会。charity gala や fundraising gala（慈善資金集めパーティー）のように、annual を伴う社内行事や招待状で頻出。",
  "repave": "re-(再び)+pave(舗装する)。従業員への社内通知で repave the parking lot（駐車場を再舗装する）の形でよく出題され、工事に伴う迂回（detour）の文脈と連動しやすい。",
  "turnover": "人が入れ替わることから人事の文脈で employee turnover（離職率）として頻出。reduce employee turnover（離職率を下げる）や turnover rate の連語が狙われやすい。",
  "shortcoming": "目標の高さに「届かない(short-coming)」ことから「欠点・短所」。改善提案の文書で address shortcomings（短所に対処する）のように複数形で動詞 address とよく共起する。",
  "anonymous": "an-(無)+onym(名前)で「名前のない」。アンケートや人事調査で anonymous survey（無記名アンケート）や、remain anonymous（匿名のままでいる）の形でよく使われる。",
  "avid": "強く求めることを意味するラテン語が語源。人物紹介や略歴で avid reader（熱心な読者）や avid collector（熱心な収集家）のように名詞の前につく定番の修飾語。",
  "definitive": "de-(完全に)+fin(限界・終わり)で、最終決定して揺るぎないこと。ビジネスの連絡で definitive answer（決定的な回答）や definitive guide（決定版）の形で使われる。",
  "privileged": "個人(privus)の法(lex)が語源で「特別扱いされた」。スピーチや挨拶状で feel privileged to do（〜できて光栄に思う）のように感謝や敬意を伝える表現でよく登場する。",
  "perishable": "perish(滅びる・傷む)+-able(できる)から「傷みやすい」。輸送や倉庫の文脈で perishable goods / items（生鮮食品・傷みやすい物品）として冷蔵保管指示と共に出やすい。",
  "sturdy": "古フランス語で「たくましい」を意味する語から。梱包やオフィス家具の文脈で sturdy box（頑丈な箱）や sturdy construction（頑丈な造り）として製品の耐久性を表す。",
  "jeopardy": "古フランス語「五分五分の勝負」から「危険・危機」。TOEICでは put [プロジェクト] in jeopardy（〜を危機にさらす）という成句で前置詞 in と共によく出題される。",
  "imperative": "imperare(命令する)が語源で「避けて通れない」。It is imperative that S (動詞の原形)...（〜することが不可欠だ）の仮定法現在の構文で締め切りの通知などによく出る。",
  "recur": "re-(再び)+cur(走る)で「再び巡り走る」。機器の不具合やエラーの報告で prevent issues from recurring（問題の再発を防ぐ）のように prevent と共に使われることが多い。",
  "abridged": "brevis(短い)が語源で「短縮された」。出版や調査レポートの案内で an abridged version（要約版）や abridged edition の形で、多忙な読者向け要約資料として登場する。",
  "turnout": "人々が外へ集まり出ること(turn out)から「来場者数・参加者数」。イベント報告で a large turnout や turnout for the event（催しの参加者数）の形で非常によく使われる。",
  "cubicle": "小さな寝室を意味するラテン語が語源。TOEICではオフィスの間仕切りで区切られた個人席を指し、office renovation（オフィス改装）の案内や座席配置の話題で頻出。",
  "tenure": "tenere(保持する)が語源で、職や地位を保持する期間。役員の退任スピーチや人事ニュースで during her tenure as CEO（CEOとしての在任期間中に）の形で定着している。",
  "outage": "供給が切れて外れること。システム障害や設備の保守通知で power outage（停電）や service outage（サービス停止）のように outage の前に停止対象を置いてよく使われる。",
  "demolish": "de-(崩す)+moliri(築く)で「築いた建物を崩す」。再開発や新社屋建設の文脈で、old building will be demolished（古い建物が取り壊される）と受動態でよく出る。",
  "compatible": "com-(共に)+pati(耐える)で「両立して一緒にいられる」。ITや新機器の導入文脈で be compatible with...（〜と互換性がある）の形で前置詞 with とセットで頻出。",
  "unanimous": "uni-(一つの)+animus(心)で「全員が同じ心」。取締役会の採決で unanimous decision（満場一致の決定）や unanimous vote（全会一致の投票）としてよく登場する。",
  "streamline": "「流線型にして抵抗を減らす」が原義。業務改善の提案で streamline the process（プロセスを効率化する）や streamline operations（業務を合理化する）の形で頻出。",
  "discreetly": "「見分けて分別がある」が原義。機密保持や顧客対応で handle matters discreetly（慎重に／内密に対処する）のように使われる。綴りが似た discrete（個別の）と混同注意。",
  "consolidate": "con-(共に)+solid(固い)で「固めて一つにする」。組織再編やコスト削減で consolidate A into B（AをBに統合・集約する）のように前置詞 into を伴う語法が頻出。",
  "bearer": "bear(運ぶ・持つ)+-er(人)で「券面の持ち主」。割引券や招待状の注意書きで entitle the bearer to a discount（持参人に割引を受ける権利を与える）の形で頻出。",
  "stagnant": "水が流出せずよどむことが原義。市場分析や経済ニュースで a stagnant economy（停滞した経済）や stagnant sales（伸び悩む売上）のように景気低迷の描写で頻出。",
  "carpool": "car(車)+pool(出し合う・共同利用)。通勤渋滞やエコ対策の社内通知で encourage employees to carpool（社員に相乗り通勤を促す）のように動詞としてよく登場する。",
  "installment": "install(配置する)から「小分けにして設定したもの」。購入案内で pay in monthly installments（月々の分割払いで支払う）のように複数形で前置詞 in と共によく出題される。",
  "viable": "フランス語 vie（生命）+-able で「生存できる」が原義。ビジネスでは「実現可能な・採算が取れる」を意味し、commercially viable や economically viable の形でよく使われる。",
  "consecutive": "con-(共に)+secut(続く)から「間を空けずに続く」。業績報告で for three consecutive years（3年連続で）のように「数字＋consecutive＋期間」の形で頻出。",
  "endorse": "en-(上に)+dorse(背・裏)で、手形の裏に署名したのが原義。転じて「公に承認・支持する」や有名人が「商品を推薦する」意味になり、名詞 endorsement（推薦・支持）もよく出る。",
  "versatile": "vers(回る・向く)+-ile で「どの方向へも自在に向きを変えられる」が原義。人に対しては「多才な」、機器や素材に対しては「多用途の」という意味で製品紹介や求人広告で重宝される。",
  "amendment": "動詞 amend（修正する）の名詞形。契約書や規約の条項を改定する文脈で使われ、make an amendment to the agreement（契約の修正を行う）のように前置詞 to を伴う。",
  "exempt": "ex-(外へ)+empt(取る)で「枠外に取り出された」が原義。TOEICでは税金や手数料、参加義務の免除で be exempt from taxes のように前置詞 from を伴う形容詞として頻出。",
  "considerate": "「相手の状況をよく考える」ことから「思いやりがある」を表す。マナー案内で be considerate of other passengers と出やすく、considerable（かなりの）との混同に注意。",
  "deteriorate": "ラテン語の「より悪い」が語源。天候や経済状況の悪化で使われ、weather conditions deteriorated rapidly のように副詞 rapidly と共に自動詞で頻出。",
  "stringent": "ラテン語の「きつく縛る」が語源で「厳格な」を表す。品質基準や法規制の文脈で stringent safety regulations や stringent standards の形で頻出。",
  "explicit": "ex-(外へ)+plic(折る)で「折り目を外に開いた」→「明白な」。指示の文脈で explicit instructions（明確な指示）や explicit permission と使われ、対義語は implicit（暗黙の）。",
  "retreat": "re-(後ろへ)+treat(引く)で日常から引きこもる場所が原義。TOEICでは「退却」ではなく、company retreat（社員研修旅行・社内合宿）のように職場の親睦・研修イベントを指す。",
  "exponentially": "数学の「指数（exponent）」が語源で急増する様子を表す。事業の急成長や需要増の文脈で grow exponentially（飛躍的に成長する）や increase exponentially と動詞を修飾する。",
  "testimonial": "ラテン語 testis（証人）に由来し、製品の良さを証言する「顧客の推薦文・体験談」を指す。企業の広告や公式HPで customer testimonials（利用者の声）という見出しで頻出。",
  "deplete": "de-(減じる)+plet(満たす)で「満杯のものを空にする」が原義。予算や資源の枯渇を表し、deplete financial reserves（予備資金を使い果たす）や deplete resources の形で使われる。",
  "adverse": "ad-(向かって)+verse(向く)で「逆風のように向かってくる」が原義。悪天候の通知で adverse weather conditions、薬や政策で adverse effects（悪影響）の連語が頻出。",
  "entail": "「不可避の結果として伴う」という意味の他動詞。求人広告の職務説明でよく使われ、This position entails frequent travel（この職務には頻繁な出張が伴う）のように業務内容を述べる。",
  "intact": "in-(否定)+tact(触れる)で「誰にも触られず損なわれていない」が原義。配送通知や商品レビューで The package arrived intact（荷物が無傷で届いた）や remain intact の形でよく見られる。",
  "optimal": "ラテン語 optimus（最良）に由来し「最も適した」状態を表す。マニュアルや改善報告で achieve optimal performance（最適な性能を引き出す）や optimal results の形で頻出。",
  "vicinity": "ラテン語の「近所」が語源の名詞。ホテルやオフィスの立地案内で in the vicinity of the airport（空港の近辺に）や in the immediate vicinity（すぐ近くに）のように使われる。",
  "expedite": "ex-(外へ)+ped(足)で「足かせを外して素早く進める」のが原義。納期や手続きを早める意味で、expedite the process（処理を早める）や expedited shipping（速達配送）として頻出。",
  "deviate": "de-(離れて)+via(道)で「進路から外れる」が原義。計画や基準からずれることを表し、deviate from the plan（計画から外れる）のように前置詞 from を伴う自動詞として頻出。",
  "vigorous": "名詞 vigor（活力）の形容詞形。人だけでなく事業や宣伝活動が活発な様子を表し、conduct a vigorous marketing campaign（精力的な販促活動を行う）などの形でよく登場する。",
  "deliberation": "libra（天秤）で重さを慎重に量ることが原義。「熟慮・審議」を意味し、after careful deliberation（慎重な審議の末に）という決まり文句で役員会や選考の通知に頻出。",
  "objectionable": "動詞 object（反対する）から派生し「異議を唱えたくなるほど好ましくない」を表す。苦情対応などで objectionable odors（不快な臭気）や objectionable behavior の形で使われる。",
  "redeemable": "動詞 redeem（買い戻す・換金する）+-able。ポイントやクーポンの利用規約で redeemable for merchandise（商品と交換可能）のように前置詞 for と結びつく。",
  "inaugural": "動詞 inaugurate（新しく始める・就任させる）の形容詞形。記念すべき第1回目を指し、inaugural flight（初就航便）や the inaugural issue（創刊号）の形で頻出。",
  "donor": "動詞 donate（寄付する）と同語源で「贈り与える人」。慈善団体や文化施設への支援者を表し、generous corporate donors（寛大な法人寄付者）や thank the donors の形で頻出。",
  "downstairs": "down（下へ）+stairs（階段）で、主に副詞として「階下へ・下の階で」を表す。オフィス内の会話で go downstairs（下の階に行く）や the downstairs conference room と自然に使われる。",
  "draw": "「絵を描く」以外に「引っ張って引き寄せる」という意味が重要。イベント告知や宣伝で draw a large crowd（大勢の観客を引きつける）や draw attention（注目を集める）の形で頻出する。",
  "duplication": "duo（2つ）+plic(折る)で「二重にすること」。業務改善や組織再編の文脈で、avoid unnecessary duplication of effort（無駄な労力の重複を避ける）という定型フレーズでよく問われる。",
  "easily": "形容詞 easy に副詞語尾 -ly がついた形。TOEICでは easily accessible（容易に行ける）のように、-able/-ible で終わる形容詞を修飾するパターンで頻出。",
  "easy": "「容易な」の意で、施設案内や製品マニュアルで easy to assemble（簡単に組み立てられる）や provide easy access to...（〜へ行きやすい）の形でよく使われる。",
  "economical": "eco-(家)+nom(管理)が原義。学問や社会全体の経済を表す economic と異なり、economical は「安上がりな・無駄のない」を表し、economical choice（経済的な選択）などと使われる。",
  "edit": "ラテン語 edere（外へ出す・出版する）に由来。社内報や報告書の作成文脈で edit a newsletter（社内報を編集する）や edit the draft（原稿を編集する）の形でよく使われる。",
  "editor": "edit に人を表す -or がついた語。雑誌や出版社の文脈で editor in chief（編集長）などの肩書で出るほか、Part 7 の読者投稿欄 Letter to the Editor でもおなじみ。",
  "editorial": "名詞「社説」と形容詞「編集の」の両方で使われる。名詞の write an editorial（社説を書く）のほか、形容詞として editorial staff（編集部員）や editorial board（編集委員会）と頻出。",
  "effect": "ex-(外へ)+fact(作る)が語源の名詞「効果・影響」。動詞 affect との混同に注意。have a positive effect on...（〜に好影響を及ぼす）や take effect（発効する）の連語が頻出。",
  "effective": "「効果的な」の意味に加え、TOEICでは人事異動や方針変更の告知で be effective immediately（即日発効する）や effective from [日付]（〜から有効）の形で頻出。",
  "efficiency": "ex-(外へ)+fic(作る)が語源。無駄なく成果を生む能力を表す。業務改善の文脈で improve operational efficiency（業務効率を改善する）や energy efficiency（省エネ性）の形で頻出。",
  "emerge": "e-(外へ)+merge(潜る)で、水底から浮かび出るのが原義。ビジネス文脈で emerge as a market leader（市場の主導的企業として台頭する）のように emerge as... の形で頻出。",
  "employ": "em-(中へ)+ploy(巻き込む)が語源。「雇う」の意味で employ qualified staff と出るほか、「用いる」の意味で employ a new method（新しい手法を採用する）の使い方も問われる。",
  "encouragement": "en-(〜にする)+courage(勇気)+-ment で「勇気を与えること」。スピーチやメールで offer words of encouragement（激励の言葉を贈る）というコロケーションでよく登場する。",
  "energy": "en-(中に)+erg(働く)が語源。TOEICでは環境対策やコスト削減のトピックで renewable energy（再生可能エネルギー）や energy-efficient（省エネの）という複合語で頻出。",
  "enforcement": "en-(〜にする)+force(力)+-ment で規則に効力を持たせること。コンプライアンスや安全管理の文脈で strict enforcement of regulations（規則の厳格な施行）の形で頻出。",
  "engaged": "en-(中に)+gage(約束)が語源。be engaged in...（〜に携わっている）のほか、形容詞として keep customers engaged（顧客の関心を引きつけ続ける）のように使われる。",
  "engineer": "engine（工夫・機関）と同語源で、工夫して設計する人を指す。TOEICでは civil engineer（土木技術者）などの専門職名として頻出するほか、動詞で「設計する」という意味もある。",
  "enhancement": "en-(強意)+hance(高くする)に由来し、価値や性能を一段と引き上げること。製品やITシステムの改善告知で feature enhancements（機能拡張）や security enhancement の形で頻出。",
  "enjoy": "en-(〜にする)+joy(喜び)。ホテルの挨拶 Please enjoy your stay のほか、ビジネス文脈で enjoy a good reputation（定評を享受している）のように利益を享受する意味でも出る。",
  "enter": "物理的参入（enter a new market）では他動詞だが、「契約・提携を結ぶ」という文脈では enter into an agreement/contract のように前置詞 into を伴う用法に注意。",
  "enterprise": "enter-(間に)+prise(つかむ)が語源で、冒険的事業や企業を指す。TOEICでは small and medium-sized enterprises（中小企業）や joint enterprise（共同事業）の形で登場する。",
  "enthusiasm": "en-(中に)+theos(神)が語源で、内から湧き出る強い情熱を表す。社員の推薦状や採用面接の描写で show enthusiasm for...（〜に対して強い意欲を示す）と前置詞 for を伴って頻出。",
  "entry": "enter の名詞形。「入場」の free entry のほか、コンテストの告知で submit an entry（応募作品を提出する）や entry deadline（応募締切）のように「応募・登録」の意味で頻出。",
  "envelop": "en-(中に)+velop(包む)が語源の動詞。名詞の envelope（封筒：末尾にeがつく）との混同に注意。霧や煙が建物を覆う描写で Thick fog enveloped the terminal のように使われる。",
  "environmental": "environment（環境）の形容詞形。企業の報告書や工事告知で environmental impact（環境への影響）や comply with environmental regulations（環境規制を遵守する）の形で頻出。",
  "equal": "ラテン語 aequus（平らな・等しい）が語源。人事・採用告知の末尾に記載される equal opportunity employer（雇用均等企業）のフレーズや、be equal to...（〜に匹敵する）の形で頻出。",
  "essence": "ラテン語 esse（存在する）が語源で、物事の根本的な核を指す。要約文で使われる接続表現 in essence（本質的には・要するに）や、the true essence of...（〜の真の本質）の形で頻出。",
  "established": "establish（確立する）の過去分詞形容詞。「定評のある・実績のある」の意味で、an established company（定評ある企業）や established reputation（確立された評判）の形で頻出。",
  "establishment": "「設立」という意味に加え、TOEICでは店舗や施設そのものを指す名詞として頻出。dining establishment（飲食店）や a local business establishment（地域の事業所）の形で使われる。",
  "evaluation": "e-(外へ)+value(価値)+-ation で価値を外から見極めること。人事・社内評価の文脈で performance evaluation（業績評価）や conduct an annual evaluation の形で頻出。",
  "exact": "ex-(外へ)+act(導き出す)が語源で、寸分たがわず精密なことを表す。日時の再確認で exact date and time（正確な日時）や、配送確認で exact location（正確な場所）の形で頻出。",
  "examination": "ex-(外へ)+語根(量る)から細かく調べること。undergo a medical examination（健康診断を受ける）や under examination（調査中）の形で頻出。",
  "excellent": "ex-(外へ)+cellere(突き出る)で「他より抜きん出ている」が原義。in excellent condition（極めて良好な状態で）や excellent service の形で頻出。",
  "exception": "ex-(外へ)+cept(取る)で「外に取り出されたもの」が原義。make an exception to...（〜に例外を認める）や with the exception of...（〜を除いて）の形で頻出。",
  "excess": "ex-(外へ)+cess(行く)で限度を越えること。excess inventory（余剰在庫）や excess baggage（超過手荷物）、in excess of...（〜を超えて）の形で頻出。",
  "excessive": "excess（過剰）の形容詞形。「度を越して多すぎる」という否定的ニュアンスで、excessive noise（過度の騒音）や excessive spending（過剰な支出）と使われる。",
  "exchange": "ex-(外へ)+change(変える)で取り替えること。exchange A for B（AをBと交換する）の前置詞 for や、in exchange for...（〜と引き換えに）の形で頻出。",
  "exclude": "ex-(外へ)+clude(閉じる)で外に締め出すこと。exclude A from B（AをBから除外する）の前置詞 from や、excluding tax（税抜き）の形でよく出る。",
  "exercise": "「運動」以外に「権限を行使する」「注意を払う」という意味がある。TOEICでは exercise caution（警戒・注意する）というコロケーションが頻出。",
  "exhaust": "ex-(外へ)+haust(汲み出す)で「使い尽くす」が原義。exhaust all options（あらゆる選択肢を尽くす）や、形容詞 exhausted（疲れ切った）でよく使われる。",
  "exist": "ex-(外へ)+sistere(立つ)が原義。完全自動詞のため受動態にならず、TOEICでは形容詞用法の existing facilities（既存の施設）などの形も頻出。",
  "exit": "ex-(外へ)+it(行く)で「外へ出ること」。館内放送などの emergency exit（非常口）や、道案内での take Exit 5（5番出口で降りる）の形でよく出る。",
  "expectancy": "ex-(外へ)+spect(見る)から派生。単なる期待（expectation）と区別し、life expectancy（機器の耐用年数・平均寿命）という複合名詞で頻出。",
  "expensive": "ex-(外へ)+pens(支払う)から「支出が大きい」こと。less expensive（より安価な）や inexpensive（手頃な価格の）など比較・派生語と共によく出る。",
  "expert": "ex-(外へ)+periri(試す)で「経験豊かな人」が原義。an expert in...（〜の専門家）の前置詞や、名詞 expertise（専門知識）との品詞の区別が頻出。",
  "expiration": "ex-(外へ)+spir(息をする)で息を吐き切り終わること。expiration date（有効期限・契約満了日）の形で、契約更新やカードの案内文脈で頻出。",
  "explanation": "ex-(外へ)+plan(平らな)で「平らにして解き明かす」こと。provide a detailed explanation of...（〜の詳細な説明をする）の形でよく使われる。",
  "export": "ex-(外へ)+port(運ぶ)で国外へ運び出すこと。export goods to...（〜へ商品を輸出する）や export market（輸出市場）の形で貿易文脈に頻出。",
  "exposed": "ex-(外へ)+pose(置く)で「むき出しの」が原義。be exposed to sunlight（日光にさらされる）や、機密書類を露出させない安全管理の文脈でよく出る。",
  "expression": "ex-(外へ)+press(押す)で感情を外に表すこと。as an expression of our appreciation（感謝のしるしとして）の定型句でお礼状などに頻出。",
  "exterior": "ラテン語で「外側の」を意味し、interior の対義語。建物の改装や点検の文脈で、exterior renovation（外装改修）や exterior walls（外壁）の形で頻出。",
  "extreme": "ex-(外へ)の最上級に由来し「極度の」を表す。extreme weather（異常気象）による遅延や、with extreme caution（細心の注意を払って）の形で頻出。",
  "face": "名詞「顔」から「正面から立ち向かう」動詞になった。他動詞で face challenges（課題に直面する）と直接目的語を取るほか、be faced with... の形も頻出。",
  "factor": "fact(作る)+-or(もの)で結果を生む要素のこと。a key factor in...（〜の重要要因）という名詞のほか、factor in...（〜を考慮に入れる）の動詞句も頻出。",
  "fair": "形容詞では at a fair price（適正価格で）など「妥当な」の意味で頻出。名詞では job fair（合同就職説明会）や trade fair（見本市）の形でよく使われる。",
  "famous": "fame(名声)+-ous(満ちた)が原義。be famous for...（〜で有名である）の前置詞 for とのセットが定番で、renowned や well-known の同義語。",
  "fault": "fail(失敗する)と同語源で手落ちや過失を指す。It is not our fault.（弊社の責任ではありません）のように、トラブル対応メールで責任の所在を示す文脈で頻出。",
  "favor": "ラテン語で「支持する」が原義。vote in favor of the plan（計画に賛成票を投じる）のように、in favor of...（〜に賛成して）の決まり文句が議決場面で頻出。",
  "favorable": "favor(好意)+-able(〜できる)で好意的なこと。favorable reviews（好評）や favorable market conditions（好都合な市況）の形で頻出。",
  "favorite": "favor(好意)から派生し愛着を表す。店舗やホテルのレビューで a local favorite（地元で人気・愛される店）や favorite destination の形でよく出る。",
  "fertilize": "fertile(肥沃な)+-ize(〜にする)で土を豊かにすること。造園（landscaping）の文脈で fertilize the lawn（芝生に肥料をやる）や名詞 fertilizer で頻出。",
  "final": "ラテン語 finis（終わり）が語源。final decision（最終決定）や final approval（最終承認）のように決定・承認を表す名詞を修飾する形で頻出。",
  "finally": "final に副詞語尾 -ly が付いた語。難航した交渉の末に finally reach an agreement や finally complete のように動詞を修飾して登場する。",
  "finance": "中世ラテン語の「決算」が語源。名詞で the finance department（財務部門）や corporate finances、動詞「〜に資金を調達する」の用法も問われる。",
  "fineable": "fine（罰金）に -able（〜できる）が付いた語。駐車違反や構内規則の警告文で a fineable offense（罰金対象の違反行為）というコロケーションで目にする。",
  "fit": "物理的に収まる（fit into...）だけでなく、fit the requirements（要件を満たす）や fit one's needs（要望に合う）のように基準に合致する意味で多用される。",
  "flat": "「平らな」から転じて、金額や料金に変動がないことを示す a flat rate（一律料金）や a flat fee（定額手数料）が頻出表現。出張トラブルでパンク（a flat tire）も出る。",
  "flexibility": "flex（曲げる）+-ibility で「柔軟性」。人事の文脈で offer greater flexibility in work schedules（勤務体系に柔軟性を持たせる）の形でよく出題される。",
  "flight": "動詞 fly（飛ぶ）の名詞形。空港アナウンスや旅程表（itinerary）で、connecting flight（乗り継ぎ便）や flight cancellation（欠航）などの重要表現として扱われる。",
  "fluency": "flu-（流れる）+-ency で言葉が淀みないこと。求人票の応募要件で fluency in English（流暢な英語力）のように言語名とともに必須スキルとして提示される。",
  "fluently": "形容詞 fluent（流暢な）の副詞形。speak English fluently（英語を流暢に話す）のように動詞を修飾する。Part 5 の品詞問題で形容詞 fluent との識別が問われやすい。",
  "flyer": "手から手へ飛ぶように配られる紙片が原義（flierとも綴る）。宣伝や開店告知で distribute promotional flyers（販促チラシを配る）の表現で頻繁に使われる。",
  "focus": "熱が集まる「火床」が原義。前置詞 on との結びつきが極めて強く、focus on customer satisfaction（顧客満足に焦点を当てる）の形で頻出する。",
  "follow": "「指示や手順に従う」の意で頻出。follow safety guidelines（安全指針に従う）や follow instructions（指示に従う）のように規則類を目的語に取る。",
  "for": "目的や対象を表す前置詞。prepare for（〜の準備をする）や apply for（〜に応募する）など、特定の動詞とセットでPart 5の空所補充問題によく出題される。",
  "formal": "form（形式）+-al で「正式な」。式典案内で formal attire（正装）とドレスコードが指定されたり、formal complaint（正式な苦情）の形で登場する。",
  "fortunately": "文頭でコンマを伴い「幸運にも」と好転を伝える。配送遅延の懸念後に Fortunately, the shipment arrived on time. と続くメール文が典型的。",
  "frequency": "形容詞 frequent（頻繁な）の名詞形。運行間隔を表す文脈で、increase the frequency of shuttle services（運行本数を増やす）の表現で目にする。",
  "functional": "function（機能）+-al。機器や施設が正常に動く状態を表し、改装案内などで fully functional（完全に機能する）と副詞 fully を伴う組み合わせが目立つ。",
  "general": "「全体に関わる」が原義。役職の general manager（総支配人）や、問い合わせの general inquiries（一般的な質問）、for general use などで広く使われる。",
  "generously": "generous（寛大な）の副詞形。チャリティーや基金集めで donate generously to the community fund（地域基金に惜しみなく寄付する）の形でよく見られる。",
  "govern": "「導き統治する」が原義。国の統治だけでなく、rules that govern workplace conduct（職場での行動を律する規則）のように社内規定の文脈でよく使われる。",
  "government": "govern（統治する）+-ment。government regulations（政府の規制）や government grant（政府助成金）など、公的機関との関わりを示す複合名詞で頻出。",
  "graduate": "ラテン語 gradus（段階）が語源。動詞では graduate from college のように前置詞 from を伴う自動詞になる。名詞「大卒者（graduate）」の用法も重要。",
  "graduation": "動詞 graduate の名詞形。採用条件や略歴の文脈で upon college graduation（大学卒業時に・卒業後すぐに）や graduation ceremony（卒業式）の表現で頻繁に用いられる。",
  "grow": "自動詞「成長する」と他動詞「〜を拡大する」の両用。grow rapidly in overseas markets（海外で急成長する）や grow revenue（増収を図る）が頻出。",
  "growth": "grow の名詞形。財務報告や事業計画で rapid growth（急成長）や robust growth（堅調な成長）、sales growth（売上増）などの表現が定着している。",
  "guaranty": "guarantee と同根で、商業文書で「保証」を指す。a money-back guaranty（返金保証）や a satisfaction guaranty（満足保証）の形でよく見られる。",
  "guest": "式典や宿泊の文脈で必須。guest speaker（特別講演者）や guest room（客室）、a guest list for the banquet（招待客名簿）などの複合名詞で押さえたい。",
  "guide": "動詞「案内する」と名詞「案内書」の両用。見学ツアーで guide visitors through the plant（工場内で来客を案内する）のように前置詞 through を伴う型を押さえたい。",
  "guideline": "guide（案内）+line（線）で「行動の指針」。TOEICでは複数形 guidelines が一般的で、follow safety guidelines（安全指針に従う）の組み合わせが代表的。",
  "hall": "banquet hall（宴会場）や town hall meeting（全社集会）のように社内案内で出ます。廊下を意味する hallway との関連で覚えるのも効果的です。",
  "hand": "名詞の by hand（手渡しで）や in hand（手元にあって）に加え、句動詞 hand in（提出する＝submit）や hand out（配布する）の重要表現を押さえましょう。",
  "help": "help + 人 + (to) do（人が〜するのを支援する）と help with + 名詞が頻出語法です。目的語のあとに原形不定詞を続ける形が文法問題で狙われます。",
  "helpful": "help（助け）+-ful（満ちた）で「役に立つ」。helpful advice や helpful staff の形で、アンケートやレビューの肯定的な評価表現として頻出です。",
  "hesitancy": "動詞 hesitate（ためらう）の名詞形。without hesitancy（ためらいなく）の形で出やすく、形容詞 hesitant（be hesitant to do）との品詞区別が重要です。",
  "high": "high standards（高水準）や high priority（最優先）が定番。副詞 highly（大いに）は highly recommended などの形で使われ、品詞識別問題で狙われます。",
  "historical": "historic（歴史上重大な）と異なり、historical は「歴史に関する・過去の」を意味します。historical data（過去のデータ・推移）などの形でよく登場します。",
  "history": "a long history of 〜（〜の長い歴史・実績）として会社概要に出るほか、履歴書文脈の employment history（職歴）などビジネス記録を表す名詞です。",
  "honorable": "honor（名誉）+-able（値する）で「名誉ある」。コンテストや表彰通知で見られる honorable mention（選外佳作・名誉賞）のコロケーションが頻出です。",
  "host": "hospitality（もてなし）と同語根。動詞では host a conference（会議を主催する）や host an event が定番で、催し物告知や招待状に頻出します。",
  "idealism": "ideal（理想）+-ism（主義）で「理想主義」。収益性（profitability）や実務的アプローチとの対比として corporate idealism（企業の理想主義）のように使われます。",
  "idealist": "接尾辞 -ist（人）がつき「理想主義者」。実利重視の realist（現実主義者）との対比や人物評で登場します。抽象名詞 idealism との語尾の区別に注意。",
  "illegal": "il-（not）+legal（合法の）で「違法な」。illegal distribution（不正流通）や illegal parking（駐車違反）など、社内規定やコンプライアンスの文脈で用いられます。",
  "illustration": "il-（中に）+lustrare（照らす）が語源。図解だけでなく、by way of illustration（例証として）のように「具体例」を表す用法も TOEIC では重要です。",
  "immediate": "im-（無）+mediate（仲介）で「間に何も置かない」が原義。immediate supervisor（直属の上司）や require immediate attention（至急対応を要する）が頻出です。",
  "impact": "have an impact on 〜（〜に影響を与える）の形で前置詞 on とセットで使われます。have an effect on や influence と同義の表現として整理しましょう。",
  "implementation": "動詞 implement（実行する）の名詞形。the implementation of the new policy（新方針の導入・実施）のように、計画を実行に移す文脈で頻出します。",
  "implications": "im-（中に）+plicare（折る）で「内に含むもの」。通例複数形で将来の「影響・結果」を表し、financial implications（財務的影響）などの形で現れます。",
  "impossible": "im-（not）+possible（可能）で「不可能な」。It is impossible to do の構文や、virtually impossible（事実上不可能）のように副詞で修飾される形が頻出です。",
  "impression": "im-（上に）+press（押す）で「心に押された刻印」。make a positive first impression（良い第一印象を与える）や under the impression that（〜と思い込んで）が頻出です。",
  "impressive": "impress（感銘を与える）+-ive で「目覚ましい」。impressive sales growth（目覚ましい売上増）のように成果を修飾し、感情を受ける人（impressed）との区別が重要です。",
  "improvement": "動詞 improve の名詞形。show continuous improvement（継続的改善を示す）や room for improvement（改善の余地）のコロケーションが頻出します。",
  "include": "in-（中に）+clude（閉じる）で「囲い込む→含む」。他動詞なので前置詞なしで直接目的語を取り、The price includes shipping.（送料込み）のように案内文の定番です。",
  "including": "include の分詞から生じた前置詞扱いの語で「〜を含めて」。all fees including tax（税込の全料金）のように例示で使われます。対義語 excluding（〜を除いて）と対比しましょう。",
  "indication": "動詞 indicate（示す）の名詞形。give a clear indication of 〜（〜の明確な兆候を示す）や there is every indication that 〜（十分な兆候がある）の形で出ます。",
  "industrial": "industrial park（工業団地）のように「産業・工業の」を表します。つづりが似ている industrious（勤勉な＝hardworking）との意味の区別が Part 5 で狙われます。",
  "industry": "the automobile industry（自動車業界）のように特定分野を表すほか、industry leader（業界大手）や industry standards（業界標準）などの複合名詞が頻出です。",
  "information": "代表的な不可算名詞で、an をつけたり複数形 -s にはできません。for further information（詳細情報については）や、数える際の a piece of information が頻出です。",
  "innovate": "in-（中に）+novus（新しい）で「新しい風を吹き込む」。renovate（改装する）と同語根です。innovate continuously（絶えず革新する）のように企業方針の文脈で登場します。",
  "innovation": "動詞 innovate（革新する）の名詞形。foster innovation（革新を促す）や technological innovation（技術革新）が頻出。形容詞 innovative（革新的な）との品詞区別も重要です。",
  "inspection": "in-（中に）+spect（見る）で「中をじっくり覗き込む」が原義。conduct an inspection（点検を実施する）や pass an inspection（検査に合格する）のコロケーションが頻出です。",
  "instruct": "in-（中に）+struct（建てる）で「知識を心の中に築く」。instruct A to do（Aに〜するよう指示する）の構文が頻出で、空欄後ろの to 不定詞と結びつく語法が狙われます。",
  "instructor": "instruct（指導する）+-or（人）で「指導員・講師」。certified instructor（公認講師）のように研修の告知でよく登場し、抽象名詞 instruction（指導・説明書）との品詞区別に注意。",
  "insufficient": "in-（否定）+sufficient（十分な）で「不十分な」。insufficient funds（残高不足）や insufficient time（時間不足）のように、原因を表す due to とセットで頻出します。",
  "insure": "in-（強意）+sure（確実にする）から派生。insure cargo against loss（貨物の紛失に保険をかける）のように用いられます。ensure（確実にする）や assure（保証する）との混同に注意。",
  "integrate": "「完全な（integer）」から「全体としてまとめる」が原義。integrate A into B（AをBに統合する・組み込む）の形が定番で、新システムの導入や組織統合の文脈で登場します。",
  "intend": "in-（向けて）+tend（伸ばす）で「心を向ける」。intend to do（〜するつもりである）や be intended for 〜（〜向けに作られている）の形でよく使われ、名詞形は intention です。",
  "interaction": "inter-（相互に）+action（作用・行動）で「相互作用・交流」。interaction with clients（顧客との対話）のように前置詞 with を伴い、接客や社内連携の場面で出ます。",
  "intersect": "inter-（相互に）+sect（切る）で「互いに横切る」。道案内で道路同士が交差する場面（where the streets intersect）に使われ、名詞 intersection（交差点）も頻出です。",
  "introduce": "intro-（内へ）+duce（導く）で「中に引き入れる」。人を紹介するだけでなく、TOEICでは introduce a new policy（新方針を導入する）のように制度や製品の「導入」で多用されます。",
  "introduction": "動詞 introduce の名詞形。with the introduction of new software（新ソフトの導入に伴い）のように使われます。人への紹介状（letter of introduction）の意味も押さえましょう。",
  "investment": "動詞 invest（投資する）の名詞形。attract foreign investment（海外投資を誘致する）や return on investment（投資利益率：ROI）のコロケーションが頻出です。",
  "invitation": "動詞 invite の名詞形。invitation to the ceremony（式典への招待）のように前置詞 to を取ります。extend an invitation to 〜（〜に招待状を差し出す）の表現も頻出です。",
  "invitee": "動詞 invite に受動の接尾辞 -ee（〜される人）がついた語で「招待客」。employee（従業員）や attendee（出席者）と同様の語尾パターンとして整理しておきましょう。",
  "involve": "in-（中に）+volve（巻く）で「中に巻き込む」。動名詞を目的語に取る（involve doing）ほか、be involved in the project（事業に携わっている）の受動態が頻出です。",
  "journalist": "journal（日々の記録）+-ist（人）で「報道記者」。press conference（記者会見）で address questions from journalists（記者からの質問に答える）などの形で登場します。",
  "junior": "ラテン語の「より若い」が語源。junior staff（若手社員）のように職位の低さを表し、比較対象を置く際は than ではなく junior to 〜（〜より後輩の・地位が下の）と to を用います。",
  "land": "「着陸する」だけでなく、ビジネスでは land a contract（契約を獲得する）や land a job（仕事を得る）のように「確保する（＝secure）」という意味で使われる点に注目です。",
  "late": "late fee（延滞料）や late response（遅れた返答）の形で頻出。副詞 lately は「最近（＝recently）」という意味になり、late（遅く）との品詞・意味の違いが Part 5 で狙われます。",
  "lawyer": "law（法律）+-yer（人）で「法律の専門家」。consult a lawyer（弁護士に相談する）や corporate lawyer（企業弁護士）の形で出ます。同義語の attorney と合わせて覚えましょう。",
  "lecture": "ラテン語の「読むこと」が語源。give [deliver] a lecture（講義・講演を行う）や attend a lecture（講演を聴く）のように、組み合わせる動詞と一緒に覚えるのが効果的です。",
  "legal": "ラテン語 lex（法律）に由来。legal advice（法的助言）や take legal action（法的措置を取る）など契約・紛争の文脈で頻出します。反対語 illegal（違法な）との対比も重要です。",
  "lend": "lend A B [lend B to A] で「AにBを貸す」。borrow（借りる）との主客の混同に注意しましょう。資金や支援を提供する文脈で lend support to 〜 の形でもよく出ます。",
  "liability": "liable（法的責任がある）の名詞形。assume liability for 〜（〜の損害賠償責任を負う）の形で契約書に頻出。会計文脈では複数形 liabilities で「負債（資産 assets の対義語）」です。",
  "like": "動詞では would like to do（〜したい）や would like you to do（あなたに〜してほしい）の形で、ビジネスメールや会話（Part 3）の丁寧な依頼・要望表現として最頻出です。",
  "limit": "ラテン語の「境界（limes）」が語源。limit A to B（AをBに制限する）の語法が重要で、limit parking to two hours（駐車を2時間に制限する）のように前置詞 to と結びつきます。",
  "limited": "動詞 limit の形容詞用法。for a limited time only（期間限定で）や limited warranty（限定保証）など、販促キャンペーンや製品説明（Part 7）に頻出します。",
  "local": "locus（場所）+-al で「その土地の」。local business（地元企業）や local residents（地域住民）の形で、地域貢献や店舗移転などの案内文に頻出します。",
  "locate": "locus（場所）に由来。be conveniently located near 〜（〜の近くに便利に位置する）の受動態が定番。「〜の場所を突き止める（locate the file）」という能動態用法も出ます。",
  "low": "at low cost（低コストで）や low turnover rate（低い離職率）のように数値を修飾します。record low（過去最低水準）のように名詞としても経済記事で頻出です。",
  "lunch": "business lunch や lunch break の形でリスニングの会話やアナウンスに頻出。catered lunch（ケータリングの昼食）など社内イベントの予定表でもよく見かける。",
  "machine": "個々の機械を指す可算名詞（a machine / machines）。copy machine（コピー機）や vending machine のほか、out of order（故障中）の対象として頻出。",
  "machinery": "machine に集合名詞をつくる -ery がついた不可算名詞で、冠詞 a や複数形 -s は付かない。heavy machinery（重機）など工場の文脈でよく使われる。",
  "mail": "名詞の mail（郵便物）は集合的で不可算名詞のため a や複数形の -s は付かない。動詞としては mail a package（小包を郵送する）のように使われる。",
  "main": "古英語の「力」に由来し「最も主要な」を表す。名詞の前でのみ使う限定用法が基本で、main office（本社）や main entrance（正面玄関）の形でよく出る。",
  "mainly": "main（主要な）＋副詞語尾 -ly。パート3・4・7の設問文で \"What is the talk mainly about?\"（主に何についてか）という主旨把握の定番として頻出。",
  "manage": "ラテン語 manus（手）に由来し、馬を手綱で操ることから「うまく扱う・管理する」。manage to do（何とか〜やり遂げる）の構文や管理業務の文脈で頻出。",
  "management": "manage に名詞語尾 -ment。単に「管理」だけでなく、「経営陣・幹部」という人を指す集合名詞としても使われ、senior management（上層部）などの形で出る。",
  "mandate": "man-(手)+date(与える)で「手に託す」→「命令・権限」。名詞で government mandate（政府の義務付け）、動詞で mandate that節（義務付ける）の形で出やすい。",
  "manufacture": "manu-(手)+fact(作る)が原義で「大量に製造する」。TOEICでは manufacturer（製造業者）や manufacturing plant（製造工場）などの関連語も併せて頻出。",
  "maximize": "ラテン語 maximus（最大の）＋動詞化語尾 -ize。対義語は minimize。maximize profits（利益を最大化する）や maximize efficiency の形でよく使われる。",
  "mechanic": "-ic で終わるが形容詞ではなく「整備士」を表す可算の人名詞。certified mechanic（認定整備士）のように修飾され、車両や設備の点検・修理の場面でよく出る。",
  "medicine": "ラテン語の「治療」に由来。「薬を飲む」は drink ではなく take medicine と表現するのが最重要ポイント。prescription medicine（処方薬）も頻出。",
  "meeting": "hold a meeting（会議を開く）や postpone a meeting（延期する）など動詞とのコロケーションが豊富。agenda（協議事項）や minutes（議事録）とセットで出やすい。",
  "member": "ラテン語の「体の一部」から「組織の構成員」。board member（取締役）や staff member のほか、member discount（会員割引）など店舗やサービスの通知で頻出。",
  "merchant": "merchandise（商品）や commerce（商業）と同根で「商人・業者」。local merchant（地元の小売店主）や online merchant（ネット通販業者）などの形で出やすい。",
  "merge": "ラテン語の「浸る・溶け合う」から「合併する」。自動詞で merge with 〜（〜と合併する）と前置詞 with を取る形や、名詞 merger（合併）の形で企業再編の話題に頻出。",
  "method": "meta-(沿って)+hodos(道)で「目的に向かう筋道」。payment method（支払い方法）や shipping method（配送方法）など、手続きや取引の選択肢で頻出。",
  "minimum": "ラテン語の「最も小さい」から「最小限」。keep ... to a minimum（〜を最小限に抑える）の成句が頻出。形容詞の minimum requirement（最低要件）も重要。",
  "mislead": "mis-(誤って)+lead(導く)で「誤解させる」。過去形・過去分詞は misled。misleading advertising（誇大・誤解を招く広告）など形容詞用法も重要。",
  "misplacement": "mis-(誤って)+place(置く)+-ment で「置き忘れ・紛失」。prevent the misplacement of files（書類の紛失を防ぐ）などオフィスの整理や保管ルールの文脈で使われる。",
  "moderately": "「尺度・節度」を表す語根から派生。TOEICでは moderately priced（手頃な価格の・適度な値段の）というコロケーションで、ホテルや店舗の広告・レビューに頻出。",
  "modern": "ラテン語 modo（今まさに）に由来し「現代の・最新の」。modern facility（最新の設備）や modern equipment の形で、オフィスの改修やホテル案内の文脈でよく出る。",
  "monitor": "ラテン語 monere（警告する）から「見張る・監視する」。名詞の画面だけでなく、動詞として monitor progress（進捗をチェックする）のように業務管理の文脈で頻出。",
  "most": "最上級だけでなく「大部分」を表す代名詞・限定詞。most of the + 複数名詞/不可算名詞（〜の大部分）と、単独で名詞を直接修飾する most people の区別が文法問題で問われやすい。",
  "motivated": "人を修飾して「意欲的な・やる気がある」。求人票や人事の文脈で highly motivated candidates（非常に意欲的な応募者）のように副詞 highly とセットで頻出。",
  "motivation": "ラテン語 movere（動かす）由来。「動機づけ・やる気」。boost employee motivation（従業員のやる気を高める）のように人事管理や研修の文脈で動詞 boost と共起しやすい。",
  "nation": "ラテン語の「生まれる」から「国・国家」。across the nation（全国にわたって）や nationwide（全国規模の）の形で、店舗展開や市場調査の文脈で頻出。",
  "native": "「生まれる」に由来し「生まれ故郷の・母国の」。native English speaker（英語の母語話者）のほか、be native to 〜（〜に固有・原産である）の語法でも使われる。",
  "necessary": "ne-(ない)+cedere(退く)で「避けられない」→「不可欠な」。take necessary steps / measures（必要な措置をとる）のコロケーションや if necessary（必要であれば）が頻出。",
  "necessity": "necessaryの名詞形。「necessity of 〜（〜の必要性）」や、副詞句の「out of necessity（必要に迫られて）」の形でよく使われる。",
  "negative": "neg-(否定)が語源。TOEICでは「negative feedback（批判的な意見）」や「negative impact（悪影響）」のコロケーションで登場しやすい。",
  "neighbor": "neigh(近く)+bor(住人)が語源。TOEICでは派生語のneighborhood（近所・地域）やneighboring（隣接する）との品詞の区別が問われやすい。",
  "noisy": "名詞noiseに形容詞語尾-yがついた形。オフィスの移転や苦情の文脈で「noisy equipment（騒音を出す機器）」などの修飾語として使われる。",
  "nomination": "nomin-(名前)が語源で名前を挙げること。「submit a nomination for 〜（〜への推薦を提出する）」など社内表彰の文脈で頻出する。",
  "nominee": "指名される側を表す受動の接尾辞-eeがつき「指名された人（候補者）」を指す。推薦する人を表すnominatorとの混同に注意したい。",
  "observation": "observeの名詞形。観察の意味ではobservationだが、規則などの「遵守」を表す場合はobservanceになるという品詞・語義の区別がポイント。",
  "observer": "observe(観察する)+-er(人)。会議や視察の文脈で「attend as an observer（オブザーバーとして参加する）」の形で使われやすい。",
  "occasional": "名詞occasion（特定の機会）の形容詞形。「occasional delays（時折の遅延）」のように、天候や交通機関の案内文で名詞を修飾して使われる。",
  "occupy": "oc-(手前に)+cup(つかむ)が語源。場所を「占める」だけでなく、「be occupied with 〜（〜で忙しい）」という熟語でもよく問われる。",
  "official": "「公式の」という形容詞だけでなく、「company officials（会社幹部）」や「city officials」のように「役人・関係者」を指す名詞としても頻出。",
  "open": "動詞「開く」のほか、「be open to the public（一般公開されている）」のように形容詞として使われる文脈がパート7などで非常に多い。",
  "opening": "店の開店（grand opening）のほか、TOEICでは「job opening（仕事の空き・求人）」の意味でvacancyの同義語として頻出する。",
  "operate": "oper-(働く)が語源。機械を「操作する」だけでなく、事業や店舗を「運営する・営業する」という意味でもビジネス文脈で幅広く使われる。",
  "operation": "「hours of operation（営業時間）」や「put into operation（稼働させる）」はTOEICの頻出表現。単なる機械操作を超えた「事業運営」の意味も重要。",
  "opposition": "op-(反対に)+posit(置く)が語源。「face strong opposition to 〜（〜への強い反対に直面する）」のように前置詞toを伴う形が狙われやすい。",
  "organization": "organizeの名詞形。TOEICでは「non-profit organization（NPO・非営利団体）」や「charitable organization」などの組み合わせが頻出。",
  "organize": "イベントや会議を「企画・主催する」文脈でorganize a conferenceなどの形で多用される。書類やデスクを「整理整頓する」意味も押さえたい。",
  "orientation": "orient(方向を合わせる)が語源。「new employee orientation（新入社員向け説明会）」という研修・人事の文脈で頻出のキーワード。",
  "originality": "origin(起源)から生じた形容詞originalに-ityがついた名詞。広告や企画の講評で「praise A for its originality（独創性を称賛する）」の形で出る。",
  "out": "不在を告げる「out of the office」や、品切れを表す「out of stock」のように、前置詞句の一部としてリスニングやメール文で頻出する。",
  "out-of-date": "日付(date)の外(out)にあることから「時代遅れの・期限切れの」。同義語のoutdatedや、対義語のup-to-dateと対比して覚えると効果的。",
  "outdate": "動詞としては「時代遅れにする」だが、TOEICでは過去分詞から派生した形容詞outdated（時代遅れの、旧式の）の形で問われることが多い。",
  "outgo": "out(外へ)+go(行く)で「外に出ていくお金＝支出」。income(収入)の対義語として、会計報告や予算削減の文脈でoutgo on 〜の形で使われる。",
  "outstand": "out(外に)+stand(立つ)が原義。動詞よりも、派生形容詞のoutstandingが「傑出した」と「未払いの（outstanding balance）」の2大語義で超頻出。",
  "overnight": "「一晩泊まる」だけでなく、物流や通販の文脈で「overnight delivery（翌日配達）」や「ship overnight」のように形容詞・副詞として頻出。",
  "overstaffed": "over-(過剰)+staffed(人員が配置された)。人員過剰を指し、対義語のunderstaffed（人手不足の）やshort-staffedと合わせて覚えるのが有効。",
  "own": "所有代名詞を強める「one's own 〜」のほか、「on one's own（独力で＝by oneself）」という前置詞句がパート5で頻出する。",
  "owner": "動詞own(所有する)に-erがついた語。「small business owner（個人商店主・中小企業経営者）」やproperty ownerの形でパート7によく登場する。",
  "account": "名詞「口座・顧客（client）」のほか、動詞句「account for 〜（〜の割合を占める、〜の理由を説明する）」がリスニング・リーディング共に頻出。",
  "add": "ad-（〜へ）+dare（与える・置く）が語源。add A to B（AをBに加える）の語法や、派生語の additional charge（追加料金）、in addition to（〜に加えて）が頻出です。",
  "advance": "ab-（前へ）に由来。in advance（事前に）の成句や、advance notice（事前通知）、advance registration（事前登録）のように名詞の前で修飾する用法が頻出です。",
  "agenda": "ラテン語 agere（行う）に由来し「なされるべき事項」が原義。会議文脈の an item on the agenda（議題の項目）や set the agenda（議題を設定する）の形で登場します。",
  "agree": "人には agree with、提案や条件には agree to や agree on を使う前置詞の使い分けが狙われます。派生語の名詞 agreement（合意・契約書）も頻出です。",
  "allow": "allow + 目的語 + to do（〜に…することを許可する）の第5文型や受動態 be allowed to do が頻出。手当や手荷物許容量を表す派生語 allowance も重要です。",
  "analysis": "ana-（全体）+lysis（解く）で「分解して調べること」。market analysis（市場分析）などの複合名詞や、動詞 analyze、複数形 analyses の語尾変化に注意が必要です。",
  "approach": "ad-（〜へ）+prope（近い）が語源。動詞では前置詞不要の他動詞として目的語を取り、名詞では approach to 〜（〜への取り組み方）と前置詞 to を伴う点に注意です。",
  "audience": "audi（聞く）が語源で audio と同根。プレゼンや広告で用いられる target audience（対象顧客層）や a wide audience（幅広い聴衆）のコロケーションが頻出です。",
  "automatic": "auto-（自身で）+matos（動く）が語源。automatic renewal（自動更新）や automatic payment（自動引き落とし）など、契約やオンライン手続きの通知文でよく見られます。",
  "automatically": "automatic の副詞形で「自動的に」。will renew automatically（自動更新される）のように動詞を修飾する位置に入り、形容詞 automatic との品詞識別問題で狙われます。",
  "award": "動詞では award A B（AにBを授与する）のほか受動態 be awarded a contract（契約を受注する）が頻出。名詞では annual awards banquet（年次授賞式）が定番です。",
  "background": "back（後ろ）+ground（地面）が語源。求人票や紹介文で strong background in marketing（マーケティングの豊富な経験）のように「経歴・素養」の意味で頻出します。",
  "based": "be based in 〜（〜に拠点を置く）と be based on 〜（〜に基づく）の前置詞の使い分けが核心。前者は会社紹介、後者は調査や判断の根拠を示す文脈で頻出します。",
  "basis": "ギリシャ語の「歩み・足場」が語源。on a daily/regular basis（毎日／定期的に）のように on a 〜 basis の慣用句で副詞的に使われるパターンが頻出です。",
  "board": "名詞では the board of directors（取締役会）のビジネス用語、動詞では board a flight（飛行機に搭乗する）のように乗り物に「乗り込む」他動詞として頻出です。",
  "cafeteria": "スペイン語の「コーヒー店」が由来。社内通知で company cafeteria（社員食堂）の営業時間変更や改装（renovation）の文脈でリスニング・リーディング問わずよく出ます。",
  "cancel": "格子（cancelli）状に線を引いて消すことが語源。cancel an order（注文を取り消す）のほか、名詞形 cancellation fee（キャンセル料）やポリシーの案内で頻出です。",
  "capacity": "capere（収める）が語源。seating capacity（収容定員）や run at full capacity（フル稼働する）のほか、in one's capacity as 〜（〜の職務・資格で）の語法も頻出です。",
  "career": "ラテン語の「車道・走路」が語源で人生の進路を表します。career opportunity（就職・昇進の機会）や career advancement（昇進）など求人・人事文脈の定番語です。",
  "cash": "前置詞 in と結びつく pay in cash（現金で支払う）や財務文脈の cash flow（資金繰り）が定番。動詞として cash a check（小切手を換金する）の用法も出題されます。",
  "cash card": "銀行口座からATM（現金自動預払機）で預金を引き出すカード。TOEICでは銀行のサービス案内や紛失時の再発行手続き（replacement）の文脈で見られます。",
  "casual": "cadere（落ちる・偶然）が語源。社内通知のドレスコード規定で business casual（ビジネスカジュアル）や casual attire（略装）の形で頻出する形容詞です。",
  "charge": "名詞では free of charge（無料で）や in charge of 〜（〜を担当して）、動詞では charge 人 for 〜（人に代金を請求する）が頻出。fee や price との使い分けも大切です。",
  "choice": "動詞 choose の名詞形。have no choice but to do（〜せざるを得ない）の重要語法や、a wide choice of products（豊富な品揃え＝selection）の表現で出題されます。",
  "choose": "choose to do（〜することを選ぶ）の不定詞構文や、choose from 〜（〜の中から選ぶ）の前置詞が頻出。過去形 chose・過去分詞 chosen の不規則変化も確実に押さえましょう。",
  "community": "com-（共に）+munis（務め）が語源で「共通の場」を表します。企業の社会貢献文脈で local community（地域社会）や community outreach（地域支援活動）が頻出です。",
  "complete": "com-（強意）+plere（満たす）が語源。動詞では complete a form（書類に記入する＝fill out）が定番。形容詞として a complete list of 〜（完全な一覧）の用法も出ます。",
  "completely": "complete に -ly がついた副詞。completely satisfied（完全に満足して）や completely booked（満室・満席で）のように過去分詞を強調する位置で頻出します。",
  "condition": "con-（共に）+dicere（言う）で「取り決め」が原義。in good condition（良好な状態で）の単数用法と、working conditions（労働条件）のような複数用法の意味の違いが重要です。",
  "conference": "con-（共に）+ferre（運ぶ）で「意見を持ち寄る場」が原義。annual conference（年次総会）や press conference（記者会見）、attend a conference（会議に出席する）の表現が頻出です。",
  "connect": "con-(共に)+nect(結ぶ)が語源。connect to や connect with の形で機器やネットワークの接続、あるいは「人を電話でつなぐ」文脈で頻出。",
  "construction": "con-(共に)+struct(積み重ねる)+ion。under construction（工事中）の決まり文句で非常によく登場し、パート1の写真描写でも問われる。",
  "convenient": "con-(共に)+veni(来る)で「集まりやすい→都合が良い」。conveniently located（便利な立地にある）という受動態を修飾する副詞形との組み合わせが頻出。",
  "copy": "ラテン語の「豊富・多量」が語源で、原本を増やして作る「写し・控え」を指す。TOEICでは書類や本、パンフレットの「1部・1冊」を a copy of で表す。",
  "corporate": "corpus(身体)から「人の集まりを法人化する」が原義。corporate headquarters（本社）や corporate executive（会社幹部）の形で頻出。",
  "cover": "「覆う」だけでなく多義語として重要。TOEICでは費用を「賄う」、保険が「補償する」、記事や会議が議題を「取り上げる」、シフトの「代わりを務める」の意味で問われる。",
  "credit card": "credit(信用)から「後払い」。pay by credit card のように前置詞 by を使い、利用明細書を指す credit card statement も頻出。",
  "crew": "船や飛行機の「乗組員」だけでなく、工事や保守の「作業班」を表す。maintenance crew（保守班）や film crew（撮影クルー）など特定の業務チームを指す。",
  "customer": "custom(習慣)から「習慣的に買いに来る人」が由来。customer satisfaction（顧客満足度）や customer service（顧客対応）の形で頻出。",
  "damage": "「損害」の意味では不可算名詞で、cause damage to（〜に損害を与える）のように使う。複数形の damages にすると法律用語の「損害賠償金」になる点に注意。",
  "delay": "交通や配送の遅れで頻出。動詞は be delayed（遅れる）と受動態が多く、名詞では without delay（遅滞なく直ちに）の定型表現が狙われる。",
  "deliver": "de-(離す)+liver(自由にする)から「引き渡す」。荷物の配達だけでなく、deliver a speech（演説を行う）の組み合わせも頻出。",
  "detail": "tail(切る)と同根で「細かく切り分けたもの」。in detail（詳細に）や for further details（詳細はこちら）の定型表現が頻出。",
  "develop": "de-(外す)+velop(包む)で「包みを解いて広げる」。新製品や戦略を展開する文脈で develop a product / strategy と目的語をとる。",
  "device": "工夫して作られた「機器」を指す可算名詞。機内アナウンスなどで electronic devices（電子機器）や mobile device として頻出。",
  "directly": "direct(まっすぐ)+ly。contact me directly（直接連絡する）や、直属の上司に仕えることを表す report directly to の形で頻出。",
  "discount": "dis-(離す)+count(数える)で「計算から引く」。前置詞は at a 10% discount（1割引で）の at や discount on（〜の割引）の on に注目。",
  "discuss": "cuss(叩く)から「叩いて検証する」。他動詞なので discuss about とせず、discuss the plan のように直接目的語を置くのがパート5の鉄則。",
  "display": "play(折る)を広げて「見せる」。パート1で on display（展示中）や be displayed on the shelf（棚に並んでいる）の形で非常によく出る。",
  "fitness club": "fit(健康な)+ness。TOEICでは福利厚生（employee benefits）として会員権の割引（membership discount）が提供される文脈で頻出。",
  "just fit": "fit は「条件がぴったり合う」。寸法が合うだけでなく、人材が役職に「まさに適任である」（a just fit for the position）文脈でも使われる。",
  "packaging": "包装材や梱包作業を表す不可算名詞。個々の荷物（可算名詞）を表す package との区別や、eco-friendly packaging（環境配慮包装）の形で出やすい。",
  "painting": "「絵画」なら可算、「ペンキ塗装」なら不可算名詞。パート1で a painting is hanging on the wall（絵が壁にかかっている）の描写で定番。",
  "passenger": "pass(通る)+enger(人)。空港や駅のアナウンスで passengers traveling to...（〜へ向かう乗客）と呼びかける場面の定番語。",
  "policy": "politics(政治)と同源で、組織の「方針・規定」。return policy（返品規定）や company policy（社内規定）、insurance policy（保険証券）の形で頻出。",
  "position": "posit(置く)+ion。求人・人事文脈の「職・役職」で頻出し、apply for a position（応募する）や fill a position（後任を補う）と使われる。",
  "positive": "posit(置く)+iveで「明確に定められた→肯定的な」。positive feedback（好意的な意見）や positive review（高評価）など評価文脈で定番。",
  "possibility": "possible(可能な)の名詞形。there is a possibility of doing（〜の可能性がある）や、検討文脈の explore the possibility of... の形で頻出。",
  "practice": "語源は「実践」。put into practice（実行に移す）や best practices（最善手法）のほか、医師・弁護士の「開業事務所」を指す用法も頻出。",
  "press": "印刷機を「押す」ことから「報道機関」に派生。press release（公式発表資料）や press conference（記者会見）は広報文脈で頻出。",
  "private": "priv-（切り離された）が語源で、公から離れた状態を表す。TOEICでは「私的な」以外に、publicの対義語としてprivate sector（民間企業・部門）の文脈で頻出。",
  "professor": "pro-（前で）+fess（公言する）+-or（人）が語源。TOEICではセミナーの基調講演者や研修講師の肩書として、Part 4などのアナウンスに頻繁に登場する。",
  "quarter": "ラテン語の「4番目」が語源で、1年を4等分した「四半期（3か月）」を指す。first quarter（第1四半期）など、業績報告や売上推移の文脈で頻出。",
  "quarterly": "quarter（四半期）に接尾辞-lyが付いた語で、形容詞（四半期ごとの）と副詞（四半期ごとに）の両方がある。quarterly report（四半期報告書）が定番。",
  "rate": "「計算された基準」が原義で、割合・料金・ペースを表す。TOEICでは interest rate（金利）や room rate（ホテルの宿泊料）、hourly rate（時給）が定番。",
  "receive": "re-（手元へ）+ceive（つかむ）が語源。名詞形はreceipt（受領、領収書）。TOEICでは receive approval（承認を得る）など手続きの文脈で頻出。",
  "recent": "ラテン語の「新鮮な」が語源。in recent years（近年）や recent survey（最近の調査）の形で頻出。副詞 recently は完了形や過去形とよく呼応する。",
  "regular": "ラテン語regula（規則・定規）が語源。TOEICでは regular business hours（通常の営業時間）や regular maintenance（定期保守）の形で頻出。",
  "regularly": "形容詞regularに-lyが付いた副詞。inspect regularly（定期的に点検する）や update regularly（定期的に更新する）など、業務ルーティンを表す。",
  "relation": "re-（再び）+lat（運ぶ・結びつける）が語源。in relation to 〜（〜に関して）という群前置詞や、public relations（PR・広報活動）の形で頻出。",
  "rent": "動詞（借りる・貸す）と名詞（家賃）の双方で使われる。TOEICでは rent a car（レンタカーを借りる）や office space for rent（賃貸オフィス）で頻出。",
  "repair": "re-（再び）+parare（整える）が語源でprepareと同根。動詞と名詞の双用。under repair（修理中で）や repair costs（修理代）として施設トラブルの文脈で頻出。",
  "report": "re-（戻って）+port（運ぶ）が語源。report to work（出勤する）や report to the manager（部長の直属である・報告する）など、前置詞 to を伴う語法が頻出。",
  "retire": "re-（後ろへ）+フランス語tirer（引く）で「身を引く」が原義。retirement party（退職記念パーティー）や retirement plan（年金制度）の形で頻出。",
  "safety": "safe（安全な）の名詞形。TOEICでは safety precautions（安全予防策）や safety regulations（安全規則）のように複合名詞の先頭で使われることが多い。",
  "salary": "古代ローマ兵士の塩（sal）購入手当が語源。主に月給・年俸を指し、時給制のwageと区別される。求人票での competitive salary（高給・好待遇）は定番表現。",
  "satisfied": "ラテン語satis（十分）+facere（作る）が語源。感情を表す受身形容詞で、be satisfied with 〜（〜に満足している）の形で前置詞withと共起するのが鉄則。",
  "schedule": "小切片・一覧表を指すラテン語が語源。ahead of schedule（予定より前倒しで）や on schedule（予定通りに）、be scheduled to do の形が超頻出。",
  "scientific": "scire（知る）+-fic（生み出す）が語源。scientific research（科学的調査）や scientific journal（科学誌）の形で出やすく、名詞scienceとの品詞識別に注意。",
  "search": "circle（円）と同根で「一帯を巡り歩いて探す」が原義。search for 〜（〜を探す）だけでなく、search the database for 〜（〜を求めてDBを検索する）の語法に注意。",
  "seat": "sit（座る）の使役形（座らせる）が原義の他動詞・名詞。アナウンスでの Please be seated.（ご着席ください）や assigned seating（指定席）が頻出。",
  "security": "se-（〜から離れて）+cure（心配）+-ityで「不安のないこと」が語源。security badge（入館証）や security checkpoint（保安検査場）など施設管理で頻出。",
  "select": "se-（選り分けて）+lect（集める）が語源。動詞「選ぶ」のほか形容詞で「厳選された」の意味もある。派生語の a wide selection of 〜（幅広い品揃え）は超頻出。",
  "separate": "se-（離して）+parare（整える）が語源。動詞と形容詞で発音が異なる。ビジネスレターで書類を別送する際の under separate cover（別便にて）は最頻出フレーズ。",
  "serious": "ラテン語の「重々しい・真面目な」が語源。serious concern（深刻な懸念）や serious damage（深刻な被害）の形で、ビジネス上のリスクや問題点を述べる際に出る。",
  "seriously": "形容詞seriousに-lyが付いた副詞。take customer feedback seriously（顧客の意見を真剣に受け止める）や seriously damaged（ひどく損傷した）が頻出コロケーション。",
  "similar": "ラテン語similis（等しい・似ている）が語源。sameと同根。be similar to 〜（〜に似ている）の形で前置詞toを伴う点がTOEIC文法問題での典型的な狙い目。",
  "simply": "simpleに-lyが付いた語。TOEICでは広告や案内文で Simply fill out the form（フォームに記入するだけで結構です）のように命令文の頭で手続きの手軽さを強調する。",
  "standard": "戦場で目印として「立てられた旗」が原義で、行動や品質の「基準」を表す。standard procedure（標準手順）や safety standards（安全基準）の形で頻出。",
  "stock": "「木の幹・蓄え」が原義。TOEICでは株式（stockholder: 株主）だけでなく商品の在庫を指し、in stock（在庫あり）や out of stock（在庫切れ）の成句が頻出。",
  "study": "TOEICでは「勉強」よりも「調査・研究」の意味で頻出。conduct a study（調査を行う）や a recent study shows that... のように調査結果を伝える文脈でよく使われる。",
  "submit": "sub-（下に）+ mit（送る）で、目上の人に差し出すイメージから「提出する」。submit an application to...（〜に申請書を提出する）のように前置詞 to を伴う。",
  "success": "sub-（後ろに）+ cess（進む）が語源。Part 5では形容詞の successful（成功した）と successive（連続する）の意味・品詞の違いを狙う問題が定番。",
  "suggestion": "sub-（下から）+ gest（運ぶ）で控えめに差し出すイメージ。可算名詞なので a suggestion や suggestions と数えられるが、同義語の advice は不可算名詞。",
  "summary": "sum（合計・総体）が語源。TOEICではビジネス文書の冒頭にある executive summary（要約版・事業計画概要）や in summary（要するに）の表現で頻出。",
  "surface": "sur-（上に）+ face（面）で「物の上面・表面」。on the surface（表面上は）や road surface（路面）のほか、動詞で問題などが「表面化する」意味でも使われる。",
  "theater": "ギリシャ語の「観る場所」が語源。イベント告知や観光案内で box office（劇場のチケット売り場）や intermission（幕間休憩）とセットで出やすい。",
  "through": "手段の「〜を通じて」のほか、期間の範囲を表す Monday through Friday（月曜から金曜まで）の形が定番。アメリカ英語の用法で終わりの曜日も含める点に注意。",
  "tour": "ぐるっと「旋回して戻る旅」が原義。工場見学（factory tour）や施設見学（guided tour of the facility）など、社外視察や研修の場面で頻出。",
  "tourist": "tourist attraction（観光名所）や tourist destination（観光地）、tourist information center（観光案内所）など観光促進の広報文で頻出の複合名詞を作る。",
  "tradition": "trans-（越えて）+ dare（手渡す）で「世代を越えて引き継がれるもの」。long-standing tradition（長年の伝統）や形容詞 traditional（伝統的な）の形がよく問われる。",
  "trend": "market trends（市場動向）や upward trend（上昇傾向）、consumer trends（消費者傾向）のように、Part 7の売上・市場分析レポートの文脈でよく見かける。",
  "understand": "案内文やお知らせで Please understand that...（〜の旨をご了承ください）という丁寧な依頼・告知の定型表現としてPart 6やPart 7のメールで頻出。",
  "update": "up（上へ）+ date（日付）で「日付を最新にする」。動詞のほか名詞として provide an update on...（〜の最新状況を報告する）や status update（進捗報告）で多用される。",
  "vacation": "vac-（空っぽの）が語源で、仕事が空になる期間。paid vacation（有給休暇）や take a vacation のほか、不在自動返信メール（休暇通知）の文脈で登場する。",
  "variety": "vary（異なる）の名詞形。a wide variety of + 複数名詞（多種多様な〜）は広告やカタログで品揃えの豊富さをアピールする最頻出コロケーション。",
  "visual": "vis-（見る）が語根。プレゼンの場面で visual aids（スライドや図表などの視覚資料）、製造・品質管理で visual inspection（外観・目視検査）として登場。",
  "weekly": "weekly meeting（定例週次会議）や weekly newsletter（週刊会報）など形容詞で使われるほか、「毎週」という意味の副詞としても使える点に注意。",
  "without": "without prior notice（事前の通知なしに）や without delay（遅滞なく）、without permission（許可なく）など、規約や業務指示の定型句で頻出の前置詞。",
  "mounting pressure": "mount（山のように積もる・高まる）から。face mounting pressure to do（〜するよう高まる重圧に直面する）や mounting costs（かさむ費用）の形でビジネス記事に出る。",
  "cornerstone": "建物の土台の角に置く基礎の石「隅石」が原義。the cornerstone of our strategy（わが社の戦略の要）のように、事業や方針の中核・礎を比喩的に指す。",
  "upfront investment": "upfront（前もって・先払いの）+ investment（投資）で「初期投資」。システム導入や新規事業の提案書で upfront costs（初期費用）とともに頻出するビジネス用語。",
  "moderation": "moderate（適度な）の名詞形。社内報の健康コラムなどで in moderation（適度に、控えめに）という成句で使われることが多い（例: consume in moderation）。",
  "marinate": "海（marine）と同語源で、もとは海水や塩水に浸して保存したことから。メニュー紹介や食品記事で marinated in herbs（ハーブ漬けにした）のように過去分詞で頻出。",
  "fermented": "ラテン語の「泡立つ・沸騰する」が原義。fermented foods（発酵食品）や fermented tea（発酵茶）など、健康食品の広告やオーガニック製品の紹介文で見かける。",
  "inflammation": "in-（中）+ flame（炎）で体内に火がついた状態から「炎症」。健康コラムや福利厚生のフィットネス記事で reduce inflammation（炎症を和らげる）の文脈で登場。",
  "probiotics": "pro-（味方・促進）+ biotic（生命の）で抗生物質（antibiotic）の対義語。健康食品やヨーグルトの宣伝で rich in probiotics（善玉菌が豊富）の形で出やすい。",
  "elaborate": "e-（外へ）+ labor（労力）で「労力を注ぎ込んだ」。形容詞の「精巧な」のほか、動詞で elaborate on...（〜についてさらに詳しく説明する）の語法が会議の場面で頻出。",
  "temptation": "動詞 tempt（誘惑する）の名詞形。業務効率化や時間管理の記事で resist the temptation to do（〜したい誘惑をこらえる）という成句で使われることが多い。",
  "tailored": "洋服の仕立て屋（tailor）が個人の体型に合わせることから。be tailored to meet your needs（お客様のニーズに合わせて個別設計された）の形で広告に頻出。",
  "strip away": "strip（剥ぐ）+ away（離して）。本質を残すために余計なコストや偏見を削ぎ落とす感覚。strip away unnecessary costs や strip away myths で使われる。",
  "oversimplification": "over-(過度に) + simple(単純) + -fy + -tion。議論を単純化しすぎた際に批判的に用いられ、oversimplification of ~ のように前置詞 of と結びつきやすい。",
  "capital": "語根 cap(頭)から「主要なもの・元手」を表す。TOEICでは raise capital（資金を調達する）や capital investment（設備投資）といった財務・経営関連のコロケーションが頻出。",
  "precision": "pre-(前もって) + cis(切る)で「不要部分を切り落とした正確さ」。with great precision（極めて精密に）などの副詞句や、precision instruments（精密機器）の複合名詞で出やすい。",
  "automated": "auto-(自ら) + matos(動く)が語源。自動化されたシステムを表す automated system や fully automated（完全自動化された）などの形で、Part 7の製造・IT記事によく登場する。",
  "displace": "dis-(離れて) + place(置く)で「元の場所から押し出す」。be displaced by robots（ロボットに職を奪われる）のように、雇用や立ち退きの文脈で見られる。",
  "scale up": "scale（規模）を up（上へ）引き上げる句動詞。scale up production（生産を拡大する）や scale up operations のように事業拡大の文脈で重宝される。",
  "resilient": "re-(跳ね返る) + salire(跳ぶ)で「衝撃を受けても元に戻る」。resilient supply chain（強靭なサプライチェーン）のように組織や経済の回復力を表す。",
  "regardless of": "regard（考慮）+ -less（ない）+ of で「〜を考慮に入れずに」。regardless of age や regardless of experience のように後ろに名詞句を従える。",
  "vertical farming": "vertical（垂直の）+ farming（農業）。高層ビルや立体棚でLEDや水耕栽培を用いて作物を育てる次世代農業を指し、Part 7の環境・最新アグリ技術関連のパッセージで話題になる。",
  "invest heavily in": "in は投資先を表す必須の前置詞。invest in ~（〜に投資する）の間に度合いを強める heavily（手厚く）が挟まった形で、研究開発や設備投資の文脈でそのまま問われやすい。",
  "getaway": "get away（日常から抜け出す）から生まれた名詞。weekend getaway（週末の小旅行）や perfect getaway（最高の保養地）のように観光・ホテル広告やPart 7の旅行記事で頻出する。",
  "satisfaction": "satis-(十分に) + fac-(作る)で「十分満たされた状態」。TOEICでは customer satisfaction（顧客満足度）や satisfaction survey（満足度調査）などの複合名詞が定番。",
  "off the beaten path": "beaten path（踏み固められた定番の通り）から off（外れて）の意。観光地紹介や旅の広告文で「人混みを避けた隠れ家的な場所」をアピールするフレーズとして使われる。",
  "in favor of": "favor（好意・支持）から「〜に賛成して」。vote in favor of the proposal（提案に賛成票を投じる）のように、会議の採決や方針決定で頻出する。",
  "opt for": "option（選択肢）と同語源の動詞 opt は前置詞 for を伴う。opt for a cheaper alternative（より安価な選択肢を選ぶ）のように製品選択で登場する。",
  "strike up": "マッチを擦って火をつけるように「突発的にパッと始める」感覚。strike up a conversation（会話を始める）や strike up a friendship のように決まった名詞とセットで用いられる。",
  "footprint": "本来の「足跡」から転じて、人間活動が環境に残す負荷を指す。reduce one's carbon footprint（二酸化炭素排出量を減らす）や environmental footprint の定型表現で頻出。",
  "deliberately": "de-(十分に) + libra(天秤)で「よく秤にかけて判断した」。deliberately schedule（意図的に日程を組む）のように、意図的な行動を修飾する副詞。",
  "overall well-being": "overall（総合的な）+ well-being（良好な状態）。employee well-being（従業員の健康・幸福）や promote overall well-being の形で登場する。",
  "compound": "com-(共に) + ponere(置く)で「一緒に混ぜ合わせたもの」。chemical compound（化合物）や natural compounds（天然成分）のように、新薬開発や製品原材料の文脈で名詞として出やすい。",
  "staple": "中世の公認市場（staple）で扱われる主要品目が語源。staple food（主食）や staple item（定番商品）のように名詞の前で形容詞的に使われるほか、a staple of ~（〜の代表格）としても出る。",
  "draw attention to": "draw（引く）+ attention（注意）+ to（〜へ）。draw attention to an issue（問題に注目を集める）のように、問題提起やPRの文脈で頻出する。",
  "microorganism": "micro-(微小な) + organism(有機体・生物)。バイオテクノロジーや環境技術、食品加工の記事で見られ、break down（分解する）などの動詞とともに主語として使われやすい。",
  "fermentation": "ラテン語 fervere（沸き立つ）が語源。パンや酒、新素材の製造記事で fermentation process（発酵工程）の形で使われ、bio-fermentation など環境配慮型製造のトピックにも登場する。",
  "carbon emissions": "carbon（炭素）+ emit（排出する）の名詞形 emission。企業のアニュアルレポートや環境方針で reduce carbon emissions by ~%（炭素排出量を〜%削減する）の形で頻繁に登場する。",
  "commercial scale": "commercial（商業的な）+ scale（規模）。研究・試験段階を終えて採算の取れる量産体制に入ったことを示す on a commercial scale（商業規模で）という前置詞句でよく使われる。",
  "hydroponic": "hydro-(水) + ponos(労働)から「土の代わりに養液で育てる」。hydroponic system（水耕栽培システム）のように、環境や先端農業の文脈で見られる。",
  "market share": "market（市場）+ share（分け前）。increase market share（市場シェアを拡大する）や gain market share など、動詞とのコロケーションが頻出する。",
  "differentiate": "dis-(別々に) + ferre(運ぶ)で「差をつける」。differentiate A from B（AをBと差別化する）の前置詞 from や、differentiate itself（差別化を図る）の語法が重要。",
  "subscription-based": "sub-(下に)+scribe(書く)で署名して申し込むことが原義。subscription-based service や subscription-based model の形でビジネス・IT関連の文書でよく使われる。",
  "transformation": "trans-(越えて)+form(形)で「形をすっかり変えること」。undergo a major transformation（大変革を遂げる）のコロケーションが頻出。",
  "saturation": "satur（満ちた）が語源で satisfy（満足させる）と同根。TOEICでは market saturation（市場飽和）や reach saturation の形で事業環境の分析によく見られる。",
  "dread": "古英語由来で、恐れやおっくうな気持ちを表す。後ろに動名詞を取る dread doing（〜するのを恐れる・嫌がる）の語法や、名詞としての用法を押さえておくと安心。",
  "efficiently": "ef-(外へ)+fic(作る)で「無駄なく結果を出す」イメージ。Part 5では work efficiently や operate efficiently のように動詞を後ろから修飾する副詞としてよく狙われる。",
  "ritual": "ラテン語の「宗教的儀式」が原義だが、TOEICでは morning ritual や daily ritual のように「毎日の決まった習慣・ルーティン」の意味でエッセイやコラムに登場しやすい。",
  "in bulk": "bulk は「かさ、容積、大量」を意味する。buy in bulk（大量購入する）や order in bulk（まとめ買いする）の形で、購買や経費削減の話題によく登場する定番表現。",
  "portion out": "portion（一人前の分け前・一部分）に分配の out がついた句動詞。食事を小分けにするだけでなく、予算や資源を割り振る文脈でも使われる。",
  "liberating": "liberty（自由）と同語源で liber（自由）に由来。a liberating experience（自由を感じさせる体験）のように、人ではなく状況や体験を修飾する形容詞として使われる。",
  "tailored to": "洋服を仕立てる tailor に由来し、be tailored to the needs of 〜（〜のニーズに合わせて作られた）の形で顧客向けサービスや研修プログラムの説明によく使われる。",
  "on a whim": "whim（気まぐれ・衝動）からなる熟語。buy on a whim（衝動買いする）のように、事前の計画なしに行動する場面で使われる。planned（計画的な）の対義的ニュアンス。",
  "take notice of": "notice（注意・注目）を払うことから「〜に気付く、注目する」。pay attention to と同義で、take notice of customer trends など市場の動向を捉える文脈で使われる。",
  "intimidating": "in-(中に)+timid（臆病な）で「人を怯えさせる」。an intimidating task（圧倒されるような困難な仕事）のように事物を修飾し、感情を表す intimidated と区別しよう。",
  "driven by": "drive（前へ押し進める）の過去分詞。growth driven by consumer demand（個人消費に後押しされた成長）のように、売上や成果の主因を説明するビジネス記事で頻出。",
  "passing fad": "passing（通り過ぎる、一時の）+ fad（気まぐれな流行）。just a passing fad（単なる一過性のブーム）の形で、長期的なトレンドと対比して市場の持続性を論じる際によく使われる。",
  "commit to": "com-(共に)+mit(送る・委ねる)が語源。to は前置詞なので後ろに動名詞（commit to doing）や名詞を取る点が Part 5 で頻繁に狙われる文法ポイント。",
  "rely heavily on": "rely on（〜に頼る）を副詞 heavily（大いに）で強めた形。rely heavily on imports（輸入に大きく依存する）のように、企業の事業構造やリスク要因を述べる文脈で頻出。",
  "operating costs": "operate（運営する）にかかる費用。reduce operating costs（運営コストを削減する）や cut operating costs の形で、決算報告や業務改善の話題で定番のフレーズ。",
  "suffer": "sub-(下で)+fer(耐える)が原義。病気に限らず、sales suffered（売上が落ち込んだ）や quality suffered（質が低下した）のように業績や品質が悪化する文脈で頻出。",
  "in terms of": "term には「観点・条件」の意味がある。in terms of quality and cost（品質と費用の観点で）のように、提案や製品を比較評価する際の基準を示す定番表現。",
  "drought": "dry（乾いた）と同語源。severe drought（深刻な干ばつ）の形で使われることが多く、天候不順による農作物の減収や原材料価格高騰を説明するニュースでよく登場する。",
  "self-sufficient": "self（自身で）+ sufficient（十分な）で「自分だけで足りる」。become energy self-sufficient（エネルギー自給を達成する）のように環境・エネルギー戦略の文脈で登場する。",
  "whirlwind vacation": "whirlwind（旋風）のように目まぐるしく進むことを表す比喩表現。whirlwind vacation や whirlwind tour（弾丸ツアー）の形で、短期間で慌ただしく観光地を巡る旅程を指す。",
  "contribute to": "con-(共に)+tribute(与える)で「一緒に差し出す」。to は前置詞なので後ろは名詞・動名詞。良い貢献だけでなく contribute to delays（遅れの原因となる）のように悪影響にも使われる。",
  "overtourism": "over-(過度の)+tourism で「過剰観光」。combat overtourism（観光公害に対処する）や manage overtourism のように、自治体の対策やホテル業界の課題として長文読解に登場しやすい。",
  "brand loyalty": "loyal（忠実な）の名詞形。build brand loyalty（顧客の忠誠心を高める）や foster brand loyalty の形で、リピーター獲得やマーケティング戦略の文書に頻出するコロケーション。",
  "scarce": "古フランス語の「切り詰めた」に由来。rare（珍しい）と異なり「需要に供給が足りていない」ことを指す。scarce resources（希少な資源）や副詞 scarcely（ほとんど〜ない）も要チェック。",
  "storefront": "store（店）+ front（正面）で、通りに面した「店先・実店舗」。ECサイトとの対比で physical storefront と言ったり、open a new storefront（新店舗を構える）の形で小売の話題に出る。",
  "invest in": "in-(中に)+vest(服を着せる)から「資金を投じる」意に発展。invest in renewable energy や invest in staff training のように前置詞 in とセットで出題される基本動詞句。",
  "adopt": "ad-(〜へ)+opt(選ぶ)で「選んで取り入れる」。adopt a new policy（新方針を採用する）のように使われる。形が酷似している adapt（〜を適応させる）との識別が Part 5 で頻出。",
  "labor shortage": "labor（労働）+shortage（不足）。TOEICでは address a labor shortage（人手不足に対処する）や severe labor shortage のコロケーションで頻出。",
  "coincide with": "co-（共に）+incide（起こる）が語源。TOEICでは coincide with the conference（会議と重なる）のように前置詞 with を伴い、日程調整の文脈で使われる。",
  "appreciate in value": "ad-（〜へ）+pretium（価格）が語源で「価値が上がる」。投資の文脈で使われ、対義語の depreciate in value（価値が下がる）と対比で覚えるのが効果的。",
  "out of print": "out of（在庫切れ・範囲外）+print（印刷）で「印刷が終了した状態」。TOEICでは書店や出版社の文脈で、書籍が絶版で入手困難なことを伝える場面で登場する。",
  "sporadically": "spore（胞子）と同根で「種があちこちに散らばる」が原義。TOEICでは regularly（定期的に）の対比として、障害や作業が散発的に起きる文脈で使われる。",
  "overwhelmed": "over-（上に）+whelm（覆う）で「水に沈められる」が原義。TOEICでは feel overwhelmed with tasks（業務に圧倒される）のように多忙やプレッシャーの文脈で頻出。",
  "ease into": "ease（楽にする）+into（〜の中へ）で「無理なく徐々に入り込む」。TOEICでは ease into a new role（新しい役職に徐々に慣れる）など、新職務への順応で使われる。",
  "prioritize": "prior（より前の）+-ize（〜化する）が語源。TOEICでは prioritize tasks（タスクを優先する）など業務管理で頻出。名詞形 priority も重要。",
  "composure": "com-（共に）+poser（置く）で「心を整えて置くこと」が原義。TOEICでは keep one's composure（冷静さを保つ）の成句で、トラブルや交渉の対応場面で登場する。",
  "pay dividends": "dividend（配当金）を支払うことから「努力が実を結ぶ」比喩表現。TOEICでは training will pay dividends（研修が成果を生む）のように使われる。",
  "stepping stone": "小川を渡る「飛び石」が原義。TOEICでは a stepping stone to a promotion（昇進への足がかり）のように、キャリアアップの段階を表す文脈で使われる。",
  "startup cost": "startup（立ち上げ）+cost（費用）で「起業・開業時の初期費用」。TOEICでは initial costs（初期費用）の同義語として、新事業の予算や資金計画で頻出する。",
  "fixture": "fix（固定する）+-tureで「据え付け品、定番のもの」。TOEICでは店舗設備（fixtures）のほか、become a fixture（定番として定着する）の比喩表現でも登場する。",
  "captivate": "capture（捕らえる）と同根で「心を捕らえて魅了する」が原義。TOEICでは新製品のデザインやプレゼンが captivate the audience（聴衆を魅了する）の形で使われる。",
  "linger": "long（長い）と同源で「長く引き延ばしてとどまる」が原義。TOEICでは linger over lunch（昼食をゆっくり楽しむ）や、匂いや影響が「なかなか消えない」文脈で使われる。",
  "single supplement": "supplement（追加補足）から「1人部屋利用の追加割増料金」。TOEICのツアー案内で waive the single supplement（シングル割増料金を免除する）などの形で登場する。",
  "strike up a conversation": "strike up（打ち出す・始める）から「会話を始める」。TOEICでは strike up a conversation with attendees（参加者に話しかける）など懇親の場で使われる。",
  "harvest": "ドイツ語 Herbst（秋）と同語源で「秋の実りを収穫する」。名詞・動詞兼用。TOEICでは locally harvested produce（地元で収穫された農産物）など飲食の文脈で頻出。",
  "follow suit": "トランプで同じマーク（suit）の札を出すルールが由来。TOEICでは competitors followed suit（競合他社も追随した）のように他社の追随行動で使われる。",
  "cultivate": "culture（文化）と同根で「耕して育てる」。TOEICでは cultivate relationships with clients（顧客との関係を深める）のように比喩的によく使われる。",
  "yield": "古英語の「生み出す・支払う」が語源。名詞で「生産量・投資利回り」、動詞で「産出する」。TOEICでは high-yield investment（高利回り投資）や収穫高の文脈で頻出する。",
  "significantly": "sign（目印）+fic（作る）で「目立つほどに」。TOEICの業績報告で increase significantly（著しく増加する）のように、売上や費用の増減動詞を修飾する定番副詞。",
  "property owner": "property（不動産）+owner（所有者）。TOEICでは賃貸契約や都市計画、建物の改装通知などで、landlord（家主）の改まった表現として通知文によく登場する。",
  "capitalize on": "capital（資本）から「好機を利益に変える」。TOEICでは capitalize on a market trend（市場トレンドを活かす）のように、機会や強みの活用で頻出。",
  "gain momentum": "momentum（運動量・推進力）を獲得することから「弾みがつく」。TOEICでは新製品の売れ行きや普及活動が gain momentum（勢いを増す）として事業進捗の文脈で登場する。",
  "resurgence": "re-（再び）+surge（湧き上がる）が語源。TOEICでは a resurgence in sales（売上の再浮上）や a resurgence of interest（関心の再燃）で登場する。",
  "niche market": "フランス語の「壁のくぼみ」が語源で、特定の小さな領域を指す。TOEICでは target a niche market（ニッチ市場を狙う）のように、スタートアップの差別化戦略の文脈で頻出。",
  "tangible": "ラテン語 tangere（触れる）が語源で「触れられる→具体的な」。TOEICでは tangible results（目に見える成果）や tangible assets（有形資産）で頻出。",
  "set apart": "「他から離して置く」ことから「際立たせる」。TOEICでは What sets us apart from competitors（他社と差別化する点）のように from と共に頻出。",
  "replicate": "re-（再び）+plicare（折る・重ねる）から「同じものを折り写す」。TOEICでは replicate the success（成功を再現する）など、成功モデルの他地域展開や実験再現で使われる。",
  "genuine": "gen-(生まれる)に由来し、「生まれつきの純粋さ」から「本物の、心からの」という意味に。genuine leather（本革）や genuine interest（純粋な関心）のように使われます。",
  "squeeze": "物理的に「搾る」だけでなく、ビジネスでは squeeze profit margins（利益を圧迫する）や squeeze budgets（予算を切り詰める）のように財政面を圧迫する文脈で使われます。",
  "foot traffic": "文字通り「足の交通量」から店舗や街頭の「客足・人通り」を指します。小売店の立地や売上報告で heavy foot traffic（人通りの多さ）や attract foot traffic の形で登場します。",
  "barrier to entry": "entry（参入）を阻む barrier（障壁）で「参入障壁」。lower the barrier to entry（参入障壁を下げる）や high barrier to entry の形で新規事業や市場動向の文脈で使われます。",
  "overstate": "over-(過度に)+state(述べる)で「大げさに言う」。TOEICでは cannot be overstated（いくら強調してもしすぎることはない）という重要性を訴える定型句でよく見られます。",
  "rely on": "前置詞 on とセットで depend on と同義。Part 5では形容詞 reliable（頼りになる）や名詞 reliance（依存）への品詞派生が頻出で、rely on heavily のように副詞が挟まる形にも注意。",
  "immersion": "im-(中に)+merg(沈める)から「すっかり浸ること」。言語教育や企業研修の文脈で immersion program（集中没入型プログラム）や total immersion の形で登場します。",
  "squeeze in": "隙間に無理やり押し込むイメージから、過密日程の合間に「時間を作って予定を入れる」意味に。squeeze in a meeting / appointment のようにスケジュール調整の会話で出ます。",
  "compact": "com-(共に)+pact(結びつける)で「ぎゅっと詰まった」が原義。製品仕様やオフィスの文脈で compact size（小型サイズ）や compact design（省スペース設計）として登場します。",
  "thrive": "prosper や flourish と同義の自動詞で「事業が繁栄する・植物がよく育つ」。thrive in a competitive market（競争の激しい市場で生き残る）などビジネスの成功を表す文脈で使われます。",
  "dedicate A to B": "AをBに「充てる・捧げる」。この to は前置詞のため、後ろには名詞だけでなく動名詞（doing）が来る点がPart 5の文法問題で問われやすい重要ポイントです。",
  "trade-off": "trade（交換）して一方を off（手放す）ことから「両立しない2者間の兼ね合い」。a trade-off between quality and cost（品質と費用の妥協点）のように between を伴って使われます。",
  "cope with": "困難な状況や変化を「何とか乗り切る・うまく処理する」。deal with よりも困難に耐えるニュアンスがあり、cope with a sudden surge in demand（急増した需要に対応する）など業務負荷の話題で出ます。",
  "sell out": "チケットや新商品が「完売する」。Part 7の告知やメールで be completely sold out（全席完売）や、先行予約が sold out in minutes（数分で売り切れた）という形で頻出です。",
  "overcrowding": "over-(過度に)+crowd(群衆)で「過密・混雑」。公共交通や展示会の話題で、alleviate overcrowding（混雑を緩和する）や reduce overcrowding のように動詞とセットで登場します。",
  "spontaneous": "ラテン語の「自発的な意志」に由来し、計画なしにその場で自然に行うこと。spontaneous decision（思いつきの決断）や spontaneous applause（自然発生的な拍手）の形で使われます。",
  "mutually beneficial": "mutually（相互に）+ beneficial（有益な）で「双方に利益がある」。企業間の提携や契約交渉の文脈で、a mutually beneficial partnership（互恵関係）として定型的に使われます。",
  "long for": "形容詞 long（長い）と同じ語源で、「思いを長く引き延ばす」から「〜を強く待ち望む」に。long for a change（変化を切望する）や long to see のように不定詞を伴う形もあります。",
  "cramped": "筋肉のこむら返りを意味する cramp から転じ、空間が「手狭で窮屈な」状態を表します。Part 7では cramped working conditions（狭い執務環境）を理由にしたオフィスの移転告知でよく見られます。",
  "wander": "あてもなく「歩き回る・さまよう」意味で、綴りが似ている wonder（不思議に思う）との混同に注意。wander around the showroom（展示場を歩き回る）などの状況描写で使われます。",
  "urban dweller": "dwell（住む）に由来する dweller（住民）と urban（都会の）が合わさり「都市生活者」。city resident と同義で、住宅事情やエコ意識に関する市場調査の文章で登場します。",
  "cortisol": "副腎皮質（cortex）に由来するストレスホルモン。TOEICではPart 7のウェルネス・健康管理に関するコラム記事で、reduce cortisol levels（ストレス数値を下げる）の文脈で登場します。",
  "immerse": "im-(中に)+merg(沈める)で「液体に浸す・夢中にさせる」。immerse oneself in work / research（仕事に没頭する）のように再帰代名詞を伴う構文が代表的です。",
  "therapeutic": "therapy（療法）の形容詞形で「治療上の・心身を癒す効果のある」。社員のメンタルヘルスや福利厚生の話題で therapeutic benefits（リフレッシュ効果・癒しの効能）などの形で使われます。",
  "rejuvenate": "re-(再び)+juven-(若い)+-ate(動詞化)で「若返らせる・活力を取り戻す」。rejuvenate tired employees（疲れた社員を癒す）や、比喩的に地域経済・ブランドを活性化する文脈で使われます。",
  "gain traction": "traction（タイヤの地面への食いつき・牽引力）から、新企画や技術が空回りせず「勢いづく・支持を広げる」ことを指します。gain traction among consumers などの形で出ます。",
  "well-being": "well（良い）+being（状態）で「心身の健康・幸福」。企業の人事やオフィス環境の話題で promote employee well-being（従業員のウェルビーイングを促進する）として極めて頻出です。",
  "commute": "定期券の運賃割引（交換・軽減）の歴史から「定期的な往復通勤」の意味に。daily commute（日々の通勤）や commute time（通勤時間）などの名詞のほか、自動詞「通勤する」でも頻出。",
  "barrier": "bar（棒・柵）が語源で「行く手を遮る壁」。trade barriers（貿易障壁）や language barrier（言葉の壁）のほか、overcome a barrier（壁を乗り越える）という動詞との組み合わせで頻出です。",
  "busking": "路上や駅構内で演奏・芸を行って投げ銭を得ること（大道芸）。Part 7の公共スペースや自治体のお知らせで、busking permit（路上演奏許可証）や演奏規制の文脈で登場することがあります。",
  "amplifier": "ample(十分な)+-fy(〜にする)+-er(物)から「音や信号を大きくするもの」。動詞 amplify や形容詞 ample も頻出。音響設備や機械の説明で見られる。",
  "credit A with B": "「AにBの功績があるとする」の意。受動態の A is credited with B（AはBの功績を認められている）や be credited with doing の形で頻出。",
  "designate": "de-(明確に)+sign(印)+-ate で「印をつけて指定する」。Part 5 や案内文で designated area(指定区域)のように過去分詞で名詞を修飾する形が目立つ。",
  "passersby": "passer(通る人)+by(そばを)の複合語。複数形は by ではなく名詞側に s がついて passersby となる点に注意。街頭や店舗前の人通りを描く場面で見られる。",
  "go viral": "virus(ウイルス)の形容詞 viral に go を組み合わせ、「ウイルスのように拡散する」を表す。TOEICではSNSマーケティングや広告戦略の文脈で登場しやすい。",
  "cashless": "cash(現金)+-less(〜のない)。cashless payment(キャッシュレス決済)や cashless transaction などのコロケーションで頻出の現代ビジネス語。",
  "launching pad": "launch(打ち上げる)+pad(台)から、ロケット発射台を転じて「飛躍の足がかり」。serve as a launching pad for ~ の形で事業やキャリアの文脈に合う。",
  "sharpen": "sharp(鋭い)+-en(〜にする)で「研ぎ澄ます」。刃物だけでなく、sharpen skills(スキルを磨く)のように研修やキャリアアップの文脈で比喩的に使われる。",
  "renewed": "re-(再び)+new(新しい)+-ed から「再び強まった」。renewed interest(再燃した関心)や renewed efforts(新たな取り組み)のように名詞を修飾する。",
  "cost-effective": "cost(費用)+effective(効果的な)で「費用対効果が高い」。cost-effective solution(効果的な解決策)や alternative の形で提案書に頻出。",
  "mentee": "mentor(指導者)に対し、指導を受ける人を表す接尾辞 -ee がついた語。社内研修や新入社員育成の文脈で mentor とペアで登場する。",
  "retention": "動詞 retain(維持する)の名詞形。re-(手元に)+tain(保つ)が語源。人事の employee retention(社員定着率)やマーケティングの顧客維持で頻出。",
  "intentional": "in-(〜へ)+tend(心を向ける)から名詞 intention を経て形容詞化。「意図的な」を意味し、intentional effort や類義語 deliberate との言い換えで出る。",
  "appealing": "appeal(心に訴える)+-ing で「魅力的な」。find ~ appealing(〜を魅力的だと思う)や appealing offer など広告・販促の文脈でよく見られる。",
  "dominate": "ラテン語 dominus(主人)が語源で「主導権を握る」。dominate the market(市場を席巻する)という市場シェアや業界動向を論じる記事で頻出の動詞。",
  "consumption": "con-(完全に)+sumere(取る)の動詞 consume の名詞形。energy consumption(エネルギー消費量)のように、省エネやコスト削減の文脈で定番の名詞。",
  "outpace": "接頭辞 out-(〜を超える)+pace(速度)。demand outpacing supply(需要が供給を上回る)のように、売上や生産の伸びを比較する文脈で使われる。",
  "stigma": "ギリシャ語の「焼き印」が原義で、社会的な「汚名・偏見」。stigma attached to ~(〜に伴う偏見)の形で、職場のメンタルヘルスや働き方の話題で見られる。",
  "wake word": "wake(目覚めさせる)+word(単語)から、スマートスピーカー等の音声起動コマンドを指す。IT機器の紹介記事や取扱説明書の文脈で登場する技術用語。",
  "hands-free": "hands(手)+free(〜がない)で「手を使わずに操作できる」。hands-free operation や hands-free device の形で安全規則や新機能の紹介に頻出。",
  "skepticism": "ギリシャ語の「よく調べる」に由来する skeptic(懐疑的な人)の名詞形。skepticism about ~(〜への疑念)の形で新提案や新技術への慎重姿勢を表す。",
  "conversational": "conversation(会話)+-al(形容詞)。conversational tone(くだけた会話調)や conversational AI(対話型AI)の形で広告・UI説明に使われる。",
  "mature": "ラテン語 maturus(熟した)が語源。形容詞だけでなく自動詞「成熟する・(債券が)満期になる」としても重要。mature market(成熟市場)などの形で使われる。",
  "recurring": "re-(再び)+currere(走る)から「繰り返し生じる」。recurring fee(定期料金)や recurring issue(再発する問題)などビジネスの現場で頻出。",
  "push back": "文字通り「押し返す」から「反対・反発する」。push back against proposed changes(提案に反発する)や、日程を延期する文脈でも使われる。",
  "bundle": "bind(縛る)と同源で、まとめた「束・セット」。通信やソフト販売で service bundle のように複数サービスを組み合わせた割安パッケージを指して使われる。",
  "subscription fatigue": "subscription(定額契約)+fatigue(疲労)。多すぎる月額課金サービスに消費者がうんざりする現象を指し、消費動向や解約対策の記事で登場する。",
  "concession": "concede(認める・譲る)の名詞形。営業権の付与から転じて「売店」を意味する。concession stand(劇場や球場の飲食売店)の形で Part 3/4 や案内文に頻出。",
  "mingle": "among や mix と同源で「入り混じる」。パーティーやカンファレンス案内で、mingle with other attendees(他の参加者と歓談・交流する)の形で頻出。",
  "niche": "フランス語の「壁のくぼみ」が原義。隙間にすっぽり収まることから、niche market(隙間市場)や carve out a niche のように企業戦略の文脈で頻出。",
  "trigger the release of": "銃の引き金(trigger)を引いて外に解き放つ(release)イメージ。release は新製品や情報の「発売・公開」の意味でも TOEIC 頻出。",
  "unplug from": "否定の un- ＋ plug（コンセント）で「電源を抜く」が原義。比喩的にスマホや仕事の連絡から離れて休養を取る文脈で使われる。",
  "cardiovascular": "ギリシャ語由来の cardio-（心臓）と vascular（血管の）の合成語。福利厚生や健康促進プログラムの話題で見かける専門語。",
  "resilience": "re-（再び）＋語根sil（跳ねる）で「跳ね返る力」が原義。build resilience（回復力を高める）などの形で使われる。",
  "chronic": "語根 chron（時）に由来し、長時間続く状態を表す。慢性疾患だけでなく、chronic shortage（慢性的な不足）のようにビジネスでも頻出。",
  "alternate between A and B": "alter（別の）に由来し「交互に行う」。between を伴って使われる。名詞 alternative（代替案）との品詞・意味の違いに注意。",
  "memorable": "memory（記憶）＋ -able（できる）で「心に残りやすい」。記念碑や追悼を表す memorial と混同しないよう注意。",
  "confined": "con-（強意）＋ fine（境界）で「枠の中に制限された」。be confined to ...（〜に限定されている）の受動態で使われやすい。",
  "stopover": "途中で立ち寄る（stop over）ことから「途中降機・立ち寄り」。観光を伴う24時間以上の滞在を指すことが多く、layoverとセットで覚えると便利。",
  "layover": "乗り継ぎ便（connecting flight）の間の「待ち時間」を表す名詞。空港内での数時間の待機によく使われ、出張や旅行の日程表に頻出。",
  "account for": "「〜の理由を説明する」「〜の割合を占める」の2大語法に加え、遅延などを「計算に入れる・考慮する」意味でも使われる重要句動詞。",
  "dedicate": "de-（完全に）＋ dicate（宣言する）が語源。be dedicated to -ing（〜に専念している）の受動態では to が前置詞になる点が文法問題の急所。",
  "sustain": "sus-（下から）＋ tain（支える）で「下支えして持続させる」。sustainable（持続可能な）の動詞形で、経済成長や関係を「維持する」文脈で使われる。",
  "circulate": "circle（円）と同語源で「ぐるぐる回す」。社内メールや会議で circulate a memo（社内報・メモを回覧する）のコロケーションが定番。",
  "steward": "古英語の「家の番人」が語源。飛行機の客室乗務員のほか、近年では環境や共有資源を大切に守る「管理責任者・世話人」の意味でも用いられる。",
  "grassroots": "「草の根」の文字通り、一般市民や現場レベルから自然発生した活動を表す。grassroots campaign（市民運動）のように名詞の前で形容詞的に使われる。",
  "premium": "名詞では pay a premium（割増料金を払う）や insurance premium（保険料）、形容詞では premium quality（高級な）と品詞ごとの意味に注意。",
  "cut out the middleman": "middleman（中間業者）を cut out（切り捨てる）で「直接取引して中間マージンを省く」。直販（direct sales）やオンライン通販の利点として頻出。",
  "quaint": "古風で味わい深い魅力を褒めるポジティブな表現。旅行や観光案内の文脈で quaint village（趣のある村）や quaint hotel のように頻出。",
  "mainstream": "main（主な）＋ stream（流れ）で「時代の本流」。become mainstream（主流になる、広く定着する）の形で新技術や商品動向の文脈によく使われる。",
  "transform into": "trans-（越えて別の状態へ）＋ form（形）。店舗改装や再開発の文脈で、be transformed into ...（〜へと姿を変える）の受動態が定番。",
  "outlast": "接頭辞 out-（〜を超える）＋ last（続く）で「〜よりも長持ちする」。outnumber（数で上回る）など out- を冠する他動詞の仲間。",
  "within reach of": "物理的に「手が届く距離」のほか、within reach of customers（手が届く手頃な価格）のように価格や目標が達成圏内にある比喩でもよく使われる。",
  "synchronized": "syn-（共に）＋ chron（時）で「時間を一致させた」。ITでのデータ同期だけでなく、作業やスケジュールが完全に連動している状態を表す。",
  "amplified": "ample（十分な、広い）と同語源で「大きくされた」。音響機器の拡声だけでなく、効果やリスクが「増幅された・大きくなった」文脈でも使われる。",
  "curfew": "フランス語の「火を覆う（消火令）」が語源。寮や宿泊施設の「門限」のほか、自治体が定める夜間の「外出禁止令」や営業・騒音の「規制時間」を指す。",
  "selection": "se-（離して）＋ lect（選ぶ）が語源。「選択」だけでなく、小売店や通販の a wide selection of ...（豊富な品揃え）のフレーズが超頻出。",
  "rotate": "ラテン語の「車輪（rota）」が語源。回転するだけでなく、人事や当番などで「順番に交代する」意味があり、rotate shifts（交替勤務）などで頻出。",
  "aim to do": "後ろに to不定詞を取って「〜することを目指す」。前置詞を使う aim at -ing や、受動態の be aimed at（〜向けである）との語法の使い分けがポイント。",
  "distributor": "dis-（あちこちへ）＋ tribute（割り振る）で「商品を流通・分配する業者」。manufacturer（製造元）と retailer（小売店）の仲介役として頻出。",
  "liability insurance": "liable(法的責任がある)の名詞形liabilityにinsuranceがついた語。契約書や工事・イベントの要件通知で、損害賠償に備えるliability insurance(賠償責任保険)として登場する。",
  "margin": "「余白」が原義だが、ビジネスでは利益の余裕を表す「利幅」として頻出。profit margin(利益率)やoperating margin(営業利益率)のほか、thin/narrow marginの形でよく使われる。",
  "dictate": "dic-(言う)が語源で「口述する」から「指図する・左右する」。TOEICでは人が命令するだけでなく、市場動向や契約条件が方針を「決定づける」意味でdictate termsなどの形で使われる。",
  "inherently": "in-(中に)+here(くっつく)で「生まれつき内在して」。リスクや安全性の議論でinherently risky(本質的に危険な)のように形容詞を直前から修飾する形で現れる。",
  "discourage": "dis-(否定)+courage(勇気)で「勇気を失わせる」。語法が重要で、discourage 人 from doing(人に〜するのを思いとどまらせる)の型が空所補充などで狙われやすい。",
  "be fixated on": "fix(固定する)から、視線や関心が1点に固定された状態を表す。前置詞onとセットで用いられ、特定の数値や目標達成に「執着している・過度に気を取られている」文脈で登場する。",
  "analyst": "動詞analyze(分析する)の派生語で専門分析者。market analyst(市場アナリスト)やfinancial analyst(証券・財務アナリスト)のように、専門領域と組み合わさった肩書で頻出。",
  "gently used": "gently(優しく)扱われたことから、中古品売買の告知文で「丁寧に使われた・状態の良い中古の」を指す表現。gently used itemsやgently used clothingのように名詞の前で使われる。",
  "trade-in": "古い品を店舗に渡し(in)、新しい商品と交換(trade)する仕組み。家電量販店やカーディーラーの広告でtrade-in program(下取り制度)やtrade-in value(下取り査定額)として頻出。",
  "resale": "re-(再び)+sale(販売)で「再販売・転売」。名詞のresale value(再販価値・中古査定額)やfor resale(転売目的で)のフレーズが、仕入れや機材の売却案内でよく登場する。",
  "salvageable": "salvage(廃品・沈没船を救出する)+-able(できる)から「再利用可能な」。水害後の機器復旧や電子ゴミ削減の記事で、少し手を加えれば「直して使える」状態を表す。",
  "coordinator": "co-(共に)+ordinate(順序立てる)で「全体の調和を取る人」。project coordinatorやevent coordinatorのように、部署間や外部との連絡・折衝を担う役職名として頻出。",
  "hurdle": "陸上競技の障害物から「乗り越えるべき困難」。ビジネスではovercome hurdles(障害を克服する)やface hurdles(壁に直面する)のように動詞との組み合わせで出やすい。",
  "lean toward": "lean(体を傾ける)から「意見や方針が傾く」。lean toward doingまたは名詞の形で「〜を支持・選択する傾向がある」を表し、委員会や取締役会の選考議論で重宝される。",
  "sponsorship": "sponsorに立場・状態を表す接尾辞-shipがついた語。催し物の告知文でcorporate sponsorship(企業の協賛)やunder the sponsorship of(〜の主催・協賛で)の形が定番。",
  "partnership": "partnerに-shipがついた語で「提携関係」。企業の提携ニュースでform a partnership with(〜と提携を結ぶ)やin partnership with(〜と共同で)のフレーズが定番。",
  "roster": "元は軍の当番表で、ビジネスでは「名簿・登録者一覧」。roster of speakers(登壇者名簿)やduty roster(当番表)のように、特定の役割を持つメンバー一覧を指す。",
  "municipal": "ラテン語municipium(自治都市)が語源。市政や地方公共団体の告知で、municipal government(自治体・市当局)やmunicipal grant(市からの助成金)などの硬い表現で現れる。",
  "balance training": "balance(平衡感覚)+training(訓練)。企業の健康増進プログラムや地域の体操教室の告知チラシで、高齢者の転倒予防などを目的とした運動講座の名称として見かける。",
  "retiree": "retire(退職する)に受動的な人を表す接尾辞-eeがついた形。年金・健康保険の通知や福利厚生の記事で、eligible retirees(対象となる退職者)のように資格要件と共に出やすい。",
  "rewrite the script": "「台本を書き直す」から転じ、従来の常識や業界の決まりきったやり方を抜本的に覆す比喩表現。革新的な配送モデルや新ビジネスの手法を取り上げた特集記事で見られる。",
  "chore": "household chores(家事)で知られるが、職場での退屈な雑用も指す。daily choresやa tedious chore(面倒な雑務)の形で、作業の自動化や効率化を促す文脈で使われる。",
  "unthinkable": "un-(否定)+think(考える)+-able(可能)で「想像もできない」。previously unthinkable(以前は考えられなかった)のように副詞とセットで社会や事業環境の急変を語る際に出る。",
  "resent": "re-(強意)+sent(感じる)から「憤る・快く思わない」。resent doing(〜するのを不満に思う)と後ろに動名詞を取る語法が重要。名詞形resentment(憤り)も頻出。",
  "distinctive": "distinct(明瞭に区別できる)+-ive(性質)で「一目で他と区別できる独特の」。distinctive feature(独特の特徴)やdistinctive designのように製品の特長アピールでよく使われる。",
  "friction": "物理の「摩擦」から人間関係の「軋轢・衝突」。部署間の対立を描く文脈でcreate friction between(〜の間で摩擦を生む)やreduce friction(摩擦を減らす)の動詞と共に使われる。",
  "gentle": "ラテン語の「家柄が良い」から「穏やかな・優しい」。運動や健康関連の文脈でgentle on joints(関節に優しい)やgentle exercise(負荷の軽い運動)のように体に負担が少ない意味で使われる。",
  "rally": "スポーツの「ラリー(打ち合い)」に加え、TOEICの市況ニュースでは自動詞で「相場が反発する」、名詞で「回復」の意味が極めて重要。stocks rallied(株価が反発した)の形で頻出。",
  "spark": "名詞「火花」から転じて動詞で「火を付ける・引き起こす」。spark interest(関心を喚起する)やspark debate(議論を巻き起こす)など、感情や反応を目的語に取るのが定番。",
  "real estate": "real(動かせない・実体の)+estate(財産)で「不動産」。real estate agent(不動産業者)やcommercial real estate(商業不動産)のように物件広告やオフィス移転の記事で頻出。",
  "hot-desking": "潜水艦などで寝台を交代で使った hot-bunking に由来し、固定席を持たない勤務形態を指す。オフィスの省スペース化やリモートワークとの併用を巡る社内通知で登場する。",
  "selective": "動詞 select に形容詞語尾 -ive が付いた語。be selective about ...（〜を厳選する・選り好みする）のように前置詞 about と結びつく語法がポイント。",
  "communal": "common（共通の）と同語源で「特定の集団で共有する」を表す。communal kitchen（共同キッチン）や communal area（共用部）の形で施設案内に頻出。",
  "zoning": "土地を特定の目的（商業・住宅・工業など）ごとに区分すること。TOEICでは zoning laws や zoning regulations（都市計画の用途地域規制）の形で出店計画の話題に登場する。",
  "mortgage": "mort（死）+ gage（担保）が原義で「返済終了まで縛られる担保」に由来。take out a mortgage（ローンを組む）や mortgage rate（金利）の形で頻出。t は発音しない点にも注意。",
  "midway": "mid（中間）+ way（道）から「道半ばで」を意味する。midway through the project（プロジェクトの途中で）のように through とセットで期間・過程の半ばを表す表現が多い。",
  "troubleshoot": "trouble（問題）を shoot（撃ち落とす）が原義。ITや機械のエラー原因を突き止めて解決する文脈で使われ、説明書にある troubleshooting guide（故障対応手順）も頻出。",
  "unattended": "un-（否定）+ attend（世話をする・注意を払う）から「見守る人がいない」を意味する。空港や駅の案内文で leave baggage unattended（手荷物を放置する）の形で頻出。",
  "spool": "糸・針金・フィルムなどを巻き付ける円筒状の枠（ボビン）。TOEICでは a spool of cable（ケーブル巻き）や製造・印刷現場の消耗品交換の文脈で登場する。",
  "hotline": "緊急時に即座に繋がる直通電話が原義。TOEICでは customer service hotline（顧客サポート窓口）や 24-hour hotline（24時間受付窓口）の形で社内外の問い合わせ先として頻出。",
  "overflow": "over-（超えて）+ flow（流れる）で許容量を超えること。TOEICでは overflow parking（満車時の臨時駐車場）や overflow crowd（収容人数を超えた観客）のように名詞の前で限定的に使われやすい。",
  "budget-conscious": "budget（予算）+ conscious（意識した）の複合形容詞。budget-conscious consumers（節約志向の消費者）や travelers の形で、格安プランや割引キャンペーンの対象読者として登場する。",
  "approachable": "approach（近づく）+ -able（できる）から「話しかけやすい・親しみやすい」を表す。人事評価や送別メッセージで、上司の人柄を「気さくで相談しやすい（very approachable）」と評する文脈で頻出。",
  "breeder": "動詞 breed（品種改良する・繁殖させる）に人を表す -er が付いた語。動物や植物の生産・繁殖業者を指し、reputable breeder（評判の良い業者）などの修飾を伴って使われることが多い。",
  "shelter": "風雨や危険から身を守る避難所・保護施設。TOEICでは animal shelter（動物保護施設）への寄付やボランティア募集、緊急時の避難場所（emergency shelter）の案内で登場する。",
  "on average": "「平均して・概して」を表す頻出成句で、文頭・文末や文中に挿入される。前置詞 on を用いる点と、具体的な数値を続ける an average of 100 people（平均100人）との構文の違いに注意。",
  "take advantage of ~": "好機や特典を「うまく生かす・利用する」という定番フレーズ。TOEICの広告や案内メールで take advantage of this special offer（この特別割引を利用する）の形で頻出。",
  "enroll in ~": "en-（中へ）+ roll（名簿）で「名簿に名前を載せる」が原義。enroll in a seminar / program のように前置詞 in と組み合わせて「講座や制度に加入・登録する」文脈で非常によく出る。",
  "loyalty program": "loyal（忠実な）顧客を増やすための「ポイント還元・優待制度」。小売店やホテル、航空会社のマイレージなど、リピーター向け会員特典の案内文（Part 7）で頻出するビジネス用語。",
  "retailer": "re-（再び）+ tailler（切り分ける）で「小分けにして売る人＝小売店」。対義語の wholesaler（卸売業者）と対比され、online retailer（ネット通販業者）などの形で頻出。",
  "peak": "山の頂から転じて「最盛期の・混雑時の」を意味する限定用法の形容詞。peak hours（ラッシュ時・ピーク時間）や peak season（繁忙期）の形で、交通やホテルの料金案内に頻出。",
  "counterfeit": "counter-（対抗して）+ feit（作る）が原義で、本物に似せて作った偽造品を指す。counterfeit goods（模倣品）や counterfeit currency（偽札）の形で知的財産や税関の話題に出る。",
  "amplify": "ample（十分な・広い）+ -fy（〜にする）で「拡大・増幅する」。音響機器の amplifier（アンプ）と同根で、音だけでなく amplify the impact（影響を強める）のように抽象的な拡大にも使う。",
  "scarcity": "形容詞 scarce（乏しい・稀な）の名詞形。scarcity of skilled labor（熟練労働者の不足）や water scarcity（水不足）のように shortage より硬い表現としてビジネス報告書で使われる。",
  "systematically": "system（体系）に形容詞語尾 -atic と副詞語尾 -ally が付いた語。「行き当たりばったりではなく順序立てて」を意味し、review ... systematically（体系的に見直す）などの動詞修飾で頻出。",
  "overlapping": "over-（上に）+ lap（重なる）の現在分詞形容詞。日程や役割の一部が重なることを指し、overlapping schedules（スケジュールの重複）や overlapping shifts（重複勤務シフト）の形でよく使われる。",
  "waiting list": "定員オーバー時に空きを待つ名簿。be on the waiting list（キャンセル待ち状態である）や put ... on the waiting list（キャンセル待ちに登録する）の熟語が研修や航空券予約で定番。",
  "undo": "un-（逆動作）+ do（する）で「行ったことを取り消す・元に戻す」。パソコンの「元に戻す」でおなじみだが、TOEICでは undo years of effort（長年の努力を台無しにする）のような抽象的用法で出る。",
  "off-peak": "off-（外れて）+ peak（頂点）で「混雑時間や最盛期を外れた」を意味する。off-peak travel（閑散期の旅行）や off-peak rates（割引料金）のように、交通機関や宿泊施設の割安プランの文脈で頻出。",
  "designation": "de-（明確に）+ sign（印をつける）+ -ation で「公式に指定・命名すること」。動詞 designate（指定する）の名詞形で、designation as ...（〜としての公式指定）や役職・肩書を表す際に使われる。",
  "constellation": "con-(共に)+stella(星)で「星の集まり」が原義。TOEICではプラネタリウムの案内や、比喩的に「一連の集まり」として登場することがある。",
  "gathering": "動詞gather（集まる）の名詞形。TOEICではsocial gathering（親睦会）やinformal gatheringの形で、社内イベントや地域行事の案内に頻出。",
  "high-profile": "profile（世間の注目度）が高いことから「人目を引く、著名な」。high-profile client（大口顧客）やhigh-profile caseなどの形でビジネス記事に登場する。",
  "burden": "古英語で「荷を運ぶこと」に由来。TOEICではfinancial burden（財政的負担）やease/reduce the burden（負担を減らす）の形でよく使われる。",
  "afloat": "a-(〜の状態で)+float(浮く)から「水に浮いて」。比喩的にkeep the business afloat（事業をなんとか維持する）やstay afloatの形で頻出。",
  "soundproofing": "sound（音）+proof（防ぐ）の動名詞。「防水（waterproof）」と同様の構成。TOEICではオフィスの改装やスタジオの設備案内で登場する。",
  "classify": "class（等級）+-ify（〜にする）で「分類する」。TOEICではbe classified as ...（〜に分類される）のように前置詞asを伴う受動態でよく使われる。",
  "trace back to": "trace（追跡する）+back to（〜まで戻って）。「起源が〜にさかのぼる」の意味で、企業や製品の歴史・開発秘話を語るPart 7の社内報や紹介記事でよく使われる。",
  "amateur": "ラテン語amare（愛する）に由来し「愛好家・好きで行う人」が原義。TOEICではprofessional（プロの）の対比として、コンテストや社内サークルの案内に出る。",
  "frustrated": "人が主語のときはfrustrated with/at ...（〜に苛立ちを感じる）、物事が主語ならfrustrating（もどかしい）となる使い分けがPart 5の文法問題で問われやすい。",
  "cross-department": "cross-（横断する）+department（部署）。cross-department collaboration（部署間連携）やproject teamの形で、組織改編や全社的プロジェクトの社内連絡に登場する。",
  "overwhelming": "over-（上から）+whelm（覆う）で「波が押し寄せて圧倒する」。TOEICではoverwhelming response（大反響）やoverwhelming supportの形でよく使われる。",
  "in advance": "文末に置く副詞句。book/pay/register in advance（事前に予約／支払／登録する）のほか、three days in advance（3日前に）のように期間を前に置く形も頻出。",
  "volunteer": "ラテン語の「自発的な意志」が語源。名詞（志願者）だけでなく、動詞としてvolunteer to do（自発的に〜を引き受ける）の形で使われる点も押さえておきたい。",
  "respond to": "re-（返し）+spond（答える）。自動詞なのでrespond to an inquiry（問い合わせに対応する）とtoが必要。直接目的語を取る他動詞answerとの違いがPart 5の急所。",
  "appeal": "「呼びかける」が原義。名詞ではbroad appeal（幅広い訴求力）、動詞ではappeal to customers（顧客の心に響く）のように前置詞toを伴う形がよく使われる。",
  "redelivery": "re-（再び）+delivery（配達）。TOEICでは荷物の配送状況を扱うPart 7で、request a redelivery（再配達を依頼する）や指定日時の連絡で頻出。",
  "infrastructure": "infra-（下に）+structure（構造）で「下部構造・基盤」。TOEICではtransport infrastructure（交通網）やIT infrastructureの文脈でよく登場する。",
  "scout": "古フランス語の「聴く・見張る」に由来。TOEICではscout a location（新店舗などの候補地を下見・選定する）のように、出店計画やロケ地探しの文脈で見られる。",
  "plot": "物語の「あらすじ」以外に、TOEICではa plot of land（一区画の土地）やgarden plot（菜園区画）のように不動産や農園の区画の意味で出やすい。",
  "nonprofit": "non-（非）+profit（利益）。TOEICでは形容詞「非営利の」のほか、名詞で「非営利団体（NPO）」そのものを指し、チャリティや寄付の文脈で頻出。",
  "flagship": "司令官が乗る「旗艦」が原義。TOEICではflagship store（旗艦店・本店）やflagship product（看板主力製品）のように、ブランドの象徴を表す修飾語として頻出。",
  "wedge": "名詞「くさび」から転じて動詞「押し込む、挟んで固定する」。wedge A between B（AをBの間に固定する）の形で、家具の設置やDIYの指示文に登場する。",
  "security deposit": "security（担保）+deposit（預け金）で「敷金・保証金」。TOEICではオフィスや部屋の賃貸契約でrefundable security deposit（返金可能な敷金）などの形で頻出。",
  "adhesive": "ad-（〜へ）+here（くっつく）から派生。形容詞「粘着性の（adhesive tape）」と名詞「接着剤」の両方で使われ、オフィス備品や修理の文脈で見られる。",
  "residue": "re-（後ろに）+sidere（残る）から「あとに残るもの」。TOEICではテープや洗剤の説明でleave no residue（跡やカスを残さない）という形でよく使われる。",
  "impractical": "否定のim- + practical（実用的な）。計画や提案のフィードバックで、highly impractical（極めて非現実的）のように予算・時間面で実行が難しい場面に登場する。",
  "abandon": "「支配権を放棄する」が原義。TOEICのビジネス文脈では人を捨てる意味ではなく、abandon a plan/project（計画・事業を中止・断念する）の形でよく使われる。",
  "advertise": "ad-（〜へ）+vert（向ける）で「人々の注意を向けさせる」。製品の宣伝だけでなく、advertise an opening/job（求人を告知する）の文脈もTOEICでは頻出。",
  "obstacle": "ob-（前に）+stare（立つ）で「目の前に立ちはだかるもの」。TOEICではovercome an obstacle（困難・障害を克服する）の組み合わせが頻出。",
  "loyalty": "loyal（忠実な）の名詞形。TOEICでは customer loyalty（顧客の愛着）や loyalty program（ポイント会員制度）の形で頻出で、rの royalty（印税・王族）との混同に注意。",
  "continuously": "con-(完全に)+tin(保つ)で「途切れず保つ」。TOEICでは continually（断続的な繰り返し）と違い「絶え間なく続く」動作を表し、Part 5の品詞問題で continuous との区別が問われる。",
  "pending": "pend(ぶら下がる)が原義で、決着がつかず宙づりの状態を表す。TOEICでは pending approval（承認待ち）の形や、pending completion（完了まで）など前置詞的な用法で出やすい。",
  "navigate": "navis(船)+agere(導く)が原義。TOEICでは物理的な移動だけでなく、navigate the website（ウェブサイトを操作・閲覧する）のようにITツールの画面操作の文脈で頻出。",
  "dispatch": "send のフォーマルな語で「急ぎ差し向ける」意。TOEICでは dispatch a technician（技術者を急派する）のように、機器修理や現場トラブルへの人員派遣の文脈でよく見られる。",
  "wearable": "wear(身につける)+-able(できる)の構造。TOEICでは wearable device（装着型端末）や wearable technology の形で、新製品のリリースやヘルスケア事業の記事によく登場する。",
};
